INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('pp-preconception-checkup', 'article', 'scientific', 'shared', 'important', 'guideline', '🩺', '{"en":"The pre-pregnancy check-up: what to test","bn":"গর্ভধারণের আগে চেকআপ: কী কী পরীক্ষা করাবেন"}'::jsonb, '{"en":"A visit to a doctor a few months before you try for a baby finds problems early, while there is still time to fix them.","bn":"সন্তান নেওয়ার চেষ্টা শুরুর কয়েক মাস আগে একবার ডাক্তার দেখালে সমস্যা আগেভাগে ধরা পড়ে, আর ঠিক করার সময়ও হাতে থাকে।"}'::jsonb, '{"en":"## Why go before pregnancy\n\nMany of the baby''s organs form in the first weeks, often before a woman knows she is pregnant. A check-up three to six months before you start trying gives time to treat anaemia, control blood sugar or blood pressure, update vaccines and start folic acid. Go together if you can: some tests are for both partners.\n\n## What the doctor will ask\n\n- Your periods, past pregnancies, miscarriages or operations\n- Long-term conditions such as diabetes, high blood pressure, thyroid disease, epilepsy or asthma\n- Every medicine you take, including herbal or homeopathic ones\n- Illnesses that run in either family, such as thalassaemia\n- Tobacco, jarda, gul or betel nut use\n\n## Common tests\n\n- **Blood group and Rh** for both partners\n- **Complete blood count (CBC)** to look for anaemia\n- **Thalassaemia carrier test** (haemoglobin electrophoresis), especially if the CBC shows small red cells\n- **Blood sugar**\n- **Blood pressure and weight**\n- **Hepatitis B, syphilis and HIV** tests, so that treatment can protect the baby if needed\n- **Urine test**\n- **Thyroid test** if the doctor advises\n\n## Vaccines\n\nBring your vaccination card and check your Td (tetanus–diphtheria) doses. If you are not protected against rubella, the doctor may give the MR vaccine; you will then be asked to wait about a month before getting pregnant. Hepatitis B vaccine may be advised if you are not protected.\n\n## Other things to sort out\n\n- A dental check, since gum and tooth problems are easier to treat now\n- Changing any medicine that is not safe in pregnancy, only with your doctor''s advice\n- Starting folic acid every day\n\nYou can get this check-up at an Upazila Health Complex, a Mother and Child Welfare Centre or with any qualified doctor. Keep all reports in one folder; you will need them again in pregnancy.","bn":"## কেন গর্ভধারণের আগেই\n\nশিশুর অনেক অঙ্গ তৈরি হয় প্রথম কয়েক সপ্তাহে, প্রায়ই মা টের পাওয়ার আগেই। চেষ্টা শুরুর ৩ থেকে ৬ মাস আগে চেকআপ করালে রক্তস্বল্পতার চিকিৎসা, ডায়াবেটিস বা উচ্চ রক্তচাপ নিয়ন্ত্রণ, টিকা হালনাগাদ আর ফলিক অ্যাসিড শুরু করার সময় পাওয়া যায়। সম্ভব হলে স্বামী-স্ত্রী একসাথে যান — কিছু পরীক্ষা দুজনেরই লাগে।\n\n## ডাক্তার যা জানতে চাইবেন\n\n- মাসিক, আগের গর্ভধারণ, গর্ভপাত বা অপারেশনের কথা\n- দীর্ঘমেয়াদি রোগ — ডায়াবেটিস, উচ্চ রক্তচাপ, থাইরয়েড, মৃগী বা হাঁপানি\n- যত ওষুধ খান, ভেষজ বা হোমিওপ্যাথিসহ\n- পরিবারে চলে আসা রোগ, যেমন থ্যালাসেমিয়া\n- তামাক, জর্দা, গুল বা সুপারি খাওয়ার অভ্যাস\n\n## সাধারণ পরীক্ষাগুলো\n\n- **রক্তের গ্রুপ ও আরএইচ (Rh)** — দুজনেরই\n- **সিবিসি (CBC)** — রক্তস্বল্পতা আছে কিনা দেখতে\n- **থ্যালাসেমিয়া বাহক পরীক্ষা** (হিমোগ্লোবিন ইলেকট্রোফোরেসিস), বিশেষ করে সিবিসিতে লোহিত কণিকা ছোট দেখালে\n- **রক্তে শর্করা**\n- **রক্তচাপ ও ওজন**\n- **হেপাটাইটিস বি, সিফিলিস ও এইচআইভি** — ধরা পড়লে চিকিৎসা দিয়ে শিশুকে সুরক্ষা দেওয়া যায়\n- **প্রস্রাব পরীক্ষা**\n- ডাক্তার বললে **থাইরয়েড পরীক্ষা**\n\n## টিকা\n\nটিকা কার্ড সাথে নিন, টিডি (টিটেনাস-ডিপথেরিয়া) টিকার কয়টি ডোজ হয়েছে দেখে নিন। রুবেলার সুরক্ষা না থাকলে ডাক্তার এমআর (MR) টিকা দিতে পারেন; তখন প্রায় এক মাস গর্ভধারণ থেকে বিরত থাকতে বলা হবে। সুরক্ষা না থাকলে হেপাটাইটিস বি টিকাও দেওয়ার পরামর্শ আসতে পারে।\n\n## আরও যা গুছিয়ে নেবেন\n\n- দাঁতের চেকআপ — দাঁত ও মাড়ির সমস্যা এখনই সারানো সহজ\n- গর্ভাবস্থায় অনিরাপদ কোনো ওষুধ খেলে তা বদলানো — শুধু ডাক্তারের পরামর্শে\n- প্রতিদিন ফলিক অ্যাসিড শুরু করা\n\nউপজেলা স্বাস্থ্য কমপ্লেক্স, মা ও শিশু কল্যাণ কেন্দ্র বা যেকোনো নিবন্ধিত ডাক্তারের কাছে এই চেকআপ করা যায়। সব রিপোর্ট একটি ফাইলে গুছিয়ে রাখুন; গর্ভাবস্থায় আবার লাগবে।"}'::jsonb, '{}'::jsonb, 4, NULL, -280, '{}'::text[], 'any', ARRAY['preconception', 'checkup', 'blood test', 'vaccines', 'planning']::text[], false, 'in_review'::lp_review_status, 2001),
  ('pp-folic-acid', 'article', 'scientific', 'shared', 'important', 'guideline', '💊', '{"en":"Folic acid: start before pregnancy","bn":"ফলিক অ্যাসিড: গর্ভধারণের আগেই শুরু করুন"}'::jsonb, '{"en":"A small daily folic acid tablet, started before pregnancy, lowers the chance of serious birth defects of the baby''s brain and spine.","bn":"গর্ভধারণের আগে থেকে প্রতিদিন একটি ছোট ফলিক অ্যাসিড ট্যাবলেট খেলে শিশুর মস্তিষ্ক ও মেরুদণ্ডের মারাত্মক জন্মত্রুটির ঝুঁকি কমে।"}'::jsonb, '{"en":"## What folic acid does\n\nFolic acid is a B vitamin (folate). The baby''s brain and spinal cord grow from a small tube that closes in the first month after conception — usually before a missed period is even noticed. Enough folate at that time helps the tube close properly and lowers the risk of neural tube defects such as spina bifida.\n\n## When and how much\n\n- WHO advises a daily folic acid tablet for every woman who may become pregnant, from the time she starts trying until 12 weeks of pregnancy.\n- The usual dose is 400 micrograms (0.4 mg) once a day, as your health worker advises.\n- Some women need a higher dose — for example, if a previous baby had a neural tube defect, or if she has diabetes or takes medicine for epilepsy. Only a doctor should decide this.\n- Ideally start at least one month before trying. If you are already pregnant and have not started, start today.\n- After 12 weeks, antenatal care usually continues with iron–folic acid tablets.\n\n## Food helps too\n\nFolate is found in dark green leafy vegetables (palong shak, lal shak, pui shak, kolmi shak), dal, chickpeas, beans, eggs, oranges and other fruits. Cook vegetables lightly, because long boiling destroys folate. Food alone is usually not enough at this stage, so take the tablet as well.\n\n## Making it a habit\n\n- Keep the strip next to your toothbrush or phone charger.\n- Take it at the same time every day.\n- If you miss one, take the next one as usual. Do not take two to catch up.\n- Store all tablets where children cannot reach them.\n\n## For the partner\n\nRemind her kindly, buy refills before the strip runs out, and eat the same healthy meals together. Planning a baby is a shared job.","bn":"## ফলিক অ্যাসিড কী করে\n\nফলিক অ্যাসিড একটি বি ভিটামিন (ফোলেট)। শিশুর মস্তিষ্ক ও সুষুম্নাকাণ্ড তৈরি হয় একটি ছোট নল থেকে, যা গর্ভধারণের প্রথম মাসেই বন্ধ হয়ে যায় — সাধারণত মাসিক বন্ধ হয়েছে বোঝার আগেই। ওই সময় শরীরে যথেষ্ট ফোলেট থাকলে নলটি ঠিকভাবে বন্ধ হয়, আর স্পাইনা বিফিডার মতো নিউরাল টিউব ত্রুটির ঝুঁকি কমে।\n\n## কখন, কতটুকু\n\n- বিশ্ব স্বাস্থ্য সংস্থা (WHO) বলে, গর্ভধারণ করতে পারেন এমন প্রত্যেক নারী চেষ্টা শুরুর সময় থেকে গর্ভাবস্থার ১২ সপ্তাহ পর্যন্ত প্রতিদিন ফলিক অ্যাসিড ট্যাবলেট খাবেন।\n- সাধারণ মাত্রা দিনে একবার ৪০০ মাইক্রোগ্রাম (০.৪ মিলিগ্রাম) — স্বাস্থ্যকর্মীর পরামর্শমতো।\n- কারো কারো বেশি মাত্রা লাগে — যেমন আগের সন্তানের নিউরাল টিউব ত্রুটি থাকলে, ডায়াবেটিস থাকলে বা মৃগীর ওষুধ খেলে। এটা শুধু ডাক্তারই ঠিক করবেন।\n- সম্ভব হলে চেষ্টা শুরুর অন্তত এক মাস আগে শুরু করুন। গর্ভধারণ হয়ে গেছে অথচ শুরু করেননি? আজই শুরু করুন।\n- ১২ সপ্তাহের পর গর্ভকালীন সেবায় সাধারণত আয়রন-ফলিক অ্যাসিড ট্যাবলেট চলতে থাকে।\n\n## খাবারও কাজে আসে\n\nগাঢ় সবুজ শাক (পালং, লাল শাক, পুঁই, কলমি), ডাল, ছোলা, শিম-বরবটি, ডিম, কমলা ও অন্যান্য ফলে ফোলেট আছে। সবজি বেশিক্ষণ সেদ্ধ করলে ফোলেট নষ্ট হয়, তাই হালকা রান্না করুন। এই সময় শুধু খাবারে সাধারণত যথেষ্ট হয় না, তাই ট্যাবলেটও খান।\n\n## অভ্যাস গড়ে তুলুন\n\n- ট্যাবলেটের পাতা টুথব্রাশ বা ফোনের চার্জারের পাশে রাখুন।\n- প্রতিদিন একই সময়ে খান।\n- একদিন ভুলে গেলে পরদিন স্বাভাবিক একটিই খান, দুটি একসাথে নয়।\n- সব ওষুধ শিশুদের নাগালের বাইরে রাখুন।\n\n## স্বামীর জন্য\n\nভালোবেসে মনে করিয়ে দিন, ট্যাবলেট শেষ হওয়ার আগেই কিনে আনুন, আর একসাথে একই পুষ্টিকর খাবার খান। সন্তানের পরিকল্পনা দুজনের কাজ।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['folic acid', 'folate', 'neural tube', 'supplements', 'planning']::text[], false, 'in_review'::lp_review_status, 2002),
  ('pp-healthy-weight-before-pregnancy', 'article', 'scientific', 'shared', 'routine', 'guideline', '🥗', '{"en":"Healthy weight, food and activity before pregnancy","bn":"গর্ভধারণের আগে সুস্থ ওজন, খাবার ও চলাফেরা"}'::jsonb, '{"en":"A healthy weight and a varied diet before pregnancy make it easier to conceive and safer for mother and baby. Small steps now already help.","bn":"গর্ভধারণের আগে ওজন ঠিক রাখা আর নানা রকম খাবার খাওয়া গর্ভধারণ সহজ করে, মা ও শিশুকেও নিরাপদ রাখে। এখনকার ছোট পদক্ষেপও কাজে দেয়।"}'::jsonb, '{"en":"## Why weight matters\n\nBeing very thin or carrying a lot of extra weight can make periods irregular and conceiving harder. In pregnancy, being underweight raises the chance of a small baby, while being overweight raises the chance of gestational diabetes, high blood pressure and a difficult birth. You do not need a perfect body; small changes before pregnancy already help.\n\n## Know your starting point\n\nAsk your health worker to check your weight, height and BMI (body mass index). A BMI between 18.5 and 24.9 is usually called healthy. For South Asian people, doctors often watch for health risks at a lower BMI, so ask what is right for you. Also get checked for anaemia, which is common among women in Bangladesh.\n\n## Eat a varied plate\n\n- Rice, atta roti or other grains, with some whole grains\n- Dal, beans, fish, eggs, chicken or meat\n- Plenty of vegetables, including dark green shak and yellow-orange ones like mishti kumra and carrot\n- Seasonal fruits such as guava, amloki, ripe papaya, banana or mango\n- Milk, yogurt, or small fish eaten with their bones, for calcium\n- Iodised salt, in small amounts\n\nCut back on sugary drinks, sweets, fried snacks and fast food. If you are underweight, add an extra small meal or a nutritious snack, such as an egg, a handful of nuts or a bowl of khichuri.\n\n## Move every day\n\nWHO recommends that adults do at least 150 minutes of moderate activity a week — for example, a brisk 30-minute walk on five days. Walking, cycling, housework at a good pace and stretching all count. It is easier to keep going when you do it together.\n\n## Small changes that last\n\n- Aim for slow, steady change, not crash diets\n- Sleep seven to eight hours at night\n- Drink safe water; if you use a tube-well, make sure it has been tested for arsenic\n- For men too: a healthy weight, good food and no tobacco help sperm health\n\nIf you have diabetes, thyroid disease or irregular periods, ask your doctor for a plan before trying for a baby.","bn":"## ওজন কেন গুরুত্বপূর্ণ\n\nখুব রোগা হলে বা অনেক বেশি ওজন থাকলে মাসিক অনিয়মিত হতে পারে, গর্ভধারণও কঠিন হয়। গর্ভাবস্থায় ওজন কম থাকলে শিশু ছোট হয়ে জন্মানোর ঝুঁকি বাড়ে; আর ওজন বেশি থাকলে গর্ভকালীন ডায়াবেটিস, উচ্চ রক্তচাপ ও কঠিন প্রসবের ঝুঁকি বাড়ে। নিখুঁত শরীরের দরকার নেই — গর্ভধারণের আগে ছোট ছোট পরিবর্তনই উপকার করে।\n\n## আগে নিজের অবস্থা জানুন\n\nস্বাস্থ্যকর্মীকে দিয়ে ওজন, উচ্চতা ও বিএমআই (BMI) মাপিয়ে নিন। সাধারণত বিএমআই ১৮.৫ থেকে ২৪.৯ হলে স্বাস্থ্যকর ধরা হয়। দক্ষিণ এশিয়ার মানুষের ক্ষেত্রে ডাক্তাররা অনেক সময় আরও কম বিএমআই থেকেই ঝুঁকি খেয়াল করেন, তাই আপনার জন্য কোনটা ঠিক জেনে নিন। রক্তস্বল্পতাও পরীক্ষা করান — বাংলাদেশের নারীদের মধ্যে এটা বেশ সাধারণ।\n\n## থালায় নানা রকম খাবার\n\n- ভাত, আটার রুটি বা অন্য শস্য — কিছুটা লাল চাল বা লাল আটা\n- ডাল, শিমের বিচি, মাছ, ডিম, মুরগি বা মাংস\n- প্রচুর সবজি — গাঢ় সবুজ শাক আর মিষ্টিকুমড়া, গাজরের মতো হলুদ-কমলা সবজি\n- মৌসুমি ফল — পেয়ারা, আমলকী, পাকা পেঁপে, কলা বা আম\n- ক্যালসিয়ামের জন্য দুধ, দই বা কাঁটাসহ খাওয়া যায় এমন ছোট মাছ\n- আয়োডিনযুক্ত লবণ, অল্প পরিমাণে\n\nচিনি দেওয়া পানীয়, মিষ্টি, ভাজাপোড়া আর ফাস্ট ফুড কমান। ওজন কম হলে বাড়তি একটা ছোট খাবার বা পুষ্টিকর নাশতা যোগ করুন — যেমন একটা ডিম, এক মুঠো বাদাম বা এক বাটি খিচুড়ি।\n\n## প্রতিদিন নড়াচড়া\n\nবিশ্ব স্বাস্থ্য সংস্থা বলে, প্রাপ্তবয়স্কদের সপ্তাহে অন্তত ১৫০ মিনিট মাঝারি ধরনের শারীরিক কাজ করা উচিত — যেমন সপ্তাহে পাঁচ দিন ৩০ মিনিট করে জোরে হাঁটা। হাঁটা, সাইকেল চালানো, চটপটে ঘরের কাজ, হাত-পা টানটান করা — সবই এর মধ্যে পড়ে। দুজনে একসাথে করলে চালিয়ে যাওয়া সহজ হয়।\n\n## টেকসই ছোট পরিবর্তন\n\n- হঠাৎ কড়া ডায়েট নয়, ধীরে ধীরে স্থির পরিবর্তন\n- রাতে সাত-আট ঘণ্টা ঘুম\n- নিরাপদ পানি পান; টিউবওয়েলের পানি খেলে আর্সেনিক পরীক্ষা করা আছে কিনা নিশ্চিত হোন\n- পুরুষদের জন্যও: ঠিক ওজন, ভালো খাবার আর তামাক বাদ দিলে শুক্রাণু ভালো থাকে\n\nডায়াবেটিস, থাইরয়েড বা অনিয়মিত মাসিক থাকলে সন্তান নেওয়ার আগে ডাক্তারের কাছ থেকে একটা পরিকল্পনা নিয়ে নিন।"}'::jsonb, '{}'::jsonb, 4, NULL, -280, '{}'::text[], 'any', ARRAY['weight', 'bmi', 'diet', 'exercise', 'planning']::text[], false, 'in_review'::lp_review_status, 2003),
  ('pp-thalassaemia-carrier-screening', 'article', 'scientific', 'shared', 'important', 'consensus', '🩸', '{"en":"Thalassaemia carrier test for couples","bn":"দম্পতির থ্যালাসেমিয়া বাহক পরীক্ষা"}'::jsonb, '{"en":"Many healthy people in Bangladesh carry a thalassaemia gene without knowing it. A simple blood test before pregnancy tells a couple whether their child could be affected.","bn":"বাংলাদেশে অনেক সুস্থ মানুষ না জেনেই থ্যালাসেমিয়ার জিন বহন করেন। গর্ভধারণের আগে একটি সহজ রক্ত পরীক্ষায় জানা যায় সন্তানের ঝুঁকি আছে কিনা।"}'::jsonb, '{"en":"## What thalassaemia is\n\nThalassaemia is an inherited blood condition in which the body makes too little healthy haemoglobin. In Bangladesh, beta-thalassaemia and haemoglobin E (HbE) are both common. A child with thalassaemia major, or a severe form of HbE/beta-thalassaemia, may need blood transfusions for life.\n\n## A carrier is not ill\n\nA carrier (also called trait or minor) has one changed gene and one normal gene. Carriers are usually healthy, may have mild anaemia, and need no treatment. Most carriers do not know they are carriers. Being a carrier is nobody''s fault, and it does not stop anyone from marrying or having children.\n\n## Why test both partners\n\nA child gets one gene from each parent. If only one parent is a carrier, the child cannot have thalassaemia major. If both parents are carriers, then in each pregnancy there is:\n\n- a 1 in 4 chance the child has the serious form\n- a 2 in 4 chance the child is a healthy carrier\n- a 1 in 4 chance the child has neither\n\nThese chances are the same in every pregnancy.\n\n## The test\n\n- A **CBC** first: small red cells (low MCV or MCH) can be a clue.\n- **Haemoglobin electrophoresis** or **HPLC** confirms carrier status.\n\nThe best time is before marriage; the next best is before pregnancy. It needs doing only once in a lifetime. Iron deficiency can also make red cells small, so do not start iron tablets on your own because of a low result. Let the doctor read both reports.\n\n## If both of you are carriers\n\n- Meet a doctor or genetic counsellor together. You deserve time and full information.\n- Tests early in pregnancy can show whether the baby is affected. They are available at some specialised centres in Bangladesh; the doctor will explain timing, risks and costs.\n- Decisions are yours as a couple. Your family needs facts, not blame.\n\n## Tell your relatives\n\nIf you are a carrier, your brothers, sisters and cousins may be carriers too. Encourage them, gently, to get tested before their own marriages.","bn":"## থ্যালাসেমিয়া কী\n\nথ্যালাসেমিয়া একটি বংশগত রক্তের রোগ, যাতে শরীর যথেষ্ট সুস্থ হিমোগ্লোবিন তৈরি করতে পারে না। বাংলাদেশে বিটা-থ্যালাসেমিয়া আর হিমোগ্লোবিন ই (HbE) — দুটোই বেশ দেখা যায়। থ্যালাসেমিয়া মেজর বা ই-বিটা থ্যালাসেমিয়ার মারাত্মক ধরন নিয়ে জন্মানো শিশুর সারাজীবন রক্ত নিতে হতে পারে।\n\n## বাহক মানে রোগী নয়\n\nবাহকের (ট্রেইট বা মাইনর) একটি জিন পরিবর্তিত, আরেকটি স্বাভাবিক। বাহকেরা সাধারণত সুস্থ থাকেন, হালকা রক্তস্বল্পতা থাকতে পারে, চিকিৎসার দরকার হয় না। বেশিরভাগ বাহক জানেনই না যে তিনি বাহক। বাহক হওয়া কারো দোষ নয়, আর এতে বিয়ে বা সন্তান নেওয়াও আটকায় না।\n\n## কেন দুজনেরই পরীক্ষা\n\nশিশু বাবা-মা দুজনের কাছ থেকে একটি করে জিন পায়। শুধু একজন বাহক হলে সন্তানের থ্যালাসেমিয়া মেজর হতে পারে না। কিন্তু দুজনই বাহক হলে প্রতিটি গর্ভধারণে:\n\n- ৪ ভাগের ১ ভাগ সম্ভাবনা — সন্তানের মারাত্মক ধরন হবে\n- ৪ ভাগের ২ ভাগ সম্ভাবনা — সন্তান সুস্থ বাহক হবে\n- ৪ ভাগের ১ ভাগ সম্ভাবনা — সন্তানের কোনোটাই থাকবে না\n\nপ্রতিবার গর্ভধারণে এই সম্ভাবনা একই থাকে।\n\n## পরীক্ষাটি কী\n\n- প্রথমে **সিবিসি (CBC)**: লোহিত কণিকা ছোট হলে (MCV বা MCH কম) সন্দেহ হয়।\n- **হিমোগ্লোবিন ইলেকট্রোফোরেসিস** বা **এইচপিএলসি (HPLC)** দিয়ে বাহক কিনা নিশ্চিত হওয়া যায়।\n\nসবচেয়ে ভালো সময় বিয়ের আগে, তারপর গর্ভধারণের আগে। জীবনে একবার করলেই হয়। আয়রনের ঘাটতিতেও লোহিত কণিকা ছোট হয়, তাই রিপোর্টে কম দেখে নিজে থেকে আয়রন ট্যাবলেট শুরু করবেন না। দুটো রিপোর্টই ডাক্তারকে দেখান।\n\n## দুজনই বাহক হলে\n\n- দুজনে মিলে ডাক্তার বা জেনেটিক কাউন্সেলরের সাথে দেখা করুন। সময় নিয়ে পুরো তথ্য জানার অধিকার আপনাদের আছে।\n- গর্ভাবস্থার শুরুর দিকে পরীক্ষা করে জানা যায় গর্ভের শিশু আক্রান্ত কিনা। বাংলাদেশের কিছু বিশেষায়িত কেন্দ্রে এই পরীক্ষা হয়; কখন, কী ঝুঁকি, কত খরচ — ডাক্তার বুঝিয়ে বলবেন।\n- সিদ্ধান্ত আপনাদের দুজনের। পরিবারের দরকার তথ্য, দোষারোপ নয়।\n\n## আত্মীয়দের জানান\n\nআপনি বাহক হলে আপনার ভাই-বোন, চাচাতো-মামাতো ভাই-বোনেরাও বাহক হতে পারেন। নরমভাবে তাঁদেরও বিয়ের আগে পরীক্ষা করাতে উৎসাহ দিন।"}'::jsonb, '{}'::jsonb, 4, NULL, -280, '{}'::text[], 'any', ARRAY['thalassaemia', 'thalassemia', 'hbe', 'carrier', 'genetic', 'blood test']::text[], false, 'in_review'::lp_review_status, 2004),
  ('pp-blood-group-rh', 'article', 'scientific', 'shared', 'important', 'guideline', '🅾️', '{"en":"Blood group and Rh: why it matters","bn":"রক্তের গ্রুপ ও আরএইচ: কেন জানা জরুরি"}'::jsonb, '{"en":"Knowing both partners'' blood groups helps in an emergency, and an Rh-negative mother may need a protective injection to keep future babies safe.","bn":"দুজনের রক্তের গ্রুপ জানা থাকলে জরুরি অবস্থায় কাজে লাগে। আর মা আরএইচ নেগেটিভ হলে পরের সন্তানদের সুরক্ষায় একটি ইনজেকশন লাগতে পারে।"}'::jsonb, '{"en":"## Know your blood groups\n\nEveryone has a blood group (A, B, AB or O) and an Rh type (positive or negative) — for example, ''B positive'' or ''O negative''. Both partners should know theirs before pregnancy. If heavy bleeding happens around birth, the family will need donors with a matching group quickly.\n\n## What Rh-negative means\n\nMost people in Bangladesh are Rh-positive. If the mother is Rh-negative and the father is Rh-positive, the baby may be Rh-positive. If some of the baby''s blood enters the mother''s blood — at birth, or after a miscarriage, abortion, bleeding, a fall or some procedures — her body may make antibodies against Rh-positive blood.\n\nThe first baby is usually not affected. But in a later pregnancy these antibodies can cross the placenta and destroy the baby''s red blood cells. This can cause severe anaemia and jaundice in the baby (haemolytic disease of the newborn).\n\n## How it is prevented\n\nAn injection called anti-D (Rh immunoglobulin) stops the mother''s body making these antibodies. Your doctor will plan it. It is usually given:\n\n- during pregnancy, often in the last three months, as your doctor advises\n- within 72 hours after the birth, if the baby is Rh-positive\n- after any bleeding, miscarriage, abortion, ectopic pregnancy or injury to the belly\n\nAsk early where anti-D is available and what it costs, so you are not searching for it at the last minute.\n\n## If you are Rh-negative\n\n- Tell every doctor, and keep the result written on your antenatal card.\n- Your blood may be checked for antibodies during pregnancy.\n- Do not miss anti-D after a miscarriage or abortion, even an early one. Ask your doctor.\n- Rh-negative donors are harder to find, so line up donors early.\n\n## If you are Rh-positive\n\nYou do not need anti-D. Still write your group down and find two possible donors before the birth.\n\nA blood group is simply a fact about your body, not a problem with you. With good planning, Rh-negative mothers have healthy babies.","bn":"## রক্তের গ্রুপ জেনে রাখুন\n\nসবার একটি রক্তের গ্রুপ (A, B, AB বা O) আর একটি আরএইচ ধরন (পজিটিভ বা নেগেটিভ) থাকে — যেমন ''বি পজিটিভ'' বা ''ও নেগেটিভ''। গর্ভধারণের আগেই স্বামী-স্ত্রী দুজনের গ্রুপ জেনে রাখা উচিত। প্রসবের সময় বেশি রক্তক্ষরণ হলে দ্রুত একই গ্রুপের রক্তদাতা লাগবে।\n\n## আরএইচ নেগেটিভ মানে কী\n\nবাংলাদেশের বেশিরভাগ মানুষ আরএইচ পজিটিভ। মা নেগেটিভ আর বাবা পজিটিভ হলে শিশু পজিটিভ হতে পারে। শিশুর কিছু রক্ত মায়ের রক্তে মিশলে — প্রসবের সময়, কিংবা গর্ভপাত, এমআর, রক্তপাত, পড়ে যাওয়া বা কিছু পরীক্ষার পর — মায়ের শরীর পজিটিভ রক্তের বিরুদ্ধে অ্যান্টিবডি তৈরি করতে পারে।\n\nপ্রথম সন্তানের সাধারণত সমস্যা হয় না। কিন্তু পরের গর্ভে এই অ্যান্টিবডি গর্ভফুল পেরিয়ে শিশুর লোহিত কণিকা ভেঙে দিতে পারে। এতে শিশুর মারাত্মক রক্তস্বল্পতা ও জন্ডিস হতে পারে (নবজাতকের হিমোলাইটিক রোগ)।\n\n## কীভাবে প্রতিরোধ করা যায়\n\nঅ্যান্টি-ডি (Anti-D) নামের একটি ইনজেকশন মায়ের শরীরকে এই অ্যান্টিবডি বানাতে দেয় না। ডাক্তার পরিকল্পনা করে দেবেন। সাধারণত দেওয়া হয়:\n\n- গর্ভাবস্থায়, প্রায়ই শেষ তিন মাসে — ডাক্তারের পরামর্শমতো\n- প্রসবের ৭২ ঘণ্টার মধ্যে, যদি শিশু পজিটিভ হয়\n- যেকোনো রক্তপাত, গর্ভপাত, এমআর, জরায়ুর বাইরে গর্ভধারণ বা পেটে আঘাতের পর\n\nকোথায় অ্যান্টি-ডি পাওয়া যায় আর দাম কত, আগে থেকে জেনে রাখুন, যাতে শেষ মুহূর্তে খুঁজতে না হয়।\n\n## আপনি আরএইচ নেগেটিভ হলে\n\n- প্রত্যেক ডাক্তারকে জানান, গর্ভকালীন কার্ডে লিখে রাখুন।\n- গর্ভাবস্থায় রক্তে অ্যান্টিবডি আছে কিনা পরীক্ষা করা হতে পারে।\n- গর্ভপাত বা এমআর-এর পর, খুব শুরুর দিকের হলেও, অ্যান্টি-ডি বাদ দেবেন না। ডাক্তারকে জিজ্ঞেস করুন।\n- নেগেটিভ রক্তদাতা খুঁজে পাওয়া কঠিন, তাই আগেভাগেই রক্তদাতা ঠিক করে রাখুন।\n\n## আপনি আরএইচ পজিটিভ হলে\n\nঅ্যান্টি-ডি লাগবে না। তবুও গ্রুপটা লিখে রাখুন আর প্রসবের আগে দুজন সম্ভাব্য রক্তদাতা ঠিক করুন।\n\nরক্তের গ্রুপ শুধু শরীরের একটা তথ্য, আপনার কোনো ত্রুটি নয়। ভালো পরিকল্পনা থাকলে আরএইচ নেগেটিভ মায়েরাও সুস্থ সন্তান পান।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['blood group', 'rh negative', 'anti-d', 'blood donor']::text[], false, 'in_review'::lp_review_status, 2005),
  ('pp-cousin-marriage-genetic-counselling', 'article', 'scientific', 'shared', 'educational', 'consensus', '🧬', '{"en":"Marriage between relatives and genetic counselling","bn":"আত্মীয়ের মধ্যে বিয়ে ও জেনেটিক কাউন্সেলিং"}'::jsonb, '{"en":"Most children of cousin couples are healthy. Knowing your family history and having a few simple tests lets you plan with confidence.","bn":"আত্মীয়ের মধ্যে বিয়ে হওয়া দম্পতির বেশিরভাগ সন্তানই সুস্থ। পরিবারের স্বাস্থ্য-ইতিহাস জানা আর কয়েকটি সহজ পরীক্ষা নিশ্চিন্তে পরিকল্পনা করতে সাহায্য করে।"}'::jsonb, '{"en":"## A common family tradition\n\nIn Bangladesh, as in many countries, marriages between cousins and other relatives are common, and they often bring families closer. This guide is not about whether to marry a relative. It is about information that helps related couples have healthy children.\n\n## Why being related matters for some conditions\n\nSome conditions, such as thalassaemia and certain rare conditions affecting hearing, sight or body chemistry, appear only when a child gets the same changed gene from both parents. Most of us carry a few such genes without knowing it. Relatives share some genes from common grandparents, so they are more likely to carry the same one. This raises the chance a little; it does not mean a problem will happen. Most children born to cousin couples are healthy.\n\n## What you can do\n\n- **Talk about family health openly.** Write down any relatives on either side who had thalassaemia, deafness or blindness from birth, developmental delay, birth defects, or babies who died young without a clear reason. Shared knowledge protects everyone.\n- **Have the thalassaemia carrier test** — both partners.\n- **Ask for genetic counselling** if anyone in the family had an inherited condition. A specialist explains the chances and the tests available; you make the decisions.\n- **Go to all antenatal check-ups** in pregnancy, including the ultrasound scans your doctor advises.\n- **Have your newborn checked** after birth, including a hearing check if it is offered.\n\n## No blame, ever\n\nIf a child is born with a genetic condition, it is not the mother''s fault, nor the father''s, nor the fault of the elders who arranged the marriage. Genes pass silently through generations. Families who support each other, instead of looking for someone to blame, cope far better and help the child thrive.\n\n## Where to ask\n\nStart with your gynaecologist or a medical college hospital. They can refer you to a genetics or thalassaemia specialist if needed.","bn":"## একটি প্রচলিত পারিবারিক রীতি\n\nবাংলাদেশসহ অনেক দেশে চাচাতো, মামাতো, খালাতো, ফুপাতো ভাই-বোন বা অন্য আত্মীয়ের মধ্যে বিয়ে প্রচলিত, আর এতে পরিবারের বন্ধন অনেক সময় দৃঢ় হয়। এই লেখা আত্মীয়ের মধ্যে বিয়ে করা উচিত কিনা তা নিয়ে নয়। এটা এমন কিছু তথ্য, যা আত্মীয় দম্পতিদের সুস্থ সন্তান পেতে সাহায্য করে।\n\n## কিছু রোগে আত্মীয়তা কেন গুরুত্বপূর্ণ\n\nথ্যালাসেমিয়া এবং শ্রবণ, দৃষ্টি বা শরীরের রাসায়নিক কাজকে প্রভাবিত করে এমন কিছু বিরল রোগ তখনই দেখা দেয়, যখন শিশু বাবা-মা দুজনের কাছ থেকেই একই পরিবর্তিত জিন পায়। আমরা প্রায় সবাই না জেনে এমন কিছু জিন বহন করি। আত্মীয়দের দাদা-দাদি বা নানা-নানি একই হওয়ায় তাঁদের কিছু জিন মিলে যায়, তাই একই জিন বহনের সম্ভাবনা বেশি। এতে ঝুঁকি একটু বাড়ে, কিন্তু সমস্যা হবেই — এমন নয়। আত্মীয় দম্পতির বেশিরভাগ সন্তানই সুস্থ।\n\n## আপনারা যা করতে পারেন\n\n- **পরিবারের স্বাস্থ্য নিয়ে খোলাখুলি কথা বলুন।** দুই পক্ষের কোনো আত্মীয়ের থ্যালাসেমিয়া, জন্ম থেকে কানে না শোনা বা চোখে না দেখা, বিকাশে দেরি, জন্মগত ত্রুটি, বা স্পষ্ট কারণ ছাড়া ছোটবেলায় মারা যাওয়া শিশু থাকলে লিখে রাখুন। এই তথ্য সবাইকে সুরক্ষা দেয়।\n- **থ্যালাসেমিয়া বাহক পরীক্ষা করান** — দুজনেরই।\n- **জেনেটিক কাউন্সেলিং নিন**, যদি পরিবারে কারো বংশগত রোগ থেকে থাকে। বিশেষজ্ঞ সম্ভাবনা আর পরীক্ষার সুযোগ বুঝিয়ে বলবেন; সিদ্ধান্ত নেবেন আপনারাই।\n- **গর্ভাবস্থায় সব চেকআপে যান**, ডাক্তার যে আলট্রাসাউন্ডগুলো করতে বলেন সেগুলোসহ।\n- **জন্মের পর নবজাতকের পরীক্ষা করান**, সুযোগ থাকলে শ্রবণ পরীক্ষাও।\n\n## কখনোই দোষারোপ নয়\n\nকোনো শিশু জিনগত রোগ নিয়ে জন্মালে তা মায়ের দোষ নয়, বাবার দোষ নয়, বিয়ে ঠিক করা মুরুব্বিদেরও দোষ নয়। জিন নিঃশব্দে প্রজন্ম থেকে প্রজন্মে যায়। যে পরিবার দোষী না খুঁজে একে অপরের পাশে দাঁড়ায়, তারা অনেক ভালোভাবে সামলাতে পারে, আর শিশুও ভালো থাকে।\n\n## কোথায় জিজ্ঞেস করবেন\n\nআপনার স্ত্রীরোগ বিশেষজ্ঞ বা কোনো মেডিকেল কলেজ হাসপাতাল থেকে শুরু করুন। দরকার হলে তাঁরা জেনেটিক বা থ্যালাসেমিয়া বিশেষজ্ঞের কাছে পাঠাবেন।"}'::jsonb, '{}'::jsonb, 4, NULL, -280, '{}'::text[], 'any', ARRAY['cousin marriage', 'consanguinity', 'genetic counselling', 'family history', 'inherited']::text[], false, 'in_review'::lp_review_status, 2006),
  ('pp-cycle-fertile-window', 'article', 'scientific', 'shared', 'educational', 'consensus', '📅', '{"en":"Your cycle and the fertile window","bn":"মাসিক চক্র ও গর্ভধারণের উপযুক্ত সময়"}'::jsonb, '{"en":"Pregnancy is possible on only a few days of each cycle. Knowing these days helps — but regular sex through the month works just as well and causes less stress.","bn":"প্রতি মাসিক চক্রে মাত্র কয়েকটি দিন গর্ভধারণ সম্ভব। এই দিনগুলো জানা কাজে দেয় — তবে পুরো মাস নিয়মিত মিলনও সমান কার্যকর, আর দুশ্চিন্তাও কম।"}'::jsonb, '{"en":"## The menstrual cycle\n\nA cycle starts on the first day of a period and ends the day before the next one. In adults it is usually between 21 and 35 days long; it does not have to be 28. Around the middle of the cycle, an ovary releases an egg (ovulation). The egg lives for about a day.\n\n## The fertile window\n\nSperm can live inside a woman''s body for up to five days. So the fertile window is about six days: the five days before ovulation and the day of ovulation itself. Ovulation usually happens about 14 days before the next period, not 14 days after the last one. In a 28-day cycle that is around day 14; in a 35-day cycle, around day 21.\n\n## Signs of ovulation\n\n- Vaginal discharge becomes clear, slippery and stretchy, like raw egg white\n- Some women feel a mild pain on one side of the lower belly\n- Ovulation test kits from a pharmacy detect a hormone rise in urine\n\n## The simplest advice\n\nTiming everything exactly can become stressful for both of you. Doctors'' advice is simply to have sex every two to three days throughout the cycle. This covers the fertile window without needing to work it out.\n\n## Track your cycle\n\nNote the first day of each period in a calendar or app for a few months. You will learn your usual cycle length, the doctor will find it useful, and it will help work out the due date later.\n\n## Good to know\n\n- Most healthy couples conceive within a year of trying.\n- Very irregular cycles, gaps of more than 35 days, no periods, or very painful or very heavy periods are worth a check-up. Conditions such as PCOS (polycystic ovary syndrome) or thyroid problems can be treated.\n- Stress, being very underweight or overweight, and smoking can all affect cycles.\n- Fertility is shared: the man''s health matters as much as the woman''s.","bn":"## মাসিক চক্র\n\nমাসিক শুরুর প্রথম দিন থেকে পরের মাসিকের আগের দিন পর্যন্ত একটি চক্র। প্রাপ্তবয়স্ক নারীর চক্র সাধারণত ২১ থেকে ৩৫ দিনের হয় — ঠিক ২৮ দিন হতেই হবে, এমন নয়। চক্রের মাঝামাঝি সময়ে ডিম্বাশয় থেকে একটি ডিম্বাণু বের হয় (ডিম্বস্ফোটন বা ওভুলেশন)। ডিম্বাণু মোটামুটি এক দিন বাঁচে।\n\n## উর্বর সময়\n\nশুক্রাণু নারীর শরীরে পাঁচ দিন পর্যন্ত বেঁচে থাকতে পারে। তাই উর্বর সময় মোটামুটি ছয় দিন — ডিম্বস্ফোটনের আগের পাঁচ দিন আর ডিম্বস্ফোটনের দিন। ডিম্বস্ফোটন সাধারণত পরের মাসিকের প্রায় ১৪ দিন আগে হয়, আগের মাসিকের ১৪ দিন পরে নয়। ২৮ দিনের চক্রে এটা মোটামুটি ১৪তম দিনে; ৩৫ দিনের চক্রে প্রায় ২১তম দিনে।\n\n## ডিম্বস্ফোটনের লক্ষণ\n\n- যোনিপথের স্রাব স্বচ্ছ, পিচ্ছিল আর কাঁচা ডিমের সাদা অংশের মতো টেনে লম্বা করা যায়\n- কেউ কেউ তলপেটের এক পাশে হালকা ব্যথা টের পান\n- ফার্মেসির ওভুলেশন টেস্ট কিট প্রস্রাবে হরমোন বাড়া ধরতে পারে\n\n## সবচেয়ে সহজ পরামর্শ\n\nসব কিছু দিন গুনে মেলাতে গেলে দুজনেরই চাপ বাড়ে। ডাক্তারদের সহজ পরামর্শ: পুরো চক্রজুড়ে দুই-তিন দিন পরপর মিলন করুন। এতে আলাদা করে হিসাব না করেও উর্বর সময়টা ধরা পড়ে।\n\n## চক্রের হিসাব রাখুন\n\nকয়েক মাস ক্যালেন্ডারে বা অ্যাপে প্রতিবার মাসিক শুরুর তারিখ লিখে রাখুন। এতে নিজের চক্র কত দিনের তা বুঝবেন, ডাক্তারের কাজে লাগবে, আর পরে প্রসবের সম্ভাব্য তারিখ বের করতেও সুবিধা হবে।\n\n## জেনে রাখুন\n\n- বেশিরভাগ সুস্থ দম্পতির চেষ্টা শুরুর এক বছরের মধ্যে গর্ভধারণ হয়।\n- খুব অনিয়মিত চক্র, ৩৫ দিনের বেশি বিরতি, মাসিক না হওয়া, কিংবা খুব ব্যথা বা খুব বেশি রক্তক্ষরণ হলে ডাক্তার দেখানো ভালো। পিসিওএস (PCOS) বা থাইরয়েডের সমস্যার চিকিৎসা আছে।\n- মানসিক চাপ, খুব কম বা খুব বেশি ওজন আর ধূমপান চক্রকে প্রভাবিত করতে পারে।\n- উর্বরতা দুজনের বিষয় — পুরুষের স্বাস্থ্যও নারীর মতোই গুরুত্বপূর্ণ।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['menstrual cycle', 'ovulation', 'fertile window', 'periods', 'trying to conceive']::text[], false, 'in_review'::lp_review_status, 2007),
  ('pp-when-to-see-doctor-fertility', 'article', 'scientific', 'shared', 'routine', 'guideline', '👩‍⚕️', '{"en":"Not pregnant yet? When to see a doctor","bn":"এখনো গর্ভধারণ হচ্ছে না? কখন ডাক্তার দেখাবেন"}'::jsonb, '{"en":"See a doctor together after 12 months of trying, or after 6 months if the woman is 35 or older — and sooner if there is a known problem.","bn":"১২ মাস চেষ্টার পরও না হলে দুজনে একসাথে ডাক্তার দেখান; নারীর বয়স ৩৫ বা বেশি হলে ৬ মাস পর — আর জানা কোনো সমস্যা থাকলে আরও আগে।"}'::jsonb, '{"en":"## Give it time\n\nMost couples conceive within a year of regular sex without contraception. Many take longer than they expected, and that is normal. Worry and family pressure are common, especially in the first year of marriage, but they do not make conception happen faster.\n\n## When to go\n\nSee a doctor if you have been having regular sex (every two to three days) without contraception for:\n\n- **12 months**, if the woman is under 35\n- **6 months**, if the woman is 35 or older\n\nGo **sooner** if:\n\n- periods are very irregular or absent\n- there is a history of pelvic infection, endometriosis, or an operation on the womb, tubes or ovaries\n- the man has had an operation or injury to the testes, or problems with erection or ejaculation\n- either partner has had cancer treatment\n- either partner has a long-term illness\n\n## Both partners, from the start\n\nDifficulty conceiving is not ''a woman''s problem''. The cause can be in the man, the woman, both, or not found at all. Testing both at the same time saves months.\n\n- **For the man:** a semen analysis — simple, inexpensive and very useful\n- **For the woman:** blood tests for hormones and ovulation, an ultrasound, and sometimes a test to check the tubes\n\n## What helps meanwhile\n\n- A healthy weight and daily activity for both\n- No tobacco, jarda, gul or betel nut\n- Folic acid every day for her\n- Kindness to each other; this is a shared journey\n\n## Be careful with\n\n- ''Guaranteed'' medicines, unproven treatments, or remedies from unqualified sellers\n- Taking hormone or fertility medicines without a doctor\n- Blaming either partner; it hurts and solves nothing\n\nStart with a gynaecologist or a medical college hospital. Many causes can be treated, and a good doctor will explain each step.","bn":"## একটু সময় দিন\n\nজন্মনিয়ন্ত্রণ ছাড়া নিয়মিত মিলনে বেশিরভাগ দম্পতির এক বছরের মধ্যে গর্ভধারণ হয়। অনেকের আশার চেয়ে বেশি সময় লাগে — এটাও স্বাভাবিক। বিশেষ করে বিয়ের প্রথম বছরে দুশ্চিন্তা আর পরিবারের চাপ খুব সাধারণ, কিন্তু চাপ দিলে গর্ভধারণ তাড়াতাড়ি হয় না।\n\n## কখন যাবেন\n\nজন্মনিয়ন্ত্রণ ছাড়া নিয়মিত (দুই-তিন দিন পরপর) মিলনের পরও গর্ভধারণ না হলে ডাক্তার দেখান:\n\n- **১২ মাস** পর, নারীর বয়স ৩৫-এর কম হলে\n- **৬ মাস** পর, নারীর বয়স ৩৫ বা তার বেশি হলে\n\n**আরও আগে** যাবেন যদি:\n\n- মাসিক খুব অনিয়মিত হয় বা না হয়\n- আগে তলপেটে সংক্রমণ, এন্ডোমেট্রিওসিস, বা জরায়ু, টিউব বা ডিম্বাশয়ে অপারেশন হয়ে থাকে\n- স্বামীর অণ্ডকোষে অপারেশন বা আঘাত হয়ে থাকে, অথবা লিঙ্গোত্থান বা বীর্যপাতে সমস্যা থাকে\n- কারো ক্যানসারের চিকিৎসা হয়ে থাকে\n- কারো দীর্ঘমেয়াদি অসুখ থাকে\n\n## শুরু থেকেই দুজনে\n\nগর্ভধারণে দেরি শুধু ''মেয়েদের সমস্যা'' নয়। কারণ থাকতে পারে স্বামীর, স্ত্রীর, দুজনেরই — বা কোনো কারণ না-ও পাওয়া যেতে পারে। দুজনের পরীক্ষা একসাথে করালে কয়েক মাস সময় বাঁচে।\n\n- **স্বামীর জন্য:** বীর্য পরীক্ষা (সিমেন অ্যানালাইসিস) — সহজ, খরচ কম, খুব কাজের\n- **স্ত্রীর জন্য:** হরমোন ও ডিম্বস্ফোটনের রক্ত পরীক্ষা, আলট্রাসাউন্ড, আর কখনো টিউব খোলা আছে কিনা দেখার পরীক্ষা\n\n## এর মধ্যে যা সাহায্য করে\n\n- দুজনেরই স্বাস্থ্যকর ওজন ও প্রতিদিন হাঁটাচলা\n- তামাক, জর্দা, গুল বা সুপারি বাদ\n- স্ত্রীর প্রতিদিন ফলিক অ্যাসিড\n- একে অপরের প্রতি সদয় থাকা — এটা দুজনের একসাথে পথচলা\n\n## যেগুলো থেকে সাবধান\n\n- ''গ্যারান্টি দিয়ে'' সারানোর ওষুধ, অপ্রমাণিত চিকিৎসা বা অদক্ষ বিক্রেতার টোটকা\n- ডাক্তার ছাড়া হরমোন বা উর্বরতার ওষুধ খাওয়া\n- কাউকে দোষ দেওয়া — এতে কষ্ট বাড়ে, সমাধান হয় না\n\nস্ত্রীরোগ বিশেষজ্ঞ বা মেডিকেল কলেজ হাসপাতাল থেকে শুরু করুন। অনেক কারণেরই চিকিৎসা আছে, আর ভালো ডাক্তার প্রতিটি ধাপ বুঝিয়ে বলবেন।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['infertility', 'fertility', 'semen analysis', 'trying to conceive', 'doctor']::text[], false, 'in_review'::lp_review_status, 2008),
  ('pp-quit-tobacco-betel', 'article', 'scientific', 'shared', 'important', 'guideline', '🚭', '{"en":"Quit smoking, jarda, gul and betel nut — and keep the home smoke-free","bn":"ধূমপান, জর্দা, গুল ও সুপারি ছাড়ুন — ঘর রাখুন ধোঁয়ামুক্ত"}'::jsonb, '{"en":"Tobacco in any form, and other people''s smoke, harm fertility and the growing baby. The best time to stop is before pregnancy, and both partners need to.","bn":"যেকোনো ধরনের তামাক আর অন্যের ধোঁয়া উর্বরতা ও গর্ভের শিশুর ক্ষতি করে। ছাড়ার সবচেয়ে ভালো সময় গর্ভধারণের আগে — আর ছাড়তে হবে দুজনকেই।"}'::jsonb, '{"en":"## Every form of tobacco harms\n\nSmoking cigarettes or bidis, chewing jarda or sadapata with paan, and rubbing gul on the gums all deliver nicotine and harmful chemicals. In pregnancy, tobacco use is linked to miscarriage, a small baby, early birth and stillbirth. After birth, babies exposed to smoke have more chest infections and a higher risk of sudden infant death.\n\n## Betel nut (supari) too\n\nAreca nut (supari), with or without tobacco, is a known cause of mouth cancer, and studies suggest it may also affect the baby''s growth in pregnancy. It is best to stop before pregnancy.\n\n## Second-hand smoke\n\nSmoke from a husband, father-in-law or guest smoking indoors reaches the mother and the baby. Opening a window is not enough. Ask everyone to smoke outside, away from the door, or better still, to quit.\n\n## For men\n\nSmoking lowers sperm quality. Quitting before trying for a baby helps fertility, protects your wife and child from smoke, and makes you a good example for your child.\n\n## How to quit\n\n1. Choose a quit date within the next two weeks and tell your family.\n2. Remove cigarettes, jarda, gul, supari and lighters from the house.\n3. Know your triggers — after meals, with tea, with friends — and plan something else: a short walk, a glass of water, a pinch of mouri (fennel seeds) or sugar-free gum.\n4. Expect strong cravings for the first few weeks. Each one passes in a few minutes.\n5. Ask a doctor for help, or call Shastho Batayon on 16263. In pregnancy, do not use nicotine gum or patches unless a doctor advises.\n6. If you slip, do not give up. Start again the next day.\n\n## For the family\n\nElders may chew paan with jarda and offer it to guests as hospitality. It is fine to say no politely and explain that it is for the baby. Support the person who is quitting with patience, not shaming.","bn":"## যেকোনো তামাকই ক্ষতিকর\n\nসিগারেট বা বিড়ি টানা, পানের সাথে জর্দা বা সাদাপাতা খাওয়া, মাড়িতে গুল ঘষা — সবকিছুতেই নিকোটিন আর ক্ষতিকর রাসায়নিক শরীরে ঢোকে। গর্ভাবস্থায় তামাকের সাথে গর্ভপাত, শিশুর কম ওজন, অকালপ্রসব ও মৃত সন্তান প্রসবের সম্পর্ক আছে। জন্মের পর ধোঁয়ার মধ্যে থাকা শিশুর বুকে সংক্রমণ বেশি হয়, ঘুমের মধ্যে হঠাৎ মৃত্যুর ঝুঁকিও বাড়ে।\n\n## সুপারিও\n\nসুপারি, তামাকসহ হোক বা ছাড়া, মুখের ক্যানসারের একটি জানা কারণ। গবেষণা বলছে, গর্ভাবস্থায় এটা শিশুর বৃদ্ধিতেও প্রভাব ফেলতে পারে। গর্ভধারণের আগেই ছেড়ে দেওয়া ভালো।\n\n## অন্যের ধোঁয়া\n\nস্বামী, শ্বশুর বা অতিথি ঘরের ভেতরে ধূমপান করলে সেই ধোঁয়া মা ও শিশুর কাছে পৌঁছায়। জানালা খুলে দিলেই যথেষ্ট নয়। সবাইকে বাইরে, দরজা থেকে দূরে গিয়ে ধূমপান করতে বলুন — তার চেয়েও ভালো, ছেড়ে দিতে বলুন।\n\n## পুরুষদের জন্য\n\nধূমপানে শুক্রাণুর মান কমে যায়। সন্তান নেওয়ার আগে ছাড়লে উর্বরতা বাড়ে, স্ত্রী-সন্তান ধোঁয়া থেকে বাঁচে, আর আপনি সন্তানের জন্য ভালো উদাহরণ হন।\n\n## কীভাবে ছাড়বেন\n\n১. আগামী দুই সপ্তাহের মধ্যে একটা তারিখ ঠিক করুন, পরিবারকে জানান।\n২. বাসা থেকে সিগারেট, জর্দা, গুল, সুপারি আর লাইটার সরিয়ে ফেলুন।\n৩. কখন বেশি ইচ্ছা করে চিনে নিন — খাওয়ার পর, চায়ের সাথে, বন্ধুদের সাথে — আর তখন অন্য কিছু করুন: একটু হাঁটা, এক গ্লাস পানি, এক চিমটি মৌরি বা চিনি ছাড়া চুইংগাম।\n৪. প্রথম কয়েক সপ্তাহ খুব ইচ্ছা করবে — প্রতিবারের তাড়না কয়েক মিনিটেই কেটে যায়।\n৫. ডাক্তারের সাহায্য নিন, বা স্বাস্থ্য বাতায়নে (১৬২৬৩) ফোন করুন। গর্ভাবস্থায় ডাক্তার না বললে নিকোটিন গাম বা প্যাচ ব্যবহার করবেন না।\n৬. একবার ভুল হলে হাল ছাড়বেন না। পরদিন আবার শুরু করুন।\n\n## পরিবারের জন্য\n\nমুরুব্বিরা জর্দা দিয়ে পান খান, অতিথিকেও আপ্যায়ন হিসেবে দেন। নম্রভাবে না বলা আর বুঝিয়ে বলা যে এটা শিশুর জন্য — এতে কোনো অসম্মান নেই। যিনি ছাড়ার চেষ্টা করছেন, তাঁকে লজ্জা না দিয়ে ধৈর্য ধরে পাশে থাকুন।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['smoking', 'jarda', 'gul', 'betel nut', 'supari', 'second-hand smoke', 'tobacco']::text[], false, 'in_review'::lp_review_status, 2009),
  ('pp-couple-talk-roles', 'article', 'general', 'shared', 'routine', 'consensus', '💬', '{"en":"Talking as a couple: roles, expectations and in-laws","bn":"দম্পতির আলাপ: দায়িত্ব, প্রত্যাশা ও শ্বশুরবাড়ি"}'::jsonb, '{"en":"Before a baby comes, talk honestly about who will do what, how you will make decisions, and how you will handle the family''s expectations.","bn":"সন্তান আসার আগেই খোলাখুলি কথা বলুন — কে কী করবেন, সিদ্ধান্ত কীভাবে নেবেন, আর পরিবারের প্রত্যাশা কীভাবে সামলাবেন।"}'::jsonb, '{"en":"## Why talk now\n\nA baby changes sleep, money, work and family life. Couples who talk about these things early argue less later and feel like a team. There is no single right way; what matters is that you both agree.\n\n## Questions to talk about\n\n- **Timing:** When do we want a child? Are we both ready? After a birth, WHO advises waiting at least two years before trying for the next pregnancy, for the health of mother and baby.\n- **Health care:** Which doctor or facility will we use? Who will come to the check-ups?\n- **Work and money:** Will she keep working? How will we save? Who pays for what?\n- **Housework and baby care:** Who cooks, cleans, washes and gets up at night? A father can do all of these except breastfeeding.\n- **Where:** Will she go to her parents'' home for the birth, as many families do? How will the father stay involved?\n- **Decisions:** In an emergency, who decides? Waiting for one person''s permission can cost precious time.\n\n## In-laws and family expectations\n\nFamily support is a blessing. Problems usually come from expectations no one has spoken aloud.\n\n- Agree as a couple first, then speak to the family together.\n- The husband is usually the best person to talk to his own parents.\n- Respect elders, and be clear about what the doctor has advised.\n- Pressure to have a son is common. Science is clear: the baby''s sex is decided by the father''s sperm, not by the mother. No woman should ever be blamed for having a daughter.\n\n## How to talk\n\n- Choose a calm time, not the middle of an argument\n- Listen fully before you answer\n- Say ''I feel…'' instead of ''You always…''\n- Write down what you agree, and look at it again every few months\n\n## If you do not feel safe\n\nIf there is shouting, threats, hitting or control at home, it is not your fault, and it is not a private matter you must bear alone. In danger, call 999. You can also call 109, the national helpline for violence against women and children.","bn":"## এখনই কেন কথা বলবেন\n\nসন্তান এলে ঘুম, টাকা, কাজ আর পারিবারিক জীবন — সবই বদলে যায়। যে দম্পতিরা আগেভাগে এসব নিয়ে কথা বলেন, পরে তাঁদের ঝগড়া কম হয়, নিজেদের এক দল মনে হয়। ঠিক একটাই পথ নেই; জরুরি হলো দুজনের একমত হওয়া।\n\n## যে প্রশ্নগুলো নিয়ে কথা বলবেন\n\n- **কখন:** আমরা কবে সন্তান চাই? দুজনেই কি প্রস্তুত? বিশ্ব স্বাস্থ্য সংস্থা বলে, মা ও শিশুর সুস্থতার জন্য এক সন্তানের জন্মের পর পরের গর্ভধারণের আগে অন্তত দুই বছর অপেক্ষা করা উচিত।\n- **চিকিৎসা:** কোন ডাক্তার বা কোন হাসপাতাল? চেকআপে কে সাথে যাবে?\n- **কাজ ও টাকা:** স্ত্রী কি চাকরি চালিয়ে যাবেন? কীভাবে টাকা জমাব? কোন খরচ কে দেবে?\n- **ঘরের কাজ ও শিশুর যত্ন:** রান্না, পরিষ্কার, কাপড় ধোয়া, রাতে উঠে শিশুকে দেখা — কে করবে? বুকের দুধ খাওয়ানো ছাড়া বাবা এর সবই করতে পারেন।\n- **কোথায়:** অনেক পরিবারের মতো স্ত্রী কি প্রসবের জন্য বাবার বাড়ি যাবেন? তখন স্বামী কীভাবে পাশে থাকবেন?\n- **সিদ্ধান্ত:** জরুরি অবস্থায় কে সিদ্ধান্ত নেবেন? কারো অনুমতির জন্য অপেক্ষা করতে গিয়ে মূল্যবান সময় চলে যেতে পারে।\n\n## শ্বশুরবাড়ি ও পরিবারের প্রত্যাশা\n\nপরিবারের সহায়তা এক বড় আশীর্বাদ। সমস্যা হয় সাধারণত সেই প্রত্যাশা থেকে, যা কেউ মুখে বলেননি।\n\n- আগে দুজনে একমত হোন, তারপর একসাথে পরিবারের সাথে কথা বলুন।\n- নিজের বাবা-মায়ের সাথে কথা বলার জন্য সাধারণত স্বামীই সবচেয়ে উপযুক্ত।\n- মুরুব্বিদের সম্মান করুন, আর ডাক্তার কী বলেছেন তা স্পষ্ট করে জানান।\n- ছেলে সন্তানের জন্য চাপ খুব সাধারণ। বিজ্ঞান পরিষ্কার: শিশু ছেলে হবে না মেয়ে, তা ঠিক হয় বাবার শুক্রাণু থেকে, মায়ের থেকে নয়। মেয়ে সন্তানের জন্য কোনো নারীকে কখনো দোষ দেওয়া যাবে না।\n\n## কীভাবে কথা বলবেন\n\n- শান্ত সময় বেছে নিন, ঝগড়ার মাঝখানে নয়\n- উত্তর দেওয়ার আগে পুরো কথা শুনুন\n- ''তুমি সবসময়…'' না বলে বলুন ''আমার মনে হয়…''\n- যেসব বিষয়ে একমত হলেন লিখে রাখুন, কয়েক মাস পরপর আবার দেখুন\n\n## নিজেকে নিরাপদ মনে না হলে\n\nঘরে চিৎকার, হুমকি, মারধর বা নিয়ন্ত্রণ থাকলে তা আপনার দোষ নয়, আর এটা একা সহ্য করার মতো ব্যক্তিগত বিষয়ও নয়। বিপদে ৯৯৯-এ ফোন করুন। নারী ও শিশু নির্যাতন প্রতিরোধে জাতীয় হেল্পলাইন ১০৯-এও ফোন করতে পারেন।"}'::jsonb, '{}'::jsonb, 4, NULL, -280, '{}'::text[], 'any', ARRAY['couple', 'communication', 'in-laws', 'roles', 'expectations', 'birth spacing']::text[], false, 'in_review'::lp_review_status, 2010),
  ('pp-pregnancy-birth-budget', 'article', 'general', 'shared', 'routine', 'consensus', '💰', '{"en":"Budgeting for pregnancy and birth","bn":"গর্ভাবস্থা ও প্রসবের খরচের পরিকল্পনা"}'::jsonb, '{"en":"Planning money early means no delay in care when it matters. Make a simple list, save a little each month, and keep an emergency fund apart.","bn":"আগে থেকে টাকার পরিকল্পনা থাকলে দরকারের সময় চিকিৎসায় দেরি হয় না। একটা সহজ তালিকা করুন, প্রতি মাসে কিছু জমান, আর জরুরি তহবিল আলাদা রাখুন।"}'::jsonb, '{"en":"## Why plan money now\n\nIn an emergency, families sometimes lose precious hours arranging money. A plan made months earlier removes that worry and lets you choose care calmly.\n\n## What to budget for\n\n- **Antenatal care:** visits, blood and urine tests, ultrasounds and supplements\n- **Better food** for the mother through pregnancy and breastfeeding\n- **Transport** to check-ups and on the day of the birth, including at night\n- **The birth:** facility charges, medicines and supplies. A caesarean costs more than a normal birth, so plan for the possibility\n- **An emergency fund:** blood transfusion, special care for the newborn, a longer stay\n- **Baby needs:** clothes, cloths and nappies, soap — simple is fine\n- **Lost income** if either parent takes time off work\n\nAsk your chosen facility what a normal birth and a caesarean usually cost, and what is free. Government facilities offer many services free or at low cost.\n\n## How to save\n\n1. Write a list with an estimated amount for each item.\n2. Divide the total by the months left, and save that amount each month.\n3. Keep the emergency fund separate — in a bank, a mobile banking savings account or with a trusted person — and use it only for health.\n4. Decide in advance who can take the money out at any hour.\n5. Avoid high-interest loans. If you must borrow, agree the terms early, not in the middle of an emergency.\n\n## Support you may be eligible for\n\n- Some areas have government support for pregnant women, such as maternal health vouchers or allowances for low-income mothers. Ask at your Upazila Health Complex, community clinic or Union Parishad.\n- Working women have a legal right to paid maternity leave. Check the rules at your workplace early.\n\n## Spend wisely\n\nBabies need warmth, breast milk, cleanliness and love far more than expensive things. Relatives often give clothes as gifts. Put your money first into safe care for the birth.","bn":"## এখনই কেন টাকার পরিকল্পনা\n\nজরুরি অবস্থায় টাকা জোগাড় করতে গিয়ে অনেক পরিবার মূল্যবান কয়েক ঘণ্টা হারায়। কয়েক মাস আগে পরিকল্পনা করলে সেই দুশ্চিন্তা থাকে না, ঠান্ডা মাথায় চিকিৎসা বেছে নেওয়া যায়।\n\n## কোন কোন খরচ ধরবেন\n\n- **গর্ভকালীন সেবা:** ডাক্তার দেখানো, রক্ত-প্রস্রাব পরীক্ষা, আলট্রাসাউন্ড, ভিটামিন-আয়রন\n- **মায়ের ভালো খাবার** — গর্ভাবস্থা ও বুকের দুধ খাওয়ানোর পুরো সময়\n- **যাতায়াত** — চেকআপে আর প্রসবের দিন, রাতের জন্যও\n- **প্রসব:** হাসপাতালের খরচ, ওষুধ ও জিনিসপত্র। স্বাভাবিক প্রসবের চেয়ে সিজারে খরচ বেশি, তাই সেই সম্ভাবনাও হিসাবে রাখুন\n- **জরুরি তহবিল:** রক্ত দেওয়া, নবজাতকের বিশেষ সেবা, বেশি দিন হাসপাতালে থাকা\n- **শিশুর জিনিস:** জামা, কাপড়, ন্যাপি, সাবান — সাধারণ হলেই চলে\n- **আয় কমে যাওয়া** — বাবা বা মা কাজ থেকে ছুটি নিলে\n\nযে হাসপাতাল বেছে নিচ্ছেন, সেখানে স্বাভাবিক প্রসব আর সিজারে সাধারণত কত খরচ হয় আর কী কী বিনা মূল্যে পাওয়া যায়, জেনে নিন। সরকারি হাসপাতালে অনেক সেবা বিনা মূল্যে বা কম খরচে পাওয়া যায়।\n\n## কীভাবে জমাবেন\n\n১. প্রতিটি খাতের আনুমানিক খরচ লিখে একটা তালিকা করুন।\n২. মোট টাকাকে বাকি মাসের সংখ্যা দিয়ে ভাগ করে প্রতি মাসে সেটুকু জমান।\n৩. জরুরি তহবিল আলাদা রাখুন — ব্যাংকে, মোবাইল ব্যাংকিংয়ের সঞ্চয়ে বা বিশ্বস্ত কারো কাছে — আর শুধু চিকিৎসায় খরচ করুন।\n৪. যেকোনো সময়, রাতেও, কে টাকা তুলতে পারবেন আগে ঠিক করে রাখুন।\n৫. চড়া সুদের ঋণ এড়িয়ে চলুন। ধার নিতেই হলে শর্তগুলো আগেভাগে ঠিক করুন, জরুরি অবস্থার মাঝখানে নয়।\n\n## যে সহায়তা পেতে পারেন\n\n- কিছু এলাকায় গর্ভবতী নারীদের জন্য সরকারি সহায়তা আছে, যেমন মাতৃস্বাস্থ্য ভাউচার বা দরিদ্র মায়েদের জন্য ভাতা। উপজেলা স্বাস্থ্য কমপ্লেক্স, কমিউনিটি ক্লিনিক বা ইউনিয়ন পরিষদে জিজ্ঞেস করুন।\n- কর্মজীবী নারীদের সবেতন মাতৃত্বকালীন ছুটির আইনি অধিকার আছে। কর্মস্থলের নিয়ম আগে থেকেই জেনে নিন।\n\n## বুঝে খরচ করুন\n\nদামি জিনিসের চেয়ে শিশুর অনেক বেশি দরকার উষ্ণতা, মায়ের দুধ, পরিচ্ছন্নতা আর ভালোবাসা। আত্মীয়রা প্রায়ই জামাকাপড় উপহার দেন। আগে টাকা রাখুন নিরাপদ প্রসবের জন্য।"}'::jsonb, '{}'::jsonb, 3, NULL, -280, '{}'::text[], 'any', ARRAY['budget', 'money', 'savings', 'birth costs', 'emergency fund', 'maternity leave']::text[], false, 'in_review'::lp_review_status, 2011),
  ('pp-antenatal-care-schedule', 'article', 'scientific', 'shared', 'important', 'guideline', '📋', '{"en":"Antenatal check-ups: when to go and what happens","bn":"গর্ভকালীন চেকআপ: কখন যাবেন, কী হয়"}'::jsonb, '{"en":"WHO recommends at least 8 antenatal contacts; Bangladesh asks for at least 4. Start before 12 weeks and keep going, even when you feel well.","bn":"বিশ্ব স্বাস্থ্য সংস্থা অন্তত ৮ বার গর্ভকালীন সেবা নিতে বলে; বাংলাদেশে কমপক্ষে ৪ বার। ১২ সপ্তাহের আগেই শুরু করুন, ভালো থাকলেও নিয়মিত যান।"}'::jsonb, '{"en":"## How many check-ups?\n\n- **WHO (2016)** recommends at least eight contacts: the first before 12 weeks, then at about 20, 26, 30, 34, 36, 38 and 40 weeks.\n- **Bangladesh''s** national programme has long asked for at least four visits, at around 16, 24–28, 32 and 36 weeks.\n\nFour is the minimum, not the goal. More contacts mean problems such as high blood pressure, anaemia or a baby who is not growing well are found earlier. Go whenever your health worker asks you to, and go at once if you notice a danger sign.\n\n## The first visit (ideally before 12 weeks)\n\n- Confirming the pregnancy and estimating the due date\n- Your health history, past pregnancies and medicines\n- Weight, height and blood pressure\n- Blood tests: haemoglobin, blood group and Rh, blood sugar, hepatitis B, syphilis and HIV; often a thalassaemia test\n- A urine test\n- An ultrasound before 24 weeks, as WHO advises, to date the pregnancy and check the baby\n- Starting iron–folic acid, and planning your Td vaccine\n\n## The middle months\n\n- Blood pressure and weight at every visit\n- Urine checked for protein and sugar\n- Measuring the growing belly and listening to the baby''s heartbeat\n- A glucose test around 24–28 weeks, as your doctor advises\n- Calcium tablets, if prescribed\n- Talking about food, rest, work and feelings\n\n## The last months\n\n- Checking the baby''s growth and position\n- Repeating the haemoglobin test\n- Your birth plan: facility, transport, money and blood donor\n- Signs of labour and danger signs\n- Breastfeeding in the first hour, and family planning after the birth\n\n## Make each visit count\n\n- Bring your antenatal card and all your reports every time\n- Write your questions down before you go\n- Bring your husband or a family member when you can\n- Before leaving, ask: ''Is everything normal? What should I watch for before the next visit?''\n\nAntenatal care is available at community clinics, Union Health and Family Welfare Centres, Upazila Health Complexes and hospitals.","bn":"## কতবার চেকআপ?\n\n- **বিশ্ব স্বাস্থ্য সংস্থা (২০১৬)** অন্তত আটবার সেবা নিতে বলে: প্রথমবার ১২ সপ্তাহের আগে, তারপর মোটামুটি ২০, ২৬, ৩০, ৩৪, ৩৬, ৩৮ ও ৪০ সপ্তাহে।\n- **বাংলাদেশের** জাতীয় কর্মসূচিতে দীর্ঘদিন ধরে অন্তত চারবার যেতে বলা হয় — মোটামুটি ১৬, ২৪–২৮, ৩২ ও ৩৬ সপ্তাহে।\n\nচারবার হলো সর্বনিম্ন, লক্ষ্য নয়। যত বেশিবার যাবেন, উচ্চ রক্তচাপ, রক্তস্বল্পতা বা শিশুর ঠিকমতো না বাড়ার মতো সমস্যা তত আগে ধরা পড়বে। স্বাস্থ্যকর্মী যখন আসতে বলেন তখন যান, আর কোনো বিপদচিহ্ন দেখলে সাথে সাথে যান।\n\n## প্রথম চেকআপ (সম্ভব হলে ১২ সপ্তাহের আগে)\n\n- গর্ভধারণ নিশ্চিত করা ও প্রসবের সম্ভাব্য তারিখ বের করা\n- আপনার অসুখ-বিসুখ, আগের গর্ভধারণ ও ওষুধের খোঁজ\n- ওজন, উচ্চতা ও রক্তচাপ\n- রক্ত পরীক্ষা: হিমোগ্লোবিন, রক্তের গ্রুপ ও আরএইচ, রক্তে শর্করা, হেপাটাইটিস বি, সিফিলিস ও এইচআইভি; অনেক সময় থ্যালাসেমিয়াও\n- প্রস্রাব পরীক্ষা\n- বিশ্ব স্বাস্থ্য সংস্থার পরামর্শমতো ২৪ সপ্তাহের আগে একটি আলট্রাসাউন্ড — গর্ভের বয়স ও শিশুর অবস্থা দেখতে\n- আয়রন-ফলিক অ্যাসিড শুরু, আর টিডি টিকার পরিকল্পনা\n\n## মাঝের মাসগুলোতে\n\n- প্রতিবার রক্তচাপ ও ওজন\n- প্রস্রাবে প্রোটিন ও শর্করা পরীক্ষা\n- পেটের মাপ নেওয়া আর শিশুর হৃৎস্পন্দন শোনা\n- ডাক্তারের পরামর্শমতো ২৪–২৮ সপ্তাহে গ্লুকোজ পরীক্ষা\n- প্রয়োজনে ক্যালসিয়াম ট্যাবলেট\n- খাবার, বিশ্রাম, কাজ ও মনের অবস্থা নিয়ে আলাপ\n\n## শেষের মাসগুলোতে\n\n- শিশুর বৃদ্ধি ও অবস্থান দেখা\n- আবার হিমোগ্লোবিন পরীক্ষা\n- প্রসব পরিকল্পনা: হাসপাতাল, যানবাহন, টাকা ও রক্তদাতা\n- প্রসববেদনার লক্ষণ ও বিপদচিহ্ন\n- জন্মের প্রথম ঘণ্টায় বুকের দুধ, আর প্রসবের পর পরিবার পরিকল্পনা\n\n## প্রতিটি চেকআপ কাজে লাগান\n\n- প্রতিবার গর্ভকালীন কার্ড আর সব রিপোর্ট সাথে নিন\n- যাওয়ার আগে প্রশ্নগুলো লিখে নিন\n- সম্ভব হলে স্বামী বা পরিবারের কাউকে সাথে নিন\n- ফেরার আগে জিজ্ঞেস করুন: ''সব কি স্বাভাবিক? পরের চেকআপের আগে কী খেয়াল রাখব?''\n\nকমিউনিটি ক্লিনিক, ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র, উপজেলা স্বাস্থ্য কমপ্লেক্স ও হাসপাতালে গর্ভকালীন সেবা পাওয়া যায়।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['antenatal care', 'anc', 'check-up', 'pregnancy visits', 'ultrasound']::text[], false, 'in_review'::lp_review_status, 2012),
  ('pp-eating-well-pregnancy', 'article', 'scientific', 'shared', 'important', 'guideline', '🍚', '{"en":"Eating well in pregnancy, with everyday Bangladeshi food","bn":"গর্ভাবস্থায় পুষ্টিকর খাবার — ঘরের চেনা খাবারেই"}'::jsonb, '{"en":"You do not need special foods. Eat a little more, and a variety of everyday foods — rice, dal, fish, eggs, shak, fruit and milk — every day.","bn":"বিশেষ কোনো খাবারের দরকার নেই। একটু বেশি খান, আর প্রতিদিন নানা রকম চেনা খাবার — ভাত, ডাল, মাছ, ডিম, শাক, ফল ও দুধ।"}'::jsonb, '{"en":"## A little more, not for two\n\nFrom the middle of pregnancy, most women need a little more food — about one extra small meal or a nutritious snack a day. ''Eating for two'' is a myth. So is eating less to keep the baby small for an easier birth: a baby who is too small faces more problems, not fewer.\n\n## A good plate every day\n\n- **Grains:** rice, atta roti, chira or muri, with some whole grains\n- **Protein:** dal, chickpeas, beans, fish, eggs, chicken or meat\n- **Small fish** such as mola, dhela and kachki, eaten whole with the bones, for calcium and vitamin A\n- **Dark green shak:** palong, lal shak, pui shak, kolmi shak, data shak\n- **Yellow and orange foods:** mishti kumra, carrot, ripe mango, ripe papaya\n- **Fruits:** guava, amloki, banana, orange and other seasonal fruits\n- **Milk or doi**, if you can\n- **Iodised salt**, in small amounts\n\nEating guava, lemon or amloki with meals helps your body absorb iron.\n\n## Drinks\n\n- Drink plenty of safe water through the day\n- Use tube-well water only if it has been tested safe for arsenic\n- Keep tea and coffee to a few cups a day, and not with meals\n- No alcohol\n\n## Food safety\n\n- Cook meat, fish and eggs well\n- Boil milk before drinking it\n- Wash fruit and vegetables in safe water\n- Avoid food that has been left uncovered or kept too long\n\n## Foods to be careful with\n\n- Green (unripe) papaya: many doctors advise avoiding it; ripe papaya is fine\n- Liver: best avoided or eaten only rarely, as very high vitamin A can harm the baby\n- Raw or half-cooked eggs and meat\n\n## Common myths\n\nFish, eggs, meat, milk, banana and pineapple in normal amounts are safe in pregnancy. ''Hot'' and ''cold'' food rules are not based on science. If family members restrict foods, ask your health worker to explain to them.\n\n## If you are thinking of fasting\n\nTalk to your doctor before fasting, for example in Ramadan. Health needs are different in each pregnancy.\n\n## When to get help\n\nTell your health worker if you cannot eat for more than a day, keep vomiting, are losing weight, or crave non-food things such as soil, ash or chalk — this can be a sign of anaemia.","bn":"## একটু বেশি, দুজনের সমান নয়\n\nগর্ভাবস্থার মাঝামাঝি থেকে বেশিরভাগ মায়ের একটু বেশি খাবার লাগে — দিনে মোটামুটি একবেলা বাড়তি অল্প খাবার বা একটা পুষ্টিকর নাশতা। ''দুজনের খাবার খেতে হবে'' — এটা ভুল ধারণা। আবার প্রসব সহজ করতে শিশুকে ছোট রাখার জন্য কম খাওয়াও ভুল: খুব ছোট শিশুর সমস্যা কমে না, বরং বাড়ে।\n\n## প্রতিদিনের ভালো থালা\n\n- **শস্য:** ভাত, আটার রুটি, চিড়া বা মুড়ি — কিছুটা লাল চাল বা লাল আটা\n- **আমিষ:** ডাল, ছোলা, শিমের বিচি, মাছ, ডিম, মুরগি বা মাংস\n- **ছোট মাছ** — মলা, ঢেলা, কাচকি — কাঁটাসহ খেলে ক্যালসিয়াম ও ভিটামিন এ মেলে\n- **গাঢ় সবুজ শাক:** পালং, লাল শাক, পুঁই, কলমি, ডাঁটা শাক\n- **হলুদ-কমলা খাবার:** মিষ্টিকুমড়া, গাজর, পাকা আম, পাকা পেঁপে\n- **ফল:** পেয়ারা, আমলকী, কলা, কমলা ও মৌসুমি ফল\n- সম্ভব হলে **দুধ বা দই**\n- অল্প পরিমাণে **আয়োডিনযুক্ত লবণ**\n\nখাবারের সাথে পেয়ারা, লেবু বা আমলকী খেলে শরীর আয়রন ভালোভাবে নিতে পারে।\n\n## পানীয়\n\n- সারাদিন প্রচুর নিরাপদ পানি পান করুন\n- টিউবওয়েলের পানি শুধু তখনই খাবেন, যদি আর্সেনিক পরীক্ষায় নিরাপদ পাওয়া যায়\n- চা-কফি দিনে কয়েক কাপের মধ্যে রাখুন, খাবারের সাথে নয়\n- মদ একেবারেই নয়\n\n## খাবারের নিরাপত্তা\n\n- মাংস, মাছ ও ডিম ভালোভাবে রান্না করুন\n- দুধ ফুটিয়ে খান\n- ফল ও সবজি নিরাপদ পানিতে ধুয়ে নিন\n- খোলা রাখা বা অনেকক্ষণ আগে রান্না করা খাবার এড়িয়ে চলুন\n\n## যেগুলোতে সাবধান\n\n- কাঁচা পেঁপে: অনেক ডাক্তার এড়াতে বলেন; পাকা পেঁপে খাওয়া যায়\n- কলিজা: না খাওয়াই ভালো, বা কালেভদ্রে অল্প — খুব বেশি ভিটামিন এ শিশুর ক্ষতি করতে পারে\n- কাঁচা বা আধা সেদ্ধ ডিম ও মাংস\n\n## প্রচলিত ভুল ধারণা\n\nস্বাভাবিক পরিমাণে মাছ, ডিম, মাংস, দুধ, কলা ও আনারস গর্ভাবস্থায় নিরাপদ। ''গরম'' আর ''ঠান্ডা'' খাবারের নিয়মের কোনো বৈজ্ঞানিক ভিত্তি নেই। পরিবারের কেউ খাবারে নিষেধ দিলে স্বাস্থ্যকর্মীকে তাঁদের বুঝিয়ে বলতে অনুরোধ করুন।\n\n## রোজা রাখতে চাইলে\n\nরোজা রাখার কথা ভাবলে আগে ডাক্তারের সাথে কথা বলুন। প্রতিটি গর্ভাবস্থার প্রয়োজন আলাদা।\n\n## কখন সাহায্য নেবেন\n\nএক দিনের বেশি কিছু খেতে না পারলে, বারবার বমি হলে, ওজন কমতে থাকলে, কিংবা মাটি, ছাই বা চকের মতো অখাদ্য খেতে খুব ইচ্ছা করলে স্বাস্থ্যকর্মীকে জানান — শেষেরটা রক্তস্বল্পতার লক্ষণ হতে পারে।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['pregnancy diet', 'nutrition', 'food', 'small fish', 'food safety', 'myths']::text[], false, 'in_review'::lp_review_status, 2013),
  ('pp-iron-folic-acid-calcium', 'article', 'scientific', 'mother', 'important', 'guideline', '💊', '{"en":"Iron–folic acid and calcium tablets","bn":"আয়রন-ফলিক অ্যাসিড ও ক্যালসিয়াম ট্যাবলেট"}'::jsonb, '{"en":"Daily iron–folic acid protects against anaemia; calcium, where prescribed, helps protect against pre-eclampsia. Take them the right way to get the most from them.","bn":"প্রতিদিনের আয়রন-ফলিক অ্যাসিড রক্তস্বল্পতা থেকে বাঁচায়; আর ডাক্তার দিলে ক্যালসিয়াম প্রি-এক্লাম্পসিয়া থেকে সুরক্ষা দিতে সাহায্য করে। সঠিক নিয়মে খেলে উপকার বেশি।"}'::jsonb, '{"en":"## Why iron and folic acid\n\nYour blood volume rises a lot in pregnancy, and the baby builds its own iron stores from yours. Anaemia is common among pregnant women in Bangladesh. It makes you tired and breathless, and it raises the risk of dangerous bleeding at birth, early birth and a small baby. WHO recommends a daily iron–folic acid tablet throughout pregnancy.\n\n## Why calcium\n\nMany women in Bangladesh get less calcium from food than they need. In such settings, WHO recommends calcium tablets in pregnancy to lower the risk of pre-eclampsia, a dangerous form of high blood pressure. Your health worker will tell you when to start, usually from the middle months, and how many to take.\n\n## How to take them\n\n- **Iron–folic acid:** one tablet a day, as your health worker advises. Take it with water or lemon water. If it upsets your stomach, take it at bedtime.\n- **Calcium:** as prescribed, often after meals.\n- **Keep them apart:** calcium reduces iron absorption, so take them at least two hours apart — for example, calcium after lunch and iron at night.\n- **Not with tea, coffee or milk:** these also reduce iron absorption. Leave an hour''s gap.\n- Vitamin C foods such as guava, amloki or lemon help iron work.\n\n## Normal side effects\n\n- Black stools are normal with iron.\n- Nausea, stomach upset or constipation can happen. Taking the tablet at night, and eating more fibre and drinking more water, usually helps.\n- Do not stop on your own. Tell your health worker, who may change the timing or the type of tablet.\n\n## How long\n\nContinue through pregnancy, and after the birth for as long as your health worker advises.\n\n## Safety\n\n- **Keep tablets locked away from children.** Iron tablets look like sweets, and too many can poison a young child. If a child swallows some, go to hospital at once.\n- Do not take extra tablets to ''catch up'' on missed days.\n- Do not buy extra vitamins without advice; more is not better.\n\n## Get help if\n\nYou feel very tired, breathless or dizzy, your heart races, or you look pale inside the eyelids or under the nails. Your haemoglobin may need checking.","bn":"## আয়রন ও ফলিক অ্যাসিড কেন\n\nগর্ভাবস্থায় শরীরে রক্তের পরিমাণ অনেক বাড়ে, আর শিশু মায়ের কাছ থেকেই নিজের আয়রনের মজুত গড়ে তোলে। বাংলাদেশে গর্ভবতী নারীদের মধ্যে রক্তস্বল্পতা বেশ সাধারণ। এতে ক্লান্তি আর শ্বাসকষ্ট হয়, প্রসবের সময় বিপজ্জনক রক্তক্ষরণ, অকালপ্রসব ও কম ওজনের শিশুর ঝুঁকিও বাড়ে। বিশ্ব স্বাস্থ্য সংস্থা পুরো গর্ভাবস্থায় প্রতিদিন আয়রন-ফলিক অ্যাসিড ট্যাবলেট খেতে বলে।\n\n## ক্যালসিয়াম কেন\n\nবাংলাদেশের অনেক নারী খাবার থেকে প্রয়োজনের চেয়ে কম ক্যালসিয়াম পান। এমন জায়গায় বিশ্ব স্বাস্থ্য সংস্থা গর্ভাবস্থায় ক্যালসিয়াম ট্যাবলেট দিতে বলে, যাতে প্রি-এক্লাম্পসিয়ার (গর্ভকালীন বিপজ্জনক উচ্চ রক্তচাপ) ঝুঁকি কমে। কখন শুরু করবেন — সাধারণত মাঝের মাসগুলো থেকে — আর কয়টা খাবেন, স্বাস্থ্যকর্মী বলে দেবেন।\n\n## কীভাবে খাবেন\n\n- **আয়রন-ফলিক অ্যাসিড:** স্বাস্থ্যকর্মীর পরামর্শমতো দিনে একটি। পানি বা লেবুপানি দিয়ে খান। পেটে অস্বস্তি হলে রাতে শোয়ার আগে খান।\n- **ক্যালসিয়াম:** যেভাবে লিখে দেওয়া হয়েছে, প্রায়ই খাবারের পরে।\n- **দুটো আলাদা সময়ে:** ক্যালসিয়াম আয়রনের শোষণ কমায়, তাই অন্তত দুই ঘণ্টার ব্যবধান রাখুন — যেমন দুপুরের খাবারের পর ক্যালসিয়াম, রাতে আয়রন।\n- **চা, কফি বা দুধের সাথে নয়:** এগুলোও আয়রনের শোষণ কমায়। এক ঘণ্টা ব্যবধান রাখুন।\n- পেয়ারা, আমলকী বা লেবুর মতো ভিটামিন সি-যুক্ত খাবার আয়রনকে কাজে লাগাতে সাহায্য করে।\n\n## স্বাভাবিক পার্শ্বপ্রতিক্রিয়া\n\n- আয়রন খেলে পায়খানা কালো হওয়া স্বাভাবিক।\n- বমি ভাব, পেটে অস্বস্তি বা কোষ্ঠকাঠিন্য হতে পারে। রাতে খাওয়া, বেশি আঁশযুক্ত খাবার আর বেশি পানি সাধারণত কাজে দেয়।\n- নিজে থেকে বন্ধ করবেন না। স্বাস্থ্যকর্মীকে জানান — তিনি খাওয়ার সময় বা ট্যাবলেটের ধরন বদলে দিতে পারেন।\n\n## কতদিন\n\nপুরো গর্ভাবস্থায়, আর প্রসবের পরও যতদিন স্বাস্থ্যকর্মী বলেন ততদিন খান।\n\n## নিরাপত্তা\n\n- **ট্যাবলেট শিশুদের নাগালের বাইরে, তালাবদ্ধ জায়গায় রাখুন।** আয়রন ট্যাবলেট দেখতে লজেন্সের মতো, আর বেশি খেলে ছোট শিশুর বিষক্রিয়া হতে পারে। কোনো শিশু গিলে ফেললে সাথে সাথে হাসপাতালে নিন।\n- বাদ পড়া দিনের জন্য বাড়তি ট্যাবলেট খাবেন না।\n- পরামর্শ ছাড়া বাড়তি ভিটামিন কিনবেন না — বেশি মানেই ভালো নয়।\n\n## কখন সাহায্য নেবেন\n\nখুব ক্লান্ত লাগলে, শ্বাসকষ্ট বা মাথা ঘুরলে, বুক ধড়ফড় করলে, কিংবা চোখের পাতার ভেতর বা নখ ফ্যাকাশে দেখালে। হিমোগ্লোবিন পরীক্ষা করা দরকার হতে পারে।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['iron', 'folic acid', 'calcium', 'anaemia', 'supplements', 'pre-eclampsia']::text[], false, 'in_review'::lp_review_status, 2014),
  ('pp-td-vaccine', 'article', 'scientific', 'mother', 'important', 'guideline', '💉', '{"en":"The Td vaccine in pregnancy","bn":"গর্ভাবস্থায় টিডি টিকা"}'::jsonb, '{"en":"The Td vaccine protects you and your newborn from tetanus. It is safe in pregnancy and free at EPI centres.","bn":"টিডি টিকা আপনাকে ও আপনার নবজাতককে ধনুষ্টংকার থেকে রক্ষা করে। গর্ভাবস্থায় এটা নিরাপদ, আর ইপিআই কেন্দ্রে বিনা মূল্যে পাওয়া যায়।"}'::jsonb, '{"en":"## What it protects against\n\nTd protects against tetanus and diphtheria. Newborn tetanus can follow if the cord is cut with an unclean blade or something dirty is put on it, and it is often fatal. When a mother is vaccinated, her antibodies pass to the baby and protect it in the first weeks of life. Bangladesh has greatly reduced newborn tetanus through this vaccine and through clean births.\n\n## Is it safe?\n\nYes. This vaccine has been given to pregnant women for many years. A sore, slightly swollen arm or a mild fever for a day or two is common and goes away on its own.\n\n## How many doses?\n\nIn Bangladesh''s EPI programme, women of childbearing age receive five doses over several years, which together give long-lasting protection:\n\n- Dose 1: at the first contact, from age 15\n- Dose 2: at least 4 weeks after dose 1\n- Dose 3: at least 6 months after dose 2\n- Dose 4: at least 1 year after dose 3\n- Dose 5: at least 1 year after dose 4\n\nIn pregnancy, what you need depends on your card:\n\n- **Never vaccinated, or not sure:** usually two doses at least four weeks apart, with the second at least two weeks before the due date. Then continue the schedule later.\n- **Some doses already:** the next dose in your schedule.\n- **All five doses:** you are protected; no more doses are needed.\n\nYour health worker will decide from your card.\n\n## Where to get it\n\nEPI centres, community clinics, Upazila Health Complexes and outreach sessions give Td free. Bring your vaccination card, and keep it safe for future pregnancies.\n\n## Other vaccines\n\n- Some other vaccines, such as influenza, may be advised in pregnancy. Ask your doctor.\n- Live vaccines such as MR (measles–rubella) are not given during pregnancy.\n\n## A clean birth matters too\n\nEven with the vaccine, give birth with a skilled attendant who uses clean hands and clean instruments. Never put ash, mud, oil or cow dung on the baby''s cord; use only what a health worker advises.","bn":"## কী থেকে রক্ষা করে\n\nটিডি টিকা ধনুষ্টংকার (টিটেনাস) আর ডিপথেরিয়া থেকে রক্ষা করে। অপরিষ্কার ব্লেড দিয়ে নাড়ি কাটলে বা নাড়িতে নোংরা কিছু লাগালে নবজাতকের ধনুষ্টংকার হতে পারে, আর তা প্রায়ই প্রাণঘাতী। মা টিকা নিলে তাঁর অ্যান্টিবডি শিশুর শরীরে যায় এবং জীবনের প্রথম সপ্তাহগুলোতে তাকে সুরক্ষা দেয়। এই টিকা আর পরিচ্ছন্ন প্রসবের মাধ্যমে বাংলাদেশে নবজাতকের ধনুষ্টংকার অনেক কমে এসেছে।\n\n## এটা কি নিরাপদ?\n\nহ্যাঁ। বহু বছর ধরে গর্ভবতী নারীদের এই টিকা দেওয়া হচ্ছে। বাহুতে ব্যথা, একটু ফোলা বা এক-দুই দিন হালকা জ্বর সাধারণ ব্যাপার, নিজে থেকেই সেরে যায়।\n\n## কয়টি ডোজ?\n\nবাংলাদেশের ইপিআই কর্মসূচিতে সন্তান ধারণক্ষম বয়সের নারীরা কয়েক বছরে মোট পাঁচটি ডোজ পান, যা দীর্ঘ সুরক্ষা দেয়:\n\n- ১ম ডোজ: প্রথম সুযোগে, ১৫ বছর বয়স থেকে\n- ২য় ডোজ: ১ম ডোজের অন্তত ৪ সপ্তাহ পর\n- ৩য় ডোজ: ২য় ডোজের অন্তত ৬ মাস পর\n- ৪র্থ ডোজ: ৩য় ডোজের অন্তত ১ বছর পর\n- ৫ম ডোজ: ৪র্থ ডোজের অন্তত ১ বছর পর\n\nগর্ভাবস্থায় কী লাগবে, তা আপনার কার্ডের ওপর নির্ভর করে:\n\n- **কখনো নেননি, বা মনে নেই:** সাধারণত অন্তত চার সপ্তাহ ব্যবধানে দুটি ডোজ, যার দ্বিতীয়টি প্রসবের সম্ভাব্য তারিখের অন্তত দুই সপ্তাহ আগে। পরে বাকি ডোজগুলো শেষ করুন।\n- **কিছু ডোজ নেওয়া আছে:** তালিকার পরের ডোজটি।\n- **পাঁচটিই নেওয়া:** আপনি সুরক্ষিত, আর ডোজ লাগবে না।\n\nকার্ড দেখে স্বাস্থ্যকর্মী ঠিক করে দেবেন।\n\n## কোথায় পাবেন\n\nইপিআই কেন্দ্র, কমিউনিটি ক্লিনিক, উপজেলা স্বাস্থ্য কমপ্লেক্স ও আউটরিচ টিকাদান কেন্দ্রে টিডি বিনা মূল্যে দেওয়া হয়। টিকা কার্ড সাথে নিন, আর পরের গর্ভধারণের জন্য যত্ন করে রেখে দিন।\n\n## অন্য টিকা\n\n- ইনফ্লুয়েঞ্জার মতো আরও কিছু টিকা গর্ভাবস্থায় দেওয়ার পরামর্শ আসতে পারে। ডাক্তারকে জিজ্ঞেস করুন।\n- এমআর (হাম-রুবেলা)-এর মতো জীবন্ত জীবাণুর টিকা গর্ভাবস্থায় দেওয়া হয় না।\n\n## পরিচ্ছন্ন প্রসবও জরুরি\n\nটিকা নেওয়া থাকলেও দক্ষ প্রসব সহায়তাকারীর হাতে প্রসব করান, যিনি পরিষ্কার হাত ও পরিষ্কার যন্ত্রপাতি ব্যবহার করেন। শিশুর নাড়িতে কখনো ছাই, মাটি, তেল বা গোবর লাগাবেন না; শুধু স্বাস্থ্যকর্মী যা বলেন তা-ই ব্যবহার করুন।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['td vaccine', 'tetanus', 'diphtheria', 'epi', 'vaccination card']::text[], false, 'in_review'::lp_review_status, 2015),
  ('pp-safe-activity-rest', 'article', 'scientific', 'shared', 'routine', 'guideline', '🚶‍♀️', '{"en":"Staying active and resting well in pregnancy","bn":"গর্ভাবস্থায় সক্রিয় থাকা ও ঠিকমতো বিশ্রাম"}'::jsonb, '{"en":"Unless your doctor says otherwise, regular gentle activity is good for you and your baby. Balance it with rest, and avoid heavy lifting.","bn":"ডাক্তার নিষেধ না করলে নিয়মিত হালকা শারীরিক কাজ আপনার ও শিশুর জন্য ভালো। সাথে বিশ্রাম নিন, আর ভারী জিনিস তোলা এড়িয়ে চলুন।"}'::jsonb, '{"en":"## Activity is safe and helpful\n\nWHO advises pregnant women without complications to do at least 150 minutes of moderate activity a week — about 30 minutes on most days. Moderate means you can still talk, but not sing. Regular activity can ease back pain, constipation and swelling, help control weight and blood sugar, improve sleep and mood, and prepare the body for labour.\n\n## Good choices\n\n- Walking — in the yard, on the roof or along a quiet road\n- Housework at an easy pace\n- Gentle stretches and pregnancy exercises a health worker shows you\n\nIf you were not active before, start with 10 minutes a day and build up slowly.\n\n## Avoid\n\n- Lifting heavy loads: full water pitchers or buckets, rice sacks, gas cylinders, or carrying a child on your hip for long\n- Activities with a risk of falling or a blow to the belly\n- Lying flat on your back for long periods in the second half of pregnancy\n- Exercising in great heat; drink water and rest in the shade\n- Climbing on stools or ladders\n\n## Rest\n\n- Try to rest for an hour or two during the day, especially in the later months, with your feet raised\n- From about 28 weeks, go to sleep on your side, not on your back. Either side is fine; many women find the left side comfortable\n- A pillow between the knees and another under the bump helps\n- The family can help most by taking over the heavy chores\n\n## Stop and get help if you have\n\n- Bleeding or fluid leaking from the vagina\n- Dizziness, fainting, chest pain, or breathlessness before you start\n- Regular painful tightening of the belly\n- Pain and swelling in one calf\n- The baby moving less than usual\n\nSome women — for example, those with a low-lying placenta, a risk of early labour or very high blood pressure — are asked to limit activity. Follow your doctor''s advice.","bn":"## শারীরিক কাজ নিরাপদ ও উপকারী\n\nজটিলতা না থাকলে বিশ্ব স্বাস্থ্য সংস্থা গর্ভবতী নারীদের সপ্তাহে অন্তত ১৫০ মিনিট মাঝারি ধরনের শারীরিক কাজ করতে বলে — মানে বেশিরভাগ দিন ৩০ মিনিটের মতো। মাঝারি মানে, কথা বলতে পারবেন কিন্তু গান গাইতে কষ্ট হবে। নিয়মিত নড়াচড়ায় কোমর ব্যথা, কোষ্ঠকাঠিন্য ও পা ফোলা কমে, ওজন ও রক্তে শর্করা নিয়ন্ত্রণে থাকে, ঘুম ও মন ভালো থাকে, আর শরীর প্রসবের জন্য তৈরি হয়।\n\n## ভালো কিছু উপায়\n\n- হাঁটা — উঠানে, ছাদে বা নিরিবিলি রাস্তায়\n- ধীরেসুস্থে ঘরের কাজ\n- স্বাস্থ্যকর্মী দেখিয়ে দেন এমন হালকা স্ট্রেচিং ও গর্ভকালীন ব্যায়াম\n\nআগে নিয়মিত হাঁটাচলা না করলে দিনে ১০ মিনিট দিয়ে শুরু করে ধীরে ধীরে বাড়ান।\n\n## এড়িয়ে চলুন\n\n- ভারী বোঝা তোলা: পানিভর্তি কলসি বা বালতি, চালের বস্তা, গ্যাস সিলিন্ডার, কিংবা অনেকক্ষণ শিশুকে কোমরে নিয়ে রাখা\n- যেসব কাজে পড়ে যাওয়া বা পেটে আঘাতের ঝুঁকি আছে\n- গর্ভাবস্থার দ্বিতীয় ভাগে অনেকক্ষণ চিত হয়ে শুয়ে থাকা\n- প্রচণ্ড গরমে ব্যায়াম; পানি পান করুন, ছায়ায় বিশ্রাম নিন\n- টুল বা মই বেয়ে ওঠা\n\n## বিশ্রাম\n\n- দিনে এক-দুই ঘণ্টা পা একটু উঁচু করে বিশ্রাম নেওয়ার চেষ্টা করুন, বিশেষ করে শেষের মাসগুলোতে\n- মোটামুটি ২৮ সপ্তাহ থেকে চিত হয়ে নয়, কাত হয়ে ঘুমাতে যান। যেকোনো পাশে হলেই চলে; অনেকে বাঁ কাতে আরাম পান\n- দুই হাঁটুর মাঝে একটা বালিশ আর পেটের নিচে আরেকটা বালিশ দিলে আরাম হয়\n- ভারী কাজগুলো পরিবারের অন্যরা নিয়ে নিলে সবচেয়ে বড় সাহায্য হয়\n\n## থেমে সাহায্য নিন যদি\n\n- যোনিপথে রক্তপাত বা পানি বের হয়\n- মাথা ঘোরে, অজ্ঞান ভাব হয়, বুকে ব্যথা হয়, বা কাজ শুরুর আগেই শ্বাসকষ্ট থাকে\n- পেট নিয়মিত ব্যথা করে শক্ত হয়ে আসে\n- এক পায়ের পেশিতে ব্যথা ও ফোলা থাকে\n- শিশু স্বাভাবিকের চেয়ে কম নড়ে\n\nকারো কারো — যেমন গর্ভফুল নিচে থাকলে, অকালপ্রসবের ঝুঁকি থাকলে বা রক্তচাপ খুব বেশি হলে — নড়াচড়া কমাতে বলা হয়। ডাক্তারের পরামর্শ মেনে চলুন।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['exercise', 'walking', 'rest', 'sleep position', 'heavy lifting']::text[], false, 'in_review'::lp_review_status, 2016),
  ('pp-medicines-in-pregnancy', 'article', 'scientific', 'shared', 'important', 'consensus', '⚠️', '{"en":"Medicines in pregnancy: no self-medication","bn":"গর্ভাবস্থায় ওষুধ: নিজে নিজে নয়"}'::jsonb, '{"en":"Many medicines are safe in pregnancy, but some can harm the baby. Take only what a doctor who knows you are pregnant has prescribed.","bn":"গর্ভাবস্থায় অনেক ওষুধ নিরাপদ, কিন্তু কিছু ওষুধ শিশুর ক্ষতি করতে পারে। শুধু সেই ওষুধ খান, যা আপনি গর্ভবতী জেনে ডাক্তার লিখে দিয়েছেন।"}'::jsonb, '{"en":"## Why it matters\n\nMost medicines reach the baby through the placenta. Some are safe, some need a different dose, and a few can cause birth defects or problems later in pregnancy. In Bangladesh it is easy to buy medicines at a pharmacy without a prescription — but in pregnancy, this is risky.\n\n## Simple rules\n\n- Tell every doctor, dentist and pharmacist that you are pregnant, or might be.\n- Take only the medicines prescribed for you in this pregnancy.\n- Do not use an old prescription, or a medicine that helped a relative or neighbour.\n- Ask before taking anything new — including painkillers, antibiotics, cough syrups, sleeping pills, creams and vitamins.\n- Herbal, kabiraji, ayurvedic and homeopathic remedies have not been proven safe in pregnancy. Tell your doctor about any you use.\n\n## Examples to avoid unless a doctor prescribes them\n\n- Painkillers such as ibuprofen, diclofenac and aspirin (a doctor may prescribe low-dose aspirin for a specific reason)\n- Some antibiotics\n- Acne creams or tablets containing retinoids\n- Some medicines for epilepsy, blood clots or blood pressure — these must be reviewed by a doctor, not stopped suddenly\n\nFor pain or fever, paracetamol is generally the first choice in pregnancy, but ask how much to take and for how long.\n\n## If you have a long-term illness\n\nDiabetes, high blood pressure, thyroid disease, epilepsy, asthma and depression all need treatment in pregnancy too. Stopping medicines suddenly can be more dangerous than continuing them. See your doctor — ideally before pregnancy — to switch to safer options if needed.\n\n## Tests and X-rays\n\nTell the radiographer you are pregnant. Ultrasound is safe. Some X-rays can still be done with protection if they are really needed.\n\n## Took something before you knew?\n\nThis is very common. Do not panic, and do not stop prescribed medicines on your own. Write down what you took, how much and when, and show your doctor.\n\n## Keep a list\n\nWrite all your medicines on your antenatal card or in your phone, and show the list at every visit.","bn":"## কেন এত গুরুত্বপূর্ণ\n\nবেশিরভাগ ওষুধ গর্ভফুলের মধ্য দিয়ে শিশুর কাছে পৌঁছায়। কিছু ওষুধ নিরাপদ, কিছুর মাত্রা বদলাতে হয়, আর কয়েকটি জন্মত্রুটি বা গর্ভাবস্থার পরের দিকে সমস্যা তৈরি করতে পারে। বাংলাদেশে প্রেসক্রিপশন ছাড়াই ফার্মেসি থেকে ওষুধ কেনা সহজ — কিন্তু গর্ভাবস্থায় এটা ঝুঁকিপূর্ণ।\n\n## সহজ কয়েকটি নিয়ম\n\n- প্রত্যেক ডাক্তার, দাঁতের ডাক্তার ও ফার্মাসিস্টকে জানান যে আপনি গর্ভবতী, বা হতে পারেন।\n- শুধু এই গর্ভাবস্থায় আপনার জন্য লেখা ওষুধ খান।\n- পুরোনো প্রেসক্রিপশন, বা আত্মীয়-প্রতিবেশীর উপকার হয়েছে এমন ওষুধ খাবেন না।\n- নতুন কিছু খাওয়ার আগে জিজ্ঞেস করুন — ব্যথার ওষুধ, অ্যান্টিবায়োটিক, কাশির সিরাপ, ঘুমের ওষুধ, মলম বা ভিটামিন, সবকিছু।\n- ভেষজ, কবিরাজি, আয়ুর্বেদিক বা হোমিওপ্যাথিক ওষুধ গর্ভাবস্থায় নিরাপদ বলে প্রমাণিত নয়। কিছু খেলে ডাক্তারকে জানান।\n\n## ডাক্তার না দিলে যেগুলো এড়াবেন — কিছু উদাহরণ\n\n- আইবুপ্রোফেন, ডাইক্লোফেনাক ও অ্যাসপিরিনের মতো ব্যথার ওষুধ (নির্দিষ্ট কারণে ডাক্তার কম মাত্রার অ্যাসপিরিন দিতে পারেন)\n- কিছু অ্যান্টিবায়োটিক\n- রেটিনয়েডযুক্ত ব্রণের ক্রিম বা ট্যাবলেট\n- মৃগী, রক্ত জমাট বাঁধা বা রক্তচাপের কিছু ওষুধ — এগুলো হঠাৎ বন্ধ নয়, ডাক্তার দেখে ঠিক করবেন\n\nব্যথা বা জ্বরে গর্ভাবস্থায় সাধারণত প্যারাসিটামলই প্রথম পছন্দ, তবে কতটুকু আর কতদিন খাবেন জিজ্ঞেস করে নিন।\n\n## দীর্ঘমেয়াদি অসুখ থাকলে\n\nডায়াবেটিস, উচ্চ রক্তচাপ, থাইরয়েড, মৃগী, হাঁপানি বা বিষণ্ণতার চিকিৎসা গর্ভাবস্থায়ও দরকার। হঠাৎ ওষুধ বন্ধ করা চালিয়ে যাওয়ার চেয়ে বেশি বিপজ্জনক হতে পারে। দরকার হলে নিরাপদ ওষুধে বদলাতে ডাক্তার দেখান — সম্ভব হলে গর্ভধারণের আগেই।\n\n## পরীক্ষা ও এক্স-রে\n\nএক্স-রে করার সময় জানান যে আপনি গর্ভবতী। আলট্রাসাউন্ড নিরাপদ। সত্যিই দরকার হলে সুরক্ষা নিয়ে কিছু এক্স-রে করা যায়।\n\n## জানার আগেই কিছু খেয়ে ফেলেছেন?\n\nএটা খুবই সাধারণ। ঘাবড়াবেন না, আর নিজে থেকে লেখা ওষুধ বন্ধ করবেন না। কী খেয়েছেন, কতটুকু, কবে — লিখে ডাক্তারকে দেখান।\n\n## একটা তালিকা রাখুন\n\nসব ওষুধের নাম গর্ভকালীন কার্ডে বা ফোনে লিখে রাখুন, আর প্রতিবার চেকআপে দেখান।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['medicines', 'self-medication', 'pharmacy', 'painkillers', 'herbal', 'x-ray']::text[], false, 'in_review'::lp_review_status, 2017),
  ('pp-gestational-diabetes-pre-eclampsia', 'article', 'scientific', 'shared', 'important', 'guideline', '🩺', '{"en":"Gestational diabetes and high blood pressure in pregnancy","bn":"গর্ভকালীন ডায়াবেটিস ও উচ্চ রক্তচাপ"}'::jsonb, '{"en":"Both are common, often silent and treatable. Regular check-ups catch them early, and knowing the warning signs of pre-eclampsia can save a life.","bn":"দুটোই প্রায়ই দেখা যায়, অনেক সময় কোনো উপসর্গ থাকে না, আর চিকিৎসা আছে। নিয়মিত চেকআপে আগেই ধরা পড়ে, আর প্রি-এক্লাম্পসিয়ার বিপদচিহ্ন জানা থাকলে জীবন বাঁচে।"}'::jsonb, '{"en":"## Gestational diabetes (GDM)\n\nThis is high blood sugar that first appears in pregnancy. It usually causes no symptoms. Women of South Asian origin, including Bangladeshi women, have a higher chance of GDM. Other risk factors are being overweight, a parent or sibling with diabetes, GDM in a previous pregnancy, a previous large baby, and being older.\n\n**The test:** an oral glucose tolerance test — a blood test, then a glucose drink, then more blood tests — usually at 24–28 weeks, and earlier for women at higher risk. Come fasting, as instructed.\n\n**If you have GDM:**\n\n- Regular, balanced meals through the day, with fewer sweets and smaller portions of white rice\n- A short walk after meals\n- Checking blood sugar as advised\n- Some women need insulin or tablets; these are safe and protect the baby\n\nUncontrolled GDM can make the baby very large, make the birth harder and cause low blood sugar in the newborn. GDM usually goes away after the birth, but it raises the chance of type 2 diabetes later, so have your sugar checked after the birth and keep up healthy habits.\n\n## High blood pressure and pre-eclampsia\n\nA blood pressure of 140/90 or higher is high. Some women have it before pregnancy; others develop it during pregnancy.\n\n**Pre-eclampsia** is high blood pressure after 20 weeks with protein in the urine or other signs of strain on the body. It can damage the mother''s kidneys, liver and brain, and slow the baby''s growth. **Eclampsia** — fits caused by pre-eclampsia — is an important cause of mothers'' deaths in Bangladesh, and good care can prevent most of these deaths.\n\n**Prevention and care:**\n\n- Have your blood pressure and urine checked at every visit\n- Take calcium if it is prescribed\n- Women at high risk may be prescribed low-dose aspirin; take it only if a doctor prescribes it\n- If you have high blood pressure, take your medicine exactly as prescribed\n\nHospitals have medicines to prevent and treat fits, and the doctor may advise an early birth if mother or baby is at risk.\n\n## Go to hospital immediately if you have\n\n- A severe headache that does not go away\n- Blurred vision or flashing lights\n- Pain under the ribs or in the upper belly\n- Sudden swelling of the face, hands or feet\n- Vomiting late in pregnancy\n- Fits, or feeling very unwell\n\nThese signs can also appear after the birth, up to several weeks later.","bn":"## গর্ভকালীন ডায়াবেটিস (GDM)\n\nগর্ভাবস্থায় প্রথমবার রক্তে শর্করা বেশি পাওয়া গেলে তাকে গর্ভকালীন ডায়াবেটিস বলে। সাধারণত কোনো উপসর্গ থাকে না। বাংলাদেশিসহ দক্ষিণ এশীয় নারীদের এর ঝুঁকি বেশি। আরও ঝুঁকি বাড়ায় — বেশি ওজন, বাবা-মা বা ভাই-বোনের ডায়াবেটিস, আগের গর্ভে ডায়াবেটিস, আগের সন্তান বড় আকারের হওয়া, আর বেশি বয়স।\n\n**পরীক্ষা:** ওজিটিটি (OGTT) — প্রথমে রক্ত পরীক্ষা, তারপর গ্লুকোজ মেশানো পানি খেয়ে আবার রক্ত পরীক্ষা। সাধারণত ২৪–২৮ সপ্তাহে করা হয়, ঝুঁকি বেশি হলে আরও আগে। নির্দেশমতো খালি পেটে আসুন।\n\n**গর্ভকালীন ডায়াবেটিস হলে:**\n\n- সারাদিন নিয়ম করে সুষম খাবার; মিষ্টি কম, সাদা ভাত অল্প পরিমাণে\n- খাওয়ার পর অল্প একটু হাঁটা\n- পরামর্শমতো রক্তে শর্করা মাপা\n- কারো কারো ইনসুলিন বা ট্যাবলেট লাগে — এগুলো নিরাপদ, শিশুকে সুরক্ষা দেয়\n\nনিয়ন্ত্রণে না থাকলে শিশু অনেক বড় হতে পারে, প্রসব কঠিন হতে পারে, আর জন্মের পর শিশুর রক্তে শর্করা কমে যেতে পারে। প্রসবের পর সাধারণত এটা চলে যায়, তবে পরে টাইপ ২ ডায়াবেটিসের ঝুঁকি বাড়ে। তাই প্রসবের পর শর্করা পরীক্ষা করান আর স্বাস্থ্যকর অভ্যাস চালিয়ে যান।\n\n## উচ্চ রক্তচাপ ও প্রি-এক্লাম্পসিয়া\n\nরক্তচাপ ১৪০/৯০ বা তার বেশি হলে তা উচ্চ রক্তচাপ। কারো গর্ভধারণের আগে থেকেই থাকে, কারো গর্ভাবস্থায় শুরু হয়।\n\n**প্রি-এক্লাম্পসিয়া** হলো ২০ সপ্তাহের পর উচ্চ রক্তচাপ, সাথে প্রস্রাবে প্রোটিন বা শরীরের ওপর চাপের অন্য লক্ষণ। এতে মায়ের কিডনি, লিভার ও মস্তিষ্কের ক্ষতি হতে পারে, শিশুর বৃদ্ধিও কমে যেতে পারে। **এক্লাম্পসিয়া** — প্রি-এক্লাম্পসিয়া থেকে খিঁচুনি — বাংলাদেশে মাতৃমৃত্যুর একটি বড় কারণ, আর ভালো সেবায় এই মৃত্যুর বেশিরভাগ ঠেকানো যায়।\n\n**প্রতিরোধ ও যত্ন:**\n\n- প্রতিবার চেকআপে রক্তচাপ ও প্রস্রাব পরীক্ষা করান\n- ক্যালসিয়াম দেওয়া হলে নিয়মিত খান\n- ঝুঁকি বেশি হলে ডাক্তার কম মাত্রার অ্যাসপিরিন দিতে পারেন — শুধু ডাক্তার দিলেই খাবেন\n- উচ্চ রক্তচাপ থাকলে ওষুধ ঠিক যেভাবে লেখা, সেভাবে খান\n\nখিঁচুনি প্রতিরোধ ও চিকিৎসার ওষুধ হাসপাতালে আছে। মা বা শিশুর ঝুঁকি থাকলে ডাক্তার আগেভাগে প্রসব করানোর পরামর্শ দিতে পারেন।\n\n## এগুলো হলে সাথে সাথে হাসপাতালে যান\n\n- তীব্র মাথাব্যথা, যা কমছে না\n- ঝাপসা দেখা বা চোখে আলোর ঝলকানি\n- পাঁজরের নিচে বা পেটের ওপরের দিকে ব্যথা\n- হঠাৎ মুখ, হাত বা পা ফুলে যাওয়া\n- গর্ভাবস্থার শেষ দিকে বমি\n- খিঁচুনি, বা খুব অসুস্থ বোধ করা\n\nএই লক্ষণগুলো প্রসবের পরেও, কয়েক সপ্তাহ পর্যন্ত, দেখা দিতে পারে।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['gestational diabetes', 'gdm', 'high blood pressure', 'pre-eclampsia', 'eclampsia', 'glucose test']::text[], false, 'in_review'::lp_review_status, 2018),
  ('pp-feelings-mental-health', 'article', 'scientific', 'shared', 'important', 'guideline', '💗', '{"en":"Feelings in pregnancy and your mental health","bn":"গর্ভাবস্থায় মন ও মানসিক স্বাস্থ্য"}'::jsonb, '{"en":"Joy, worry and mood swings are all normal in pregnancy. But feeling low or anxious most of the time is a health problem, and it can be treated.","bn":"গর্ভাবস্থায় আনন্দ, দুশ্চিন্তা, হঠাৎ মন বদলানো — সবই স্বাভাবিক। কিন্তু বেশিরভাগ সময় মন খারাপ বা উদ্বিগ্ন থাকা একটি স্বাস্থ্য সমস্যা, আর এর চিকিৎসা আছে।"}'::jsonb, '{"en":"## Many feelings, all normal\n\nPregnancy brings hormone changes, tiredness and big changes in life. It is normal to feel excited one day and tearful or worried the next. Many women worry about the baby''s health, the birth, money or how the family will treat them. Fathers can feel anxious too.\n\n## When it is more than mood swings\n\nDepression and anxiety in pregnancy are common, and they are not a sign of weakness. Talk to a health worker if, for two weeks or more, you:\n\n- feel sad, empty or hopeless most of the day\n- lose interest in things you used to enjoy\n- feel constant worry, fear or panic\n- cannot sleep even when tired, or sleep much more than usual\n- feel worthless or guilty\n- find it hard to concentrate or make decisions\n- do not feel connected to the pregnancy\n\n## Get help urgently if\n\n- you have thoughts of harming yourself or ending your life\n- you hear or see things that others do not\n- you feel unable to look after yourself\n\nTell someone you trust, and go to a hospital or call 999 now.\n\n## What helps\n\n- **Talk.** Share your feelings with your husband, mother, sister or a friend.\n- **Tell your health worker** at your check-up. A few simple questions can find problems early.\n- **Rest and routine:** regular meals, sleep, a daily walk and time outdoors.\n- **Slow breathing:** breathe in for a count of 4 and out for a count of 6, for a few minutes, when you feel anxious.\n- **Limit what drains you:** frightening stories, constant comparison, harsh comments.\n- **Counselling** works well. If medicine is needed, there are options that can be used in pregnancy; a doctor will weigh the benefits with you.\n\n## For the family\n\n- Listen without judging. Do not say ''just be happy'' or ''it is all in your head''.\n- Share the housework so she can rest.\n- Protect her from blame, especially about the baby''s sex or her looks.\n- Go with her to a doctor if she agrees.\n\n## Where to call\n\nShastho Batayon (16263) gives health advice by phone and can tell you where to find support near you. Getting help early is good for you and for your baby.","bn":"## নানা অনুভূতি, সবই স্বাভাবিক\n\nগর্ভাবস্থায় হরমোনের পরিবর্তন, ক্লান্তি আর জীবনের বড় বদল আসে। এক দিন খুব আনন্দ, পরের দিন কান্না পাওয়া বা দুশ্চিন্তা — এটা স্বাভাবিক। অনেক মা শিশুর স্বাস্থ্য, প্রসব, টাকাপয়সা বা পরিবার কেমন আচরণ করবে তা নিয়ে চিন্তা করেন। বাবারাও উদ্বিগ্ন হতে পারেন।\n\n## যখন শুধু মন খারাপের চেয়ে বেশি\n\nগর্ভাবস্থায় বিষণ্ণতা (ডিপ্রেশন) ও উদ্বেগ খুব সাধারণ, আর এটা দুর্বলতার লক্ষণ নয়। দুই সপ্তাহ বা তার বেশি সময় ধরে নিচের বিষয়গুলো থাকলে স্বাস্থ্যকর্মীকে বলুন:\n\n- দিনের বেশিরভাগ সময় মন খারাপ, ফাঁকা বা আশাহীন লাগে\n- আগে যা ভালো লাগত, তাতে আর আগ্রহ নেই\n- সারাক্ষণ দুশ্চিন্তা, ভয় বা আতঙ্ক\n- ক্লান্ত থাকলেও ঘুম আসে না, বা স্বাভাবিকের চেয়ে অনেক বেশি ঘুম\n- নিজেকে মূল্যহীন বা অপরাধী মনে হয়\n- মনোযোগ দিতে বা সিদ্ধান্ত নিতে কষ্ট হয়\n- গর্ভের সন্তানের সাথে কোনো টান অনুভব হয় না\n\n## জরুরি সাহায্য নিন যদি\n\n- নিজের ক্ষতি করার বা জীবন শেষ করে দেওয়ার চিন্তা আসে\n- অন্যরা শোনে না বা দেখে না এমন কিছু শোনেন বা দেখেন\n- নিজের যত্ন নিতে পারছেন না মনে হয়\n\nবিশ্বস্ত কাউকে জানান, আর এখনই হাসপাতালে যান বা ৯৯৯-এ ফোন করুন।\n\n## যা সাহায্য করে\n\n- **কথা বলুন।** স্বামী, মা, বোন বা বান্ধবীর সাথে মনের কথা ভাগ করুন।\n- **চেকআপে স্বাস্থ্যকর্মীকে জানান।** কয়েকটি সহজ প্রশ্নেই সমস্যা আগে ধরা পড়ে।\n- **বিশ্রাম ও নিয়ম:** সময়মতো খাওয়া, ঘুম, প্রতিদিন একটু হাঁটা, খোলা বাতাসে কিছুক্ষণ।\n- **ধীরে শ্বাস:** দুশ্চিন্তা হলে কয়েক মিনিট ৪ গুনে শ্বাস নিন, ৬ গুনে ছাড়ুন।\n- **যা মন ভারী করে তা কমান:** ভয়ের গল্প, অন্যের সাথে তুলনা, কটু কথা।\n- **কাউন্সেলিং** খুব কাজ করে। ওষুধ দরকার হলে গর্ভাবস্থায় ব্যবহার করা যায় এমন ওষুধও আছে; ডাক্তার আপনার সাথে লাভ-ক্ষতি বিবেচনা করবেন।\n\n## পরিবারের জন্য\n\n- বিচার না করে মন দিয়ে শুনুন। ''খুশি থাকো তো'' বা ''এসব তোমার মনের ভুল'' বলবেন না।\n- ঘরের কাজ ভাগ করে নিন, যাতে তিনি বিশ্রাম পান।\n- শিশু ছেলে না মেয়ে, বা তাঁর চেহারা নিয়ে দোষারোপ থেকে তাঁকে আগলে রাখুন।\n- তিনি রাজি হলে ডাক্তারের কাছে সাথে যান।\n\n## কোথায় ফোন করবেন\n\nস্বাস্থ্য বাতায়ন (১৬২৬৩) ফোনে স্বাস্থ্য পরামর্শ দেয়, আর কাছাকাছি কোথায় সহায়তা পাবেন তা জানাতে পারে। আগেভাগে সাহায্য নেওয়া আপনার ও শিশুর দুজনের জন্যই ভালো।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['mental health', 'depression', 'anxiety', 'mood', 'feelings', 'support']::text[], false, 'in_review'::lp_review_status, 2019),
  ('pp-father-role-pregnancy', 'article', 'general', 'father', 'important', 'consensus', '👨', '{"en":"The father''s role in pregnancy","bn":"গর্ভাবস্থায় বাবার ভূমিকা"}'::jsonb, '{"en":"A father''s support in pregnancy helps the mother stay healthier and calmer, and makes the birth safer. Here are concrete things you can do from today.","bn":"গর্ভাবস্থায় বাবার সহায়তা মাকে সুস্থ ও শান্ত রাখে, প্রসবকেও নিরাপদ করে। আজ থেকেই করতে পারেন এমন কিছু নির্দিষ্ট কাজ।"}'::jsonb, '{"en":"## You matter from day one\n\nThe pregnancy happens in her body, but the baby belongs to you both. When fathers are involved, mothers tend to go to more check-ups, eat and rest better, feel less stressed, and reach help faster in an emergency.\n\n## At the clinic\n\n- Go to as many check-ups as you can — take leave in advance\n- Know the due date, her blood group and her medicines\n- Ask the doctor your own questions\n\n## At home\n\n- Take over heavy work: carrying water, lifting, washing big loads\n- Cook, clean or shop so she can rest for an hour in the day\n- Make sure she eats an extra meal and takes her tablets\n- Keep the home smoke-free. If you smoke, stop, or at least smoke far away outside\n\n## Learn the danger signs\n\nLearn the pregnancy danger signs together: bleeding, severe headache or blurred vision, fits, high fever, severe belly pain, difficulty breathing, the baby moving less, waters breaking early, and sudden swelling of the face or hands. Know which hospital you will go to, by day or by night.\n\n## Make the birth plan\n\nYou are often the one who arranges:\n\n- transport, with drivers'' phone numbers saved\n- money set aside for emergencies\n- two blood donors with a matching group\n- who will stay with her, and who will look after other children\n\n## Support her feelings\n\n- Ask every day, ''How are you feeling?'' — and listen\n- Stand by her when relatives criticise or pressure her\n- Never blame her for the baby''s sex; it is decided by the father''s sperm\n- Notice if she seems low for weeks, and help her get support\n\n## Bond with your baby\n\nIn the later months the baby can hear sounds from outside the womb. Talk or sing softly to your baby, and feel the kicks with your hand on her belly.\n\n## If you work away from home\n\nMany fathers in Bangladesh work in another city or abroad. Call often, send money for check-ups on time, and ask a trusted person to take her to the hospital when needed. Plan to be there around the birth if you can.","bn":"## প্রথম দিন থেকেই আপনি গুরুত্বপূর্ণ\n\nগর্ভধারণ হয় স্ত্রীর শরীরে, কিন্তু সন্তান আপনাদের দুজনের। বাবারা যুক্ত থাকলে মায়েরা সাধারণত বেশি চেকআপে যান, ভালো খান ও বিশ্রাম নেন, দুশ্চিন্তা কম থাকে, আর জরুরি অবস্থায় দ্রুত সাহায্য পান।\n\n## চেকআপে\n\n- যতগুলো সম্ভব চেকআপে সাথে যান — আগে থেকে ছুটি নিয়ে রাখুন\n- প্রসবের সম্ভাব্য তারিখ, স্ত্রীর রক্তের গ্রুপ আর ওষুধগুলো জেনে রাখুন\n- নিজের প্রশ্নগুলোও ডাক্তারকে করুন\n\n## ঘরে\n\n- ভারী কাজ নিজে নিন: পানি টানা, ভারী জিনিস তোলা, বড় কাপড় ধোয়া\n- রান্না, ঘর পরিষ্কার বা বাজার করুন, যাতে তিনি দিনে এক ঘণ্টা বিশ্রাম পান\n- তিনি বাড়তি একবেলা খাচ্ছেন আর ট্যাবলেট খাচ্ছেন কিনা খেয়াল রাখুন\n- ঘর ধোঁয়ামুক্ত রাখুন। ধূমপান করলে ছেড়ে দিন, অন্তত বাইরে দূরে গিয়ে করুন\n\n## বিপদচিহ্ন জেনে নিন\n\nদুজনে মিলে গর্ভাবস্থার বিপদচিহ্নগুলো শিখুন: রক্তপাত, তীব্র মাথাব্যথা বা ঝাপসা দেখা, খিঁচুনি, বেশি জ্বর, পেটে তীব্র ব্যথা, শ্বাসকষ্ট, শিশুর নড়াচড়া কমে যাওয়া, সময়ের আগে পানি ভাঙা, হঠাৎ মুখ বা হাত ফোলা। দিনে হোক বা রাতে — কোন হাসপাতালে যাবেন, ঠিক করে রাখুন।\n\n## প্রসব পরিকল্পনা করুন\n\nসাধারণত আপনিই এগুলোর ব্যবস্থা করেন:\n\n- যানবাহন, চালকদের ফোন নম্বর সেভ করা\n- জরুরি খরচের টাকা আলাদা রাখা\n- একই গ্রুপের দুজন রক্তদাতা\n- কে তাঁর সাথে থাকবেন, আর অন্য সন্তানদের কে দেখবেন\n\n## তাঁর মনের পাশে থাকুন\n\n- প্রতিদিন জিজ্ঞেস করুন, ''কেমন লাগছে?'' — আর মন দিয়ে শুনুন\n- আত্মীয়রা সমালোচনা বা চাপ দিলে তাঁর পাশে দাঁড়ান\n- শিশু ছেলে না মেয়ে হবে, তার জন্য তাঁকে কখনো দোষ দেবেন না; এটা ঠিক হয় বাবার শুক্রাণু থেকে\n- কয়েক সপ্তাহ ধরে মন খারাপ দেখলে সাহায্য পেতে সহায়তা করুন\n\n## গর্ভের শিশুর সাথে বন্ধন\n\nশেষের মাসগুলোতে শিশু বাইরের শব্দ শুনতে পায়। শিশুর সাথে কথা বলুন, নরম সুরে গান শোনান, আর স্ত্রীর পেটে হাত রেখে লাথি অনুভব করুন।\n\n## দূরে কাজ করলে\n\nবাংলাদেশের অনেক বাবা অন্য শহরে বা বিদেশে কাজ করেন। ঘন ঘন ফোন করুন, চেকআপের টাকা সময়মতো পাঠান, আর দরকারে তাঁকে হাসপাতালে নেওয়ার জন্য বিশ্বস্ত কাউকে দায়িত্ব দিন। সম্ভব হলে প্রসবের সময় পাশে থাকার পরিকল্পনা করুন।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['father', 'husband', 'support', 'danger signs', 'birth plan', 'bonding']::text[], false, 'in_review'::lp_review_status, 2020),
  ('pp-working-while-pregnant', 'article', 'general', 'mother', 'routine', 'consensus', '💼', '{"en":"Working while pregnant","bn":"গর্ভাবস্থায় কর্মজীবন"}'::jsonb, '{"en":"Most women can keep working safely through pregnancy with a few changes. Know your rights and tell your employer what you need.","bn":"কিছু পরিবর্তন করে বেশিরভাগ নারী গর্ভাবস্থায় নিরাপদে কাজ চালিয়ে যেতে পারেন। নিজের অধিকার জানুন, আর কী দরকার তা কর্মস্থলে জানান।"}'::jsonb, '{"en":"## Can I keep working?\n\nYes, in most cases. Whether you work in an office, a garment factory, a school, in the fields or at home, you can usually carry on with some adjustments. Your doctor may advise changes if there are complications.\n\n## Know your rights in Bangladesh\n\n- Under the Bangladesh Labour Act, women workers who have worked for an employer for the required period are entitled to paid maternity leave — 16 weeks in total, around the birth.\n- Government employees have six months of paid maternity leave.\n- An employer should not dismiss a woman because she is pregnant.\n- Rules can differ by sector and can change. Ask your HR office, union or welfare officer for the exact rules where you work.\n\n## Telling your employer\n\nMany women wait until after 12 weeks. But if your work involves heavy lifting, chemicals, radiation or long hours of standing, tell them earlier so changes can be made. Ask for:\n\n- time off for antenatal check-ups\n- lighter tasks instead of heavy lifting\n- a chair, and short breaks to sit, eat and use the toilet\n- day shifts instead of night shifts, if possible\n\n## Looking after yourself at work\n\n- Carry water and small snacks such as muri, biscuits or fruit\n- Sit with your feet up during breaks; if you sit all day, get up and walk a little every hour\n- Wear comfortable, flat shoes\n- Stay away from strong chemicals, pesticides, paint fumes and smoke\n- Avoid lifting heavy loads, especially from the floor\n- Travel at less crowded times if you can, and ask for a seat on the bus\n\n## Plan ahead\n\n- Discuss your leave dates and handover early\n- Think about childcare and breastfeeding for when you return; ask whether your workplace has a day-care centre or a breastfeeding room\n\n## Stop and get help if\n\nYou have bleeding, fluid leaking, regular tightening of the belly, a severe headache, blurred vision, dizziness, or the baby moving less. Your health comes before any job.","bn":"## কাজ কি চালিয়ে যেতে পারব?\n\nবেশিরভাগ ক্ষেত্রেই হ্যাঁ। অফিস, পোশাক কারখানা, স্কুল, খেত বা ঘরে — যেখানেই কাজ করুন, কিছু পরিবর্তন এনে সাধারণত কাজ চালিয়ে যাওয়া যায়। জটিলতা থাকলে ডাক্তার পরিবর্তনের পরামর্শ দিতে পারেন।\n\n## বাংলাদেশে আপনার অধিকার\n\n- বাংলাদেশ শ্রম আইন অনুযায়ী, নির্দিষ্ট সময় ধরে একই প্রতিষ্ঠানে কাজ করা নারী শ্রমিকেরা প্রসবের আগে-পরে মিলিয়ে মোট ১৬ সপ্তাহ সবেতন মাতৃত্বকালীন ছুটি পান।\n- সরকারি চাকরিজীবীরা ছয় মাসের সবেতন মাতৃত্বকালীন ছুটি পান।\n- গর্ভবতী হওয়ার কারণে কাউকে চাকরি থেকে বাদ দেওয়া উচিত নয়।\n- খাতভেদে নিয়ম আলাদা হতে পারে, বদলাতেও পারে। আপনার কর্মস্থলের সঠিক নিয়ম এইচআর, ট্রেড ইউনিয়ন বা কল্যাণ কর্মকর্তার কাছ থেকে জেনে নিন।\n\n## কর্মস্থলে জানানো\n\nঅনেকে ১২ সপ্তাহ পার হওয়া পর্যন্ত অপেক্ষা করেন। কিন্তু কাজে ভারী জিনিস তোলা, রাসায়নিক, রেডিয়েশন বা দীর্ঘক্ষণ দাঁড়িয়ে থাকা থাকলে আগেই জানান, যাতে কাজে পরিবর্তন আনা যায়। চেয়ে নিন:\n\n- গর্ভকালীন চেকআপের জন্য ছুটি\n- ভারী কাজের বদলে হালকা কাজ\n- বসার একটা চেয়ার, আর বসা, খাওয়া ও টয়লেটে যাওয়ার জন্য ছোট বিরতি\n- সম্ভব হলে রাতের বদলে দিনের শিফট\n\n## কাজের সময় নিজের যত্ন\n\n- পানি আর মুড়ি, বিস্কুট বা ফলের মতো হালকা নাশতা সাথে রাখুন\n- বিরতিতে পা উঁচু করে বসুন; সারাদিন বসে কাজ করলে প্রতি ঘণ্টায় উঠে একটু হাঁটুন\n- আরামদায়ক, সমান জুতা পরুন\n- কড়া রাসায়নিক, কীটনাশক, রঙের গন্ধ ও ধোঁয়া থেকে দূরে থাকুন\n- ভারী বোঝা তুলবেন না, বিশেষ করে মেঝে থেকে\n- সম্ভব হলে কম ভিড়ের সময় যাতায়াত করুন, বাসে বসার জায়গা চেয়ে নিন\n\n## আগে থেকে পরিকল্পনা\n\n- ছুটির তারিখ আর কাজ বুঝিয়ে দেওয়ার বিষয়ে আগেভাগে কথা বলুন\n- কাজে ফেরার পর শিশুর দেখাশোনা আর বুকের দুধ খাওয়ানোর কথা ভাবুন; কর্মস্থলে ডে-কেয়ার বা দুধ খাওয়ানোর কক্ষ আছে কিনা জেনে নিন\n\n## থেমে সাহায্য নিন যদি\n\nরক্তপাত, পানি বের হওয়া, পেট নিয়মিত শক্ত হয়ে আসা, তীব্র মাথাব্যথা, ঝাপসা দেখা, মাথা ঘোরা বা শিশুর নড়াচড়া কমে যায়। যেকোনো চাকরির চেয়ে আপনার স্বাস্থ্য আগে।"}'::jsonb, '{}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['work', 'working mother', 'maternity leave', 'employer', 'rights']::text[], false, 'in_review'::lp_review_status, 2021),
  ('pp-normal-birth-caesarean', 'article', 'scientific', 'shared', 'important', 'consensus', '🏥', '{"en":"Normal birth or caesarean: facts to discuss with your doctor","bn":"স্বাভাবিক প্রসব নাকি সিজার: ডাক্তারের সাথে আলোচনার তথ্য"}'::jsonb, '{"en":"A caesarean is a life-saving operation when there is a medical reason. When mother and baby are healthy, a normal birth is usually the safer choice.","bn":"চিকিৎসার কারণ থাকলে সিজার জীবন বাঁচানো অপারেশন। মা ও শিশু সুস্থ থাকলে সাধারণত স্বাভাবিক প্রসবই বেশি নিরাপদ।"}'::jsonb, '{"en":"## Both have a place\n\nMost healthy women can give birth normally (vaginally). A caesarean section is an operation to deliver the baby through a cut in the belly and the womb. When it is needed, it saves the lives of mothers and babies. When it is not needed, it adds risk without adding benefit. In Bangladesh, many caesareans are done without a clear medical reason, especially in private facilities, so it helps to decide with good information.\n\n## Common medical reasons for a caesarean\n\n- The placenta lies over the opening of the womb (placenta praevia)\n- The baby is lying sideways, or in some bottom-first (breech) positions\n- Labour does not progress despite good care, or the baby cannot pass through the pelvis\n- Signs that the baby is in distress\n- Severe pre-eclampsia or some other illnesses, when the baby must be born quickly\n- Two or more previous caesareans\n\nSome of these are known in advance; others arise during labour.\n\n## Normal birth: what to know\n\n- Recovery is usually quicker; you can walk and care for your baby sooner\n- Breastfeeding often starts more easily\n- Lower risk of infection, heavy bleeding and blood clots\n- Fewer problems in later pregnancies\n- Labour pain is real. Support, moving around, breathing and a companion help; ask what pain relief the facility offers\n\n## Caesarean: what to know\n\n- Safe in a good facility, but it is major surgery\n- Longer recovery, and pain at the wound; lifting and caring for the baby is harder at first\n- Risks of infection, bleeding and blood clots\n- Each caesarean raises the risk of placenta problems in later pregnancies\n- After one caesarean, a normal birth next time may still be possible — ask your doctor\n\n## Questions to ask your doctor\n\n- Is there a medical reason for a caesarean in my case?\n- What happens if we wait for labour to start naturally?\n- What are the risks for me and the baby with each option?\n- If a caesarean is planned, can it wait until 39 weeks unless there is a reason not to?\n- What support and pain relief are available for a normal birth?\n\n## Choose a facility you trust\n\nChoose a facility that supports normal birth and can also do an emergency caesarean at any hour. Fear of pain, family pressure or wanting a particular date are things to talk through with your doctor; on their own they are not medical reasons.","bn":"## দুটোরই প্রয়োজন আছে\n\nবেশিরভাগ সুস্থ নারী স্বাভাবিকভাবে (যোনিপথে) সন্তান জন্ম দিতে পারেন। সিজার হলো পেট ও জরায়ু কেটে শিশুকে বের করার অপারেশন। দরকার হলে এটা মা ও শিশুর জীবন বাঁচায়। দরকার না থাকলে লাভ ছাড়াই ঝুঁকি বাড়ায়। বাংলাদেশে, বিশেষ করে বেসরকারি হাসপাতালে, অনেক সিজার স্পষ্ট চিকিৎসার কারণ ছাড়াই হয় — তাই ভালোভাবে জেনে সিদ্ধান্ত নেওয়া জরুরি।\n\n## সিজারের সাধারণ চিকিৎসাগত কারণ\n\n- গর্ভফুল জরায়ুর মুখের ওপর থাকা (প্লাসেন্টা প্রিভিয়া)\n- শিশু আড়াআড়ি থাকা, বা কিছু ক্ষেত্রে পা/নিতম্ব নিচে থাকা (ব্রিচ)\n- ভালো যত্নের পরও প্রসব এগোচ্ছে না, বা শিশু শ্রোণিপথ দিয়ে বের হতে পারছে না\n- শিশু বিপদে আছে এমন লক্ষণ\n- মারাত্মক প্রি-এক্লাম্পসিয়া বা অন্য কিছু অসুখ, যখন দ্রুত প্রসব দরকার\n- আগে দুই বা তার বেশি সিজার\n\nএর কিছু আগে থেকেই জানা যায়, কিছু প্রসবের সময় দেখা দেয়।\n\n## স্বাভাবিক প্রসব: যা জানা দরকার\n\n- সাধারণত দ্রুত সেরে ওঠা যায়; তাড়াতাড়ি হাঁটা ও শিশুর যত্ন নেওয়া যায়\n- বুকের দুধ খাওয়ানো প্রায়ই সহজে শুরু হয়\n- সংক্রমণ, বেশি রক্তক্ষরণ ও রক্ত জমাট বাঁধার ঝুঁকি কম\n- পরের গর্ভধারণে সমস্যা কম\n- প্রসবের ব্যথা সত্যি। সাহস দেওয়া, হাঁটাচলা, শ্বাসের কৌশল আর পাশে একজন সঙ্গী সাহায্য করে; হাসপাতালে ব্যথা কমানোর কী ব্যবস্থা আছে জেনে নিন\n\n## সিজার: যা জানা দরকার\n\n- ভালো হাসপাতালে নিরাপদ, তবে এটা বড় অপারেশন\n- সেরে উঠতে বেশি সময় লাগে, কাটা জায়গায় ব্যথা থাকে; শুরুতে শিশুকে তোলা ও যত্ন নেওয়া কঠিন\n- সংক্রমণ, রক্তক্ষরণ ও রক্ত জমাট বাঁধার ঝুঁকি\n- প্রতিটি সিজারে পরের গর্ভে গর্ভফুলের সমস্যার ঝুঁকি বাড়ে\n- একবার সিজারের পরও পরের বার স্বাভাবিক প্রসব সম্ভব হতে পারে — ডাক্তারকে জিজ্ঞেস করুন\n\n## ডাক্তারকে যা জিজ্ঞেস করবেন\n\n- আমার ক্ষেত্রে সিজারের কোনো চিকিৎসাগত কারণ আছে কি?\n- স্বাভাবিকভাবে ব্যথা ওঠার জন্য অপেক্ষা করলে কী হবে?\n- প্রতিটি পথে আমার ও শিশুর কী কী ঝুঁকি?\n- সিজার আগে থেকে ঠিক হলে, বিশেষ কারণ না থাকলে, ৩৯ সপ্তাহ পর্যন্ত কি অপেক্ষা করা যায়?\n- স্বাভাবিক প্রসবে কী সহায়তা আর ব্যথা কমানোর কী ব্যবস্থা আছে?\n\n## ভরসার হাসপাতাল বেছে নিন\n\nএমন হাসপাতাল বেছে নিন, যেখানে স্বাভাবিক প্রসবে উৎসাহ দেওয়া হয়, আবার দিন-রাত যেকোনো সময় জরুরি সিজারও করা যায়। ব্যথার ভয়, পরিবারের চাপ বা নির্দিষ্ট একটা তারিখের ইচ্ছা — এগুলো ডাক্তারের সাথে খোলাখুলি আলোচনা করুন; শুধু এগুলো চিকিৎসাগত কারণ নয়।"}'::jsonb, '{}'::jsonb, 4, -189, 0, '{}'::text[], 'any', ARRAY['normal birth', 'vaginal birth', 'caesarean', 'c-section', 'birth choices']::text[], false, 'in_review'::lp_review_status, 2022),
  ('pp-signs-of-labour', 'article', 'scientific', 'shared', 'important', 'consensus', '⏱️', '{"en":"Signs of labour: true or false?","bn":"প্রসববেদনার লক্ষণ: আসল নাকি মিথ্যা?"}'::jsonb, '{"en":"Learn how real labour feels, how it differs from practice contractions, and when to leave for the hospital.","bn":"আসল প্রসববেদনা কেমন, অনুশীলনের ব্যথা থেকে তা কীভাবে আলাদা, আর কখন হাসপাতালের পথে রওনা দেবেন — জেনে নিন।"}'::jsonb, '{"en":"## Practice contractions (false labour)\n\nFrom the middle of pregnancy, the belly may tighten for a short time and then relax. These Braxton Hicks contractions are the womb practising. They:\n\n- come at irregular times\n- do not get stronger or closer together\n- are felt mostly in the front of the belly\n- often ease when you rest, walk, change position or drink water\n\n## Signs that labour is starting\n\n- **Contractions that become regular**, last longer, get stronger and come closer together, and do not stop with rest. The pain often starts in the back and moves to the front.\n- **A show:** sticky mucus with a little blood from the vagina.\n- **Waters breaking:** a gush or a steady trickle of fluid that you cannot control.\n- Some women also have backache, loose stools, or a strong urge to push.\n\n## When to go to the hospital\n\nIn Bangladesh, the journey can take time, especially at night or in the rain, so leave early rather than late. Go when:\n\n- **contractions come every 5 minutes or closer**, each lasting about a minute, for an hour — or sooner if you live far away or this is not your first baby, as later labours are often faster\n- **your waters break**, even without pain\n\n## Go immediately if\n\n- There is bleeding — more than a streak of blood in mucus\n- The water is green or brown, or smells bad\n- The baby moves less\n- There is severe, constant pain in the belly\n- You have a fever, severe headache, blurred vision or fits\n- Contractions start before 37 weeks\n- You see or feel the cord after the waters break — call 999 and go at once\n\n## In early labour at home\n\n- Keep the hospital bag and documents by the door\n- Eat light food and drink water\n- Walk, sway and change positions\n- Note when contractions start and how often they come\n- Call your transport and the person who will go with you\n\n## Avoid\n\n- Pushing before the health worker says it is time\n- Anyone pressing on the belly to push the baby out\n- Medicines or injections to speed up labour at home\n- Waiting at home overnight, hoping it will settle","bn":"## অনুশীলনের ব্যথা (মিথ্যা প্রসববেদনা)\n\nগর্ভাবস্থার মাঝামাঝি থেকে পেট মাঝে মাঝে অল্প সময়ের জন্য শক্ত হয়ে আবার নরম হয়ে যেতে পারে। একে ব্র্যাক্সটন হিকস বলে — জরায়ু যেন অনুশীলন করছে। এই ব্যথা:\n\n- অনিয়মিত সময়ে আসে\n- বাড়ে না, কাছাকাছিও আসে না\n- বেশিরভাগ পেটের সামনের দিকে টের পাওয়া যায়\n- বিশ্রাম নিলে, হাঁটলে, পাশ বদলালে বা পানি খেলে প্রায়ই কমে যায়\n\n## প্রসব শুরুর লক্ষণ\n\n- **নিয়মিত ব্যথা**, যা আরও লম্বা, আরও তীব্র ও আরও ঘন ঘন হয়, বিশ্রামেও থামে না। ব্যথা প্রায়ই পিঠে শুরু হয়ে সামনে আসে।\n- **শো:** যোনিপথে একটু রক্তমেশানো আঠালো শ্লেষ্মা।\n- **পানি ভাঙা:** হঠাৎ অনেকটা পানি বা ধীরে ধীরে চুইয়ে পড়া পানি, যা আটকে রাখা যায় না।\n- কারো কোমরে ব্যথা, পাতলা পায়খানা বা চাপ দেওয়ার তীব্র ইচ্ছাও হয়।\n\n## কখন হাসপাতালে যাবেন\n\nবাংলাদেশে, বিশেষ করে রাতে বা বৃষ্টিতে, পথে সময় লাগতে পারে — তাই দেরি না করে আগেভাগে রওনা দিন। যাবেন যখন:\n\n- **৫ মিনিট বা তারও কম পরপর ব্যথা আসে**, প্রতিটা প্রায় এক মিনিট থাকে, আর এভাবে এক ঘণ্টা চলে — দূরে থাকলে বা এটা প্রথম সন্তান না হলে আরও আগে, কারণ পরের প্রসব প্রায়ই দ্রুত হয়\n- **পানি ভেঙে যায়**, ব্যথা না থাকলেও\n\n## সাথে সাথে যাবেন যদি\n\n- রক্তপাত হয় — শ্লেষ্মায় সামান্য দাগের চেয়ে বেশি\n- পানি সবুজ বা বাদামি হয়, বা দুর্গন্ধ থাকে\n- শিশু কম নড়ে\n- পেটে তীব্র, একটানা ব্যথা থাকে\n- জ্বর, তীব্র মাথাব্যথা, ঝাপসা দেখা বা খিঁচুনি হয়\n- ৩৭ সপ্তাহের আগেই ব্যথা শুরু হয়\n- পানি ভাঙার পর নাড়ি দেখা যায় বা টের পান — ৯৯৯-এ ফোন করুন, এখনই রওনা দিন\n\n## প্রসবের শুরুতে ঘরে থাকলে\n\n- হাসপাতালের ব্যাগ আর কাগজপত্র দরজার পাশে রাখুন\n- হালকা খাবার খান, পানি পান করুন\n- হাঁটুন, দোল খান, অবস্থান বদলান\n- কখন ব্যথা শুরু হলো আর কত পরপর আসছে, লিখে রাখুন\n- যানবাহন আর যিনি সাথে যাবেন, তাঁকে ফোন করুন\n\n## যা করবেন না\n\n- স্বাস্থ্যকর্মী বলার আগেই চাপ দেওয়া\n- শিশুকে বের করতে কাউকে দিয়ে পেটে চাপ দেওয়ানো\n- ঘরে প্রসব দ্রুত করার ওষুধ বা ইনজেকশন নেওয়া\n- রাতটা কেটে গেলে ঠিক হয়ে যাবে ভেবে ঘরে অপেক্ষা করা"}'::jsonb, '{}'::jsonb, 3, -84, 0, '{}'::text[], 'any', ARRAY['labour', 'contractions', 'braxton hicks', 'waters breaking', 'false labour']::text[], false, 'in_review'::lp_review_status, 2023),
  ('pp-choosing-birth-place', 'article', 'scientific', 'shared', 'important', 'guideline', '🏥', '{"en":"Choosing where to give birth","bn":"কোথায় প্রসব করাবেন — আগেই ঠিক করুন"}'::jsonb, '{"en":"Give birth in a health facility with a skilled birth attendant. Choose the place in the middle months, and visit it before labour starts.","bn":"দক্ষ প্রসব সহায়তাকারী আছে এমন স্বাস্থ্যকেন্দ্রে প্রসব করান। মাঝের মাসগুলোতেই জায়গা ঠিক করুন, আর ব্যথা ওঠার আগে একবার ঘুরে আসুন।"}'::jsonb, '{"en":"## Why a facility birth\n\nMost births go well. But some problems — heavy bleeding after birth, a baby who does not breathe, or a long, blocked labour — happen suddenly, even to healthy women. In a facility with a skilled birth attendant (a trained doctor, nurse or midwife), these can be handled within minutes. At home, the delay can cost a life.\n\n## Options in Bangladesh\n\n- **Union Health and Family Welfare Centres** — some provide normal births\n- **Mother and Child Welfare Centres** and **Upazila Health Complexes**\n- **District hospitals and medical college hospitals**, which can manage complications\n- **Private clinics and hospitals**, and **NGO facilities**\n\n## Questions to ask when choosing\n\n- Is a skilled birth attendant there 24 hours a day?\n- Can they do a caesarean and give a blood transfusion at any hour? If not, where do they refer, and how quickly?\n- Is there care for small or sick newborns?\n- How far is it, and how will we get there at night or in the rainy season?\n- What does a normal birth cost? A caesarean?\n- Can a family member stay with me during labour?\n- Do they support skin-to-skin contact and breastfeeding in the first hour?\n- Do the staff treat women with respect?\n\nYour antenatal doctor can help you decide, especially if your pregnancy has a higher risk and needs a bigger hospital.\n\n## If you are going to your parents'' home\n\nMany women go to their parents'' home for the birth. Choose a facility near there, and move early — before about 36 weeks. Take your antenatal card and reports, and tell the new facility about your pregnancy so far.\n\n## Visit before the day\n\nGo once with your husband or companion. Learn how to get in at night, where the labour room is, and what to bring.\n\n## If the baby comes before you get there\n\nCall a skilled attendant or 999. Dry the baby, place it skin-to-skin on the mother''s chest and cover both. Do not pull on the cord, and put nothing on it unless a health worker advises. Go to the facility as soon as possible so mother and baby can be checked.","bn":"## কেন স্বাস্থ্যকেন্দ্রে প্রসব\n\nবেশিরভাগ প্রসব ভালোভাবেই হয়। কিন্তু কিছু সমস্যা — প্রসবের পর অতিরিক্ত রক্তক্ষরণ, শিশুর শ্বাস না নেওয়া, বা দীর্ঘ আটকে যাওয়া প্রসব — হঠাৎ দেখা দেয়, সুস্থ মায়েরও। দক্ষ প্রসব সহায়তাকারী (প্রশিক্ষিত ডাক্তার, নার্স বা মিডওয়াইফ) থাকলে স্বাস্থ্যকেন্দ্রে কয়েক মিনিটেই এগুলো সামলানো যায়। ঘরে থাকলে সেই দেরিতে জীবন চলে যেতে পারে।\n\n## বাংলাদেশে যেসব জায়গা আছে\n\n- **ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র** — কিছু কেন্দ্রে স্বাভাবিক প্রসব হয়\n- **মা ও শিশু কল্যাণ কেন্দ্র** এবং **উপজেলা স্বাস্থ্য কমপ্লেক্স**\n- **জেলা সদর হাসপাতাল ও মেডিকেল কলেজ হাসপাতাল** — জটিলতা সামলাতে পারে\n- **বেসরকারি ক্লিনিক ও হাসপাতাল**, এবং **এনজিও পরিচালিত কেন্দ্র**\n\n## বেছে নেওয়ার সময় যা জিজ্ঞেস করবেন\n\n- দিন-রাত ২৪ ঘণ্টা দক্ষ প্রসব সহায়তাকারী থাকেন কি?\n- যেকোনো সময় সিজার ও রক্ত দেওয়া যায় কি? না গেলে কোথায় পাঠান, কত দ্রুত?\n- ছোট বা অসুস্থ নবজাতকের চিকিৎসার ব্যবস্থা আছে কি?\n- কত দূরে, আর রাতে বা বর্ষায় কীভাবে যাব?\n- স্বাভাবিক প্রসবে কত খরচ? সিজারে কত?\n- প্রসবের সময় পরিবারের একজন কি পাশে থাকতে পারবেন?\n- জন্মের পরপর মায়ের বুকে শিশুকে রাখা আর প্রথম ঘণ্টায় বুকের দুধ খাওয়ানোয় তাঁরা সহায়তা করেন কি?\n- কর্মীরা কি মায়েদের সাথে সম্মানের সাথে আচরণ করেন?\n\nগর্ভকালীন সেবা দেওয়া ডাক্তার সিদ্ধান্ত নিতে সাহায্য করতে পারেন, বিশেষ করে যদি আপনার গর্ভাবস্থা ঝুঁকিপূর্ণ হয় আর বড় হাসপাতাল দরকার হয়।\n\n## বাবার বাড়ি গেলে\n\nঅনেক মা প্রসবের জন্য বাবার বাড়ি যান। সেখানকার কাছাকাছি একটা স্বাস্থ্যকেন্দ্র বেছে নিন, আর আগেভাগে — মোটামুটি ৩৬ সপ্তাহের আগেই — চলে যান। গর্ভকালীন কার্ড ও রিপোর্ট সাথে নিন, নতুন জায়গার ডাক্তারকে এ পর্যন্ত গর্ভাবস্থার সব কথা জানান।\n\n## আগে একবার ঘুরে আসুন\n\nস্বামী বা সঙ্গীকে নিয়ে একবার যান। রাতে কোন দিক দিয়ে ঢুকতে হয়, প্রসব কক্ষ কোথায়, কী কী নিতে হবে — জেনে আসুন।\n\n## পৌঁছানোর আগেই শিশু চলে এলে\n\nদক্ষ সহায়তাকারী ডাকুন বা ৯৯৯-এ ফোন করুন। শিশুকে মুছে মায়ের খোলা বুকে রাখুন, দুজনকে ঢেকে দিন। নাড়ি ধরে টানবেন না, আর স্বাস্থ্যকর্মী না বললে নাড়িতে কিছু লাগাবেন না। মা ও শিশুকে পরীক্ষা করাতে যত দ্রুত সম্ভব স্বাস্থ্যকেন্দ্রে যান।"}'::jsonb, '{}'::jsonb, 3, -189, 0, '{}'::text[], 'any', ARRAY['facility birth', 'skilled birth attendant', 'hospital', 'birth place', 'upazila health complex']::text[], false, 'in_review'::lp_review_status, 2024),
  ('pp-pregnancy-customs-bangladesh', 'article', 'cultural', 'family', 'educational', 'tradition', '🌼', '{"en":"Pregnancy customs in Bangladesh: what helps, what to avoid","bn":"গর্ভাবস্থার প্রচলিত রীতি: কোনটা উপকারী, কোনটা এড়াবেন"}'::jsonb, '{"en":"Many family customs around pregnancy show love and care. A few can delay care or harm mother and baby. Here is a kind, practical guide.","bn":"গর্ভাবস্থা ঘিরে পরিবারের অনেক রীতিতে ভালোবাসা আর যত্ন প্রকাশ পায়। কিছু রীতি আবার চিকিৎসায় দেরি করায় বা মা-শিশুর ক্ষতি করে। এখানে সহজ ও আন্তরিক একটি গাইড।"}'::jsonb, '{"en":"## Customs that help\n\n- **Extra care from family:** relatives cooking her favourite dishes and sending fruit or fish. Wonderful, as long as the food is varied and fresh.\n- **Saadh:** the celebration in the later months, when the mother-to-be is fed her favourite foods and blessed, brings joy and support. Keep it restful so she is not worn out by guests.\n- **Going to her parents'' home for the birth:** good support, as long as a skilled facility nearby has been chosen.\n- **Rest and lighter work:** families who share the chores protect the mother.\n- **Prayers and blessings:** they bring comfort and hope, and they sit alongside medical care.\n\n## Customs that are harmless\n\n- Staying indoors during an eclipse, not cutting things, or not going near certain trees at night. These beliefs have no scientific basis, but they do no harm as long as they never stop a woman going to a check-up or to hospital.\n- Not buying baby things before the birth. Still prepare the basics — clean clothes and cloths, and the hospital bag — so nothing is rushed.\n\n## Customs to avoid, and why\n\n- **Eating less so the baby stays small:** an underfed baby is weaker, not easier to deliver. The mother needs more food, not less.\n- **Food restrictions** — no fish, eggs, meat, milk or certain fruits, or ''hot'' and ''cold'' food rules. These take away nutrients that mother and baby need.\n- **Keeping the pregnancy hidden in the early months:** this delays the first check-up, folic acid and important tests. Tell your health worker early, even if you wait to tell others.\n- **Heavy work ''to make the birth easy'':** it does not help and can cause harm.\n- **Staying at home in labour** or calling someone without training: complications can come suddenly.\n- **Pressing or pushing on the belly** to speed up the birth: this can injure mother and baby.\n- **Putting ash, oil, turmeric or cow dung on the cord:** these can cause infection, including tetanus.\n- **Blaming the mother** for a daughter, a miscarriage or a difficult birth: no one is to blame, and the stress harms her health.\n\n## Talking with elders\n\nElders mean well and have a lifetime of experience. Listen with respect, gently explain what the doctor said, and invite them to come along to a check-up. When a doctor or health worker they respect explains things, families often change their minds.","bn":"## যে রীতিগুলো উপকারী\n\n- **পরিবারের বাড়তি যত্ন:** আত্মীয়রা প্রিয় খাবার রান্না করে দেন, ফল-মাছ পাঠান। খুব ভালো, যদি খাবার নানা রকম ও টাটকা হয়।\n- **সাধ:** শেষের দিকের মাসে হবু মাকে পছন্দের খাবার খাইয়ে দোয়া-আশীর্বাদ করার এই অনুষ্ঠান আনন্দ আর ভরসা দেয়। শুধু খেয়াল রাখুন, অতিথির ভিড়ে মা যেন ক্লান্ত না হয়ে পড়েন।\n- **প্রসবের জন্য বাবার বাড়ি যাওয়া:** খুব ভালো সহায়তা — যদি কাছাকাছি দক্ষ সেবার একটা কেন্দ্র আগে থেকে ঠিক করা থাকে।\n- **বিশ্রাম ও হালকা কাজ:** যে পরিবার ঘরের কাজ ভাগ করে নেয়, তারা মাকে সুরক্ষা দেয়।\n- **দোয়া ও আশীর্বাদ:** মনে শান্তি আর আশা দেয়, চিকিৎসার পাশাপাশি চলে।\n\n## যে রীতিগুলো ক্ষতিকর নয়\n\n- গ্রহণের সময় ঘরে থাকা, কিছু না কাটা, কিংবা রাতে নির্দিষ্ট কিছু গাছের কাছে না যাওয়া। এসব বিশ্বাসের বৈজ্ঞানিক ভিত্তি নেই, তবে যতক্ষণ এগুলো চেকআপে বা হাসপাতালে যাওয়া আটকায় না, ততক্ষণ ক্ষতি নেই।\n- জন্মের আগে শিশুর জিনিস না কেনা। তবুও জরুরি জিনিস — পরিষ্কার জামা ও কাপড়, হাসপাতালের ব্যাগ — গুছিয়ে রাখুন, যাতে শেষ মুহূর্তে তাড়াহুড়ো না হয়।\n\n## যে রীতিগুলো এড়াবেন, এবং কেন\n\n- **শিশু ছোট রাখতে কম খাওয়া:** কম খাওয়ানো শিশু দুর্বল হয়, প্রসব সহজ হয় না। মায়ের দরকার বেশি খাবার, কম নয়।\n- **খাবারে নিষেধ** — মাছ, ডিম, মাংস, দুধ বা কিছু ফল না খাওয়া, কিংবা ''গরম-ঠান্ডা'' খাবারের নিয়ম। এতে মা ও শিশু দরকারি পুষ্টি থেকে বঞ্চিত হয়।\n- **প্রথম কয়েক মাস গর্ভধারণের কথা লুকিয়ে রাখা:** এতে প্রথম চেকআপ, ফলিক অ্যাসিড আর জরুরি পরীক্ষায় দেরি হয়। অন্যদের পরে জানালেও স্বাস্থ্যকর্মীকে আগেই জানান।\n- **''প্রসব সহজ করতে'' ভারী কাজ করা:** এতে উপকার হয় না, ক্ষতি হতে পারে।\n- **প্রসববেদনা উঠলে ঘরে থাকা** বা অপ্রশিক্ষিত কাউকে ডাকা: জটিলতা হঠাৎ আসতে পারে।\n- **প্রসব দ্রুত করতে পেটে চাপ দেওয়া বা ঠেলা:** এতে মা ও শিশু আঘাত পেতে পারে।\n- **নাড়িতে ছাই, তেল, হলুদ বা গোবর লাগানো:** এতে ধনুষ্টংকারসহ সংক্রমণ হতে পারে।\n- **মাকে দোষ দেওয়া** — মেয়ে সন্তান, গর্ভপাত বা কঠিন প্রসবের জন্য: এতে কারো দোষ নেই, আর মানসিক চাপ তাঁর স্বাস্থ্যের ক্ষতি করে।\n\n## মুরুব্বিদের সাথে কথা বলা\n\nমুরুব্বিরা ভালো চান, তাঁদের জীবনভর অভিজ্ঞতাও আছে। সম্মান দিয়ে শুনুন, ডাক্তার কী বলেছেন নরমভাবে বুঝিয়ে বলুন, আর তাঁদের একবার চেকআপে সাথে যেতে বলুন। ভরসার কোনো ডাক্তার বা স্বাস্থ্যকর্মী বুঝিয়ে বললে পরিবার প্রায়ই মত বদলায়।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['customs', 'traditions', 'saadh', 'food taboos', 'elders', 'beliefs']::text[], false, 'in_review'::lp_review_status, 2025),
  ('pp-hospital-bag-checklist', 'checklist', 'general', 'shared', 'routine', 'consensus', '🎒', '{"en":"Hospital bag checklist","bn":"হাসপাতালের ব্যাগের তালিকা"}'::jsonb, '{"en":"Pack by about 36 weeks so you can leave at any hour. Keep the bag and the documents where everyone at home can find them.","bn":"মোটামুটি ৩৬ সপ্তাহের মধ্যে ব্যাগ গুছিয়ে ফেলুন, যাতে যেকোনো সময় বের হতে পারেন। ব্যাগ আর কাগজপত্র এমন জায়গায় রাখুন, যা বাড়ির সবাই জানে।"}'::jsonb, '{"en":"Pack the bag by about 36 weeks — earlier if your doctor expects an early birth or you live far from the hospital. Put the documents in a plastic folder at the top. Tell your husband and family where the bag is.\n\nGovernment hospitals may not provide everything, so bring basics such as a bedsheet, a plate and a glass.","bn":"মোটামুটি ৩৬ সপ্তাহের মধ্যে ব্যাগ গুছিয়ে ফেলুন — ডাক্তার আগে প্রসবের আশঙ্কা করলে বা হাসপাতাল দূরে হলে আরও আগে। কাগজপত্র একটা প্লাস্টিকের ফোল্ডারে ভরে সবার ওপরে রাখুন। ব্যাগ কোথায় আছে, স্বামী ও পরিবারকে জানিয়ে রাখুন।\n\nসরকারি হাসপাতালে সবকিছু না-ও পাওয়া যেতে পারে, তাই বিছানার চাদর, থালা ও গ্লাসের মতো দরকারি জিনিস নিয়ে যান।"}'::jsonb, '{"items":{"en":["Documents: antenatal card and all test and ultrasound reports","Documents: national ID cards of mother and husband, and any voucher or insurance papers","Documents: mother''s blood group written down, and phone numbers of blood donors, transport and family","Money in cash, and mobile banking with enough balance","Mobile phone and charger","Mother: 2–3 loose dresses or maxis that open at the front for breastfeeding, and an orna or shawl","Mother: underwear and plenty of maternity pads or clean, soft cloths","Mother: towel, soap, toothbrush, toothpaste, comb and slippers","Mother: bedsheet, a light blanket, plate, glass, spoon and a water bottle","Mother: light snacks such as biscuits, dates or fruit","Baby: 3–4 soft cotton outfits, caps and socks","Baby: several soft, clean cloths or a kantha to dry and wrap the baby","Baby: nappies or clean cloth nappies","Baby: a warm wrap or blanket, even in summer","Companion: a change of clothes and toiletries"],"bn":["কাগজপত্র: গর্ভকালীন কার্ড আর সব পরীক্ষা ও আলট্রাসাউন্ডের রিপোর্ট","কাগজপত্র: মা ও স্বামীর জাতীয় পরিচয়পত্র, আর কোনো ভাউচার বা বিমার কাগজ থাকলে","কাগজপত্র: মায়ের রক্তের গ্রুপ লেখা কাগজ, আর রক্তদাতা, যানবাহন ও পরিবারের ফোন নম্বর","নগদ টাকা, আর যথেষ্ট ব্যালান্সসহ মোবাইল ব্যাংকিং","মোবাইল ফোন ও চার্জার","মায়ের জন্য: বুকের দুধ খাওয়াতে সামনে খোলা যায় এমন ২–৩টি ঢিলেঢালা জামা বা ম্যাক্সি, আর ওড়না বা শাল","মায়ের জন্য: অন্তর্বাস আর যথেষ্ট ম্যাটারনিটি প্যাড বা পরিষ্কার নরম কাপড়","মায়ের জন্য: তোয়ালে, সাবান, টুথব্রাশ, টুথপেস্ট, চিরুনি ও স্যান্ডেল","মায়ের জন্য: বিছানার চাদর, হালকা কাঁথা, থালা, গ্লাস, চামচ ও পানির বোতল","মায়ের জন্য: বিস্কুট, খেজুর বা ফলের মতো হালকা নাশতা","শিশুর জন্য: ৩–৪ সেট নরম সুতির জামা, টুপি ও মোজা","শিশুর জন্য: শিশুকে মোছা ও জড়ানোর জন্য কয়েকটি নরম পরিষ্কার কাপড় বা কাঁথা","শিশুর জন্য: ডায়াপার বা পরিষ্কার কাপড়ের ন্যাপি","শিশুর জন্য: গরমকালেও একটা উষ্ণ চাদর বা কম্বল","সঙ্গীর জন্য: এক সেট কাপড় ও টুকিটাকি দরকারি জিনিস"]},"avoid":{"en":["Kajal or surma for the baby''s eyes","Oil to put in the baby''s nose or ears","Honey, sugar water or any other feed for the baby — breast milk is all the baby needs"],"bn":["শিশুর চোখে দেওয়ার কাজল বা সুরমা","শিশুর নাকে বা কানে দেওয়ার তেল","মধু, চিনির পানি বা অন্য কোনো খাবার — শিশুর জন্য মায়ের দুধই যথেষ্ট"]}}'::jsonb, 2, -84, 0, '{}'::text[], 'any', ARRAY['hospital bag', 'packing', 'documents', 'baby clothes', 'checklist']::text[], false, 'in_review'::lp_review_status, 2026),
  ('pp-birth-plan-checklist', 'checklist', 'general', 'shared', 'important', 'guideline', '📝', '{"en":"Birth plan checklist","bn":"প্রসব পরিকল্পনার তালিকা"}'::jsonb, '{"en":"A birth plan answers the key questions before labour: where, how you will get there, with what money, which blood donor, and who will be with the mother.","bn":"প্রসব পরিকল্পনা ব্যথা ওঠার আগেই জরুরি প্রশ্নগুলোর উত্তর ঠিক করে রাখে: কোথায়, কীভাবে যাবেন, কোন টাকায়, কোন রক্তদাতা, আর মায়ের পাশে কে থাকবেন।"}'::jsonb, '{"en":"Make the plan together by about 32 weeks. Write it on paper, and give a copy to the husband and one other family member. Stick it on the wall or keep it in the hospital bag, and update it if anything changes.","bn":"মোটামুটি ৩২ সপ্তাহের মধ্যে দুজনে মিলে পরিকল্পনা করুন। কাগজে লিখে স্বামী ও পরিবারের আরেকজনকে একটা করে কপি দিন। দেয়ালে লাগিয়ে রাখুন বা হাসপাতালের ব্যাগে রাখুন, আর কিছু বদলালে হালনাগাদ করুন।"}'::jsonb, '{"items":{"en":["The chosen facility, with its address and phone number","A back-up facility that can do a caesarean and a blood transfusion","Transport for day and night: a driver''s or ambulance number, plus a second option","Money saved for the birth and a separate emergency fund, and who can withdraw it at any hour","Mother''s blood group noted, and at least two willing donors with a matching group, with phone numbers","The person who will stay with the mother in hospital","Who will look after other children, elders and the home","Who can make decisions in an emergency if the husband is away — agreed in advance","Hospital bag packed by 36 weeks","Everyone at home knows the danger signs and the signs of labour","Antenatal card and reports kept together in one folder","Your wishes: a companion in labour, skin-to-skin contact and breastfeeding in the first hour","After the birth: rest, help at home, postnatal check-ups and family planning"],"bn":["বেছে নেওয়া স্বাস্থ্যকেন্দ্র, তার ঠিকানা ও ফোন নম্বর","বিকল্প একটা স্বাস্থ্যকেন্দ্র, যেখানে সিজার ও রক্ত দেওয়ার ব্যবস্থা আছে","দিন ও রাতের যানবাহন: চালক বা অ্যাম্বুলেন্সের নম্বর, সাথে আরেকটা বিকল্প","প্রসবের জন্য জমানো টাকা আর আলাদা জরুরি তহবিল, এবং যেকোনো সময় কে টাকা তুলতে পারবেন","মায়ের রক্তের গ্রুপ লেখা, আর একই গ্রুপের অন্তত দুজন রাজি রক্তদাতা ও তাঁদের ফোন নম্বর","হাসপাতালে মায়ের পাশে কে থাকবেন","অন্য সন্তান, বয়স্ক সদস্য আর সংসার কে দেখবেন","স্বামী দূরে থাকলে জরুরি সিদ্ধান্ত কে নেবেন — আগেই ঠিক করা","৩৬ সপ্তাহের মধ্যে হাসপাতালের ব্যাগ গোছানো","বাড়ির সবাই বিপদচিহ্ন ও প্রসববেদনার লক্ষণ জানেন","গর্ভকালীন কার্ড ও রিপোর্ট এক ফোল্ডারে রাখা","আপনার ইচ্ছা: প্রসবের সময় একজন সঙ্গী, জন্মের পর মায়ের বুকে শিশু আর প্রথম ঘণ্টায় বুকের দুধ","প্রসবের পর: বিশ্রাম, ঘরের কাজে সাহায্য, প্রসব-পরবর্তী চেকআপ ও পরিবার পরিকল্পনা"]}}'::jsonb, 2, -189, 0, '{}'::text[], 'any', ARRAY['birth plan', 'transport', 'blood donor', 'emergency fund', 'checklist']::text[], false, 'in_review'::lp_review_status, 2027),
  ('pp-home-ready-checklist', 'checklist', 'general', 'family', 'routine', 'consensus', '🏠', '{"en":"Getting the home ready for the baby","bn":"শিশুর জন্য ঘর প্রস্তুত করা"}'::jsonb, '{"en":"A newborn needs a clean, warm, smoke-free home and a rested mother far more than anything bought from a shop.","bn":"দোকানের কেনা জিনিসের চেয়ে নবজাতকের অনেক বেশি দরকার পরিষ্কার, উষ্ণ, ধোঁয়ামুক্ত একটা ঘর আর বিশ্রাম পাওয়া একজন মা।"}'::jsonb, '{"en":"Get ready in the last weeks, before you go for the birth. If the mother will stay at her parents'' home, prepare that home together with the family there.","bn":"শেষের কয়েক সপ্তাহে, প্রসবের জন্য যাওয়ার আগেই গুছিয়ে নিন। মা বাবার বাড়িতে থাকলে সেখানকার পরিবারের সাথে মিলে সেই ঘরটাও প্রস্তুত করুন।"}'::jsonb, '{"items":{"en":["Clean the room where mother and baby will stay, and let in sunlight and fresh air","Keep the home smoke-free: no smoking indoors, and keep cooking smoke away from the baby''s room","A firm, flat place for the baby to sleep close to the mother, with a mosquito net","Soap and water at a handwashing place for everyone who will hold the baby","Safe drinking water for the mother: boiled, filtered, or from an arsenic-safe source","Soft cotton clothes, caps, socks and cloths, washed and dried in the sun","A warm wrap or blanket for the baby, even in summer","A thermometer, plus the antenatal card and important phone numbers in one place","Food stocked for the mother''s first weeks: rice, dal, eggs, fish, vegetables and fruit","Help arranged for cooking, washing and other children in the first weeks","Tripping hazards removed: loose wires, slippery floors, clutter on stairs","Medicines, iron tablets, kerosene and chemicals locked away from children","The nearest facility for postnatal and newborn check-ups noted down"],"bn":["মা ও শিশু যে ঘরে থাকবেন তা পরিষ্কার করুন, রোদ আর আলো-বাতাস ঢুকতে দিন","ঘর ধোঁয়ামুক্ত রাখুন: ঘরের ভেতর ধূমপান নয়, রান্নার ধোঁয়াও শিশুর ঘর থেকে দূরে রাখুন","মায়ের কাছেই শিশুর ঘুমানোর জন্য শক্ত, সমান একটা জায়গা, সাথে মশারি","শিশুকে যাঁরা কোলে নেবেন, তাঁদের হাত ধোয়ার জন্য সাবান-পানির ব্যবস্থা","মায়ের জন্য নিরাপদ খাবার পানি: ফোটানো, ফিল্টার করা বা আর্সেনিকমুক্ত উৎসের","নরম সুতির জামা, টুপি, মোজা ও কাপড় — ধুয়ে রোদে শুকানো","গরমকালেও শিশুর জন্য একটা উষ্ণ চাদর বা কম্বল","একটা থার্মোমিটার, আর গর্ভকালীন কার্ড ও জরুরি ফোন নম্বর এক জায়গায়","মায়ের প্রথম কয়েক সপ্তাহের খাবার মজুত: চাল, ডাল, ডিম, মাছ, সবজি ও ফল","প্রথম কয়েক সপ্তাহ রান্না, কাপড় ধোয়া আর অন্য সন্তানদের দেখাশোনায় সাহায্যের ব্যবস্থা","হোঁচট খাওয়ার ঝুঁকি দূর করা: ঝুলে থাকা তার, পিচ্ছিল মেঝে, সিঁড়িতে জিনিসপত্র","ওষুধ, আয়রন ট্যাবলেট, কেরোসিন ও রাসায়নিক শিশুদের নাগালের বাইরে তালাবদ্ধ","প্রসব-পরবর্তী ও নবজাতকের চেকআপের জন্য সবচেয়ে কাছের স্বাস্থ্যকেন্দ্র লিখে রাখা"]},"avoid":{"en":["Pillows, heavy quilts or soft toys in the baby''s sleep space","Mosquito coils or any smoke near the baby","Spending savings on gadgets the baby does not need"],"bn":["শিশুর ঘুমের জায়গায় বালিশ, ভারী লেপ বা নরম খেলনা","শিশুর কাছে মশার কয়েল বা যেকোনো ধোঁয়া","শিশুর দরকার নেই এমন যন্ত্রপাতিতে জমানো টাকা খরচ করা"]}}'::jsonb, 2, -84, 0, '{}'::text[], 'any', ARRAY['home', 'newborn', 'preparation', 'smoke-free', 'safe sleep', 'checklist']::text[], false, 'in_review'::lp_review_status, 2028),
  ('pp-nausea-vomiting', 'scenario', 'scientific', 'mother', 'important', 'guideline', '🤢', '{"en":"Nausea and vomiting in pregnancy","bn":"গর্ভাবস্থায় বমি বমি ভাব ও বমি"}'::jsonb, '{"en":"Feeling sick is very common in the first months and usually eases by mid-pregnancy. Vomiting so severe that you cannot keep fluids down needs care the same day.","bn":"প্রথম কয়েক মাসে বমি বমি ভাব খুব সাধারণ, সাধারণত মাঝামাঝি সময়ে কমে আসে। কিন্তু এত বমি যে পানিও পেটে থাকছে না — তাহলে সেদিনই চিকিৎসা নিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Nausea and vomiting — often called morning sickness, although it can happen at any time of day — usually start around 6 weeks and ease by 16 to 20 weeks. For a small number of women, vomiting is severe and does not stop. This is called hyperemesis gravidarum, and it needs treatment.","bn":"বমি বমি ভাব ও বমি — যাকে মর্নিং সিকনেস বলে, যদিও দিনের যেকোনো সময় হতে পারে — সাধারণত ৬ সপ্তাহের দিকে শুরু হয়ে ১৬ থেকে ২০ সপ্তাহের মধ্যে কমে আসে। অল্প কিছু মায়ের বমি খুব বেশি হয় আর থামে না। একে হাইপারএমেসিস গ্রাভিডেরাম বলে, এর চিকিৎসা দরকার।"},"why":{"en":"Pregnancy hormones are the main cause. Tiredness, an empty stomach, strong smells and stress can make it worse. It is not a sign that something is wrong with the baby.","bn":"মূল কারণ গর্ভাবস্থার হরমোন। ক্লান্তি, খালি পেট, কড়া গন্ধ আর দুশ্চিন্তায় বাড়তে পারে। এটা শিশুর কোনো সমস্যার লক্ষণ নয়।"},"normal":{"en":"Feeling sick, vomiting now and then, and disliking some foods or smells are normal, as long as you can still keep some food and water down. Many women eat less in the first months; the baby still gets what it needs at this stage.","bn":"বমি ভাব, মাঝে মাঝে বমি, কিছু খাবার বা গন্ধ সহ্য না হওয়া — এগুলো স্বাভাবিক, যতক্ষণ কিছু খাবার আর পানি পেটে থাকছে। প্রথম কয়েক মাসে অনেকেই কম খান; এই সময়ে শিশু তার দরকারি পুষ্টি পেয়ে যায়।"},"do_now":{"en":["Eat something plain before getting out of bed — dry toast, biscuits, muri or a little rice","Eat small amounts every 2–3 hours instead of three big meals","Sip water, lemon water, oral saline or coconut water slowly through the day","Try ginger, in tea or a little raw ginger with food","Rest, and get some fresh air"],"bn":["বিছানা থেকে ওঠার আগেই শুকনো কিছু খান — টোস্ট, বিস্কুট, মুড়ি বা একটু ভাত","তিনবেলা ভরপেট না খেয়ে ২–৩ ঘণ্টা পরপর অল্প অল্প খান","সারাদিন অল্প অল্প করে পানি, লেবুপানি, খাবার স্যালাইন বা ডাবের পানি পান করুন","আদা খেয়ে দেখুন — চায়ে, বা খাবারের সাথে একটু কাঁচা আদা","বিশ্রাম নিন, খোলা বাতাসে একটু থাকুন"]},"steps":{"en":["Notice your triggers — cooking smells, oily food, brushing teeth — and avoid them where you can","Ask family to cook strong-smelling food for a while, or cook with the window open","Choose cold or room-temperature food if hot food smells too strong","If iron tablets make you feel sick, take them at night and tell your health worker","Keep track of how much you drink and how often you pass urine","If vomiting is bad, ask a doctor — there are medicines that are safe in pregnancy"],"bn":["কীসে বাড়ে খেয়াল করুন — রান্নার গন্ধ, তেলে ভাজা খাবার, দাঁত ব্রাশ — যতটা সম্ভব এড়িয়ে চলুন","কিছুদিন কড়া গন্ধের রান্না পরিবারের অন্যদের করতে বলুন, বা জানালা খুলে রান্না করুন","গরম খাবারের গন্ধ সহ্য না হলে ঠান্ডা বা স্বাভাবিক তাপমাত্রার খাবার খান","আয়রন ট্যাবলেটে বমি ভাব হলে রাতে খান, আর স্বাস্থ্যকর্মীকে জানান","কতটা পানি খাচ্ছেন আর কতবার প্রস্রাব হচ্ছে, খেয়াল রাখুন","বমি বেশি হলে ডাক্তার দেখান — গর্ভাবস্থায় নিরাপদ ওষুধ আছে"]},"avoid":{"en":["Taking anti-vomiting medicines from a pharmacy on your own","Stopping drinking because you are afraid of vomiting","Spicy, oily and fried food when the nausea is bad","Lying down straight after eating"],"bn":["নিজে নিজে ফার্মেসি থেকে বমির ওষুধ কিনে খাওয়া","বমির ভয়ে পানি খাওয়া বন্ধ করা","বমি ভাব বেশি থাকলে ঝাল, তেলে ভাজা ও চর্বিযুক্ত খাবার","খেয়েই শুয়ে পড়া"]},"example":{"en":"Rina, 9 weeks pregnant, vomited every morning. Her husband started keeping a jar of muri and biscuits by the bed, and her mother-in-law cooked the fish while Rina sat outside. Small snacks every few hours helped. One day she could not keep even water down, so they went to the Upazila Health Complex. She was given fluids and medicine and felt better by evening.","bn":"৯ সপ্তাহের অন্তঃসত্ত্বা রিনা প্রতিদিন সকালে বমি করতেন। স্বামী বিছানার পাশে মুড়ি আর বিস্কুটের বয়াম রাখতে শুরু করলেন, আর শাশুড়ি মাছ রান্নার সময় রিনাকে বাইরে বসতে বললেন। কয়েক ঘণ্টা পরপর অল্প খাবারে কাজ হলো। একদিন পানিও পেটে থাকছিল না, তাই তাঁরা উপজেলা স্বাস্থ্য কমপ্লেক্সে গেলেন। স্যালাইন আর ওষুধ পেয়ে সন্ধ্যার মধ্যেই রিনা ভালো বোধ করলেন।"},"seek_help":{"en":["You cannot keep food or fluids down for 24 hours","Very dark urine, or no urine for 8 hours or more","Feeling dizzy or faint when you stand up","Losing weight","Vomiting continues after 20 weeks"],"bn":["২৪ ঘণ্টা ধরে কোনো খাবার বা পানি পেটে থাকছে না","প্রস্রাব খুব গাঢ়, বা ৮ ঘণ্টা বা তার বেশি সময় প্রস্রাব হয়নি","দাঁড়ালে মাথা ঘোরে বা অজ্ঞান ভাব হয়","ওজন কমে যাচ্ছে","২০ সপ্তাহের পরও বমি চলছে"]},"warning_signs":{"en":["Vomiting blood","Severe belly pain","Fever","Confusion or extreme weakness","Vomiting that starts later in pregnancy with a severe headache or blurred vision"],"bn":["বমির সাথে রক্ত","পেটে তীব্র ব্যথা","জ্বর","এলোমেলো কথা বা খুব বেশি দুর্বলতা","গর্ভাবস্থার পরের দিকে নতুন করে বমি, সাথে তীব্র মাথাব্যথা বা ঝাপসা দেখা"]}}'::jsonb, 3, -280, -84, '{}'::text[], 'any', ARRAY['nausea', 'vomiting', 'morning sickness', 'hyperemesis', 'first trimester']::text[], false, 'in_review'::lp_review_status, 2029),
  ('pp-heartburn', 'scenario', 'scientific', 'mother', 'routine', 'guideline', '🔥', '{"en":"Heartburn and acidity","bn":"বুক জ্বালা ও অম্বল"}'::jsonb, '{"en":"A burning feeling in the chest is common, especially in later pregnancy. Small meals and a few simple habits usually help.","bn":"বুকে জ্বালাপোড়া খুব সাধারণ, বিশেষ করে গর্ভাবস্থার শেষের দিকে। অল্প অল্প খাওয়া আর কয়েকটি সহজ অভ্যাসে সাধারণত আরাম মেলে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Heartburn is a burning feeling behind the breastbone or in the throat, sometimes with a sour taste in the mouth. It is common from the middle of pregnancy and is often worse at night.","bn":"বুক জ্বালা হলো বুকের হাড়ের পেছনে বা গলায় জ্বালাপোড়া, কখনো মুখে টক স্বাদ আসে। গর্ভাবস্থার মাঝামাঝি থেকে এটা সাধারণ, আর রাতে প্রায়ই বাড়ে।"},"why":{"en":"Pregnancy hormones relax the valve at the top of the stomach, so acid moves up more easily. In the later months, the growing womb also presses on the stomach.","bn":"গর্ভাবস্থার হরমোন পাকস্থলীর মুখের ভাল্‌ভটাকে ঢিলে করে দেয়, তাই অ্যাসিড সহজে ওপরে উঠে আসে। শেষের মাসগুলোতে বড় হতে থাকা জরায়ুও পাকস্থলীতে চাপ দেয়।"},"normal":{"en":"Burning after meals or when lying down, burping, and feeling full quickly are common and do not harm the baby.","bn":"খাওয়ার পর বা শুলে জ্বালা, ঢেকুর ওঠা আর অল্পতেই পেট ভরে যাওয়া — এগুলো সাধারণ, শিশুর ক্ষতি করে না।"},"do_now":{"en":["Sit upright or stand; do not lie flat","Sip a glass of water or cold milk","If your stomach is empty, eat a small amount of plain food"],"bn":["সোজা হয়ে বসুন বা দাঁড়ান; চিত হয়ে শোবেন না","অল্প অল্প করে এক গ্লাস পানি বা ঠান্ডা দুধ খান","পেট খালি থাকলে অল্প একটু সাধারণ খাবার খান"]},"steps":{"en":["Eat 5–6 small meals instead of 2–3 large ones","Finish dinner at least 2–3 hours before bed","Raise the head of the bed, or use an extra pillow under your shoulders","Cut down on oily, fried and very spicy food, and on tea, coffee and soft drinks","Notice which foods set it off for you","Wear clothes that are loose around the waist","If it keeps bothering you, ask your doctor about an antacid that is safe in pregnancy, and take it at a different time from your iron tablet"],"bn":["২–৩ বার ভরপেট না খেয়ে ৫–৬ বার অল্প করে খান","রাতের খাবার শোয়ার অন্তত ২–৩ ঘণ্টা আগে শেষ করুন","খাটের মাথার দিক একটু উঁচু করুন, বা কাঁধের নিচে বাড়তি বালিশ দিন","তেলে ভাজা, চর্বিযুক্ত ও খুব ঝাল খাবার, আর চা, কফি ও কোমল পানীয় কমান","কোন খাবারে আপনার জ্বালা বাড়ে, খেয়াল করুন","কোমরে ঢিলেঢালা কাপড় পরুন","সমস্যা চলতে থাকলে গর্ভাবস্থায় নিরাপদ অ্যান্টাসিডের কথা ডাক্তারকে জিজ্ঞেস করুন, আর আয়রন ট্যাবলেট থেকে আলাদা সময়ে খান"]},"avoid":{"en":["Antacids or acid tablets without asking — some are not advised in pregnancy, and antacids stop iron working if taken together","A big meal late at night","Bending forward or lying down right after eating","Smoking or chewing tobacco"],"bn":["জিজ্ঞেস না করে অ্যান্টাসিড বা গ্যাসের ট্যাবলেট খাওয়া — কিছু গর্ভাবস্থায় উপযুক্ত নয়, আর আয়রনের সাথে একসাথে খেলে আয়রন কাজ করে না","রাতে দেরিতে ভরপেট খাওয়া","খেয়েই ঝুঁকে কাজ করা বা শুয়ে পড়া","ধূমপান বা তামাক চিবানো"]},"example":{"en":"Shirin, 30 weeks pregnant, woke up with burning every night. She moved dinner earlier, ate a small plate of rice and dal instead of a big one, and her husband raised the head of the bed with two bricks. Her doctor also prescribed an antacid to take at a different time from her iron tablet. The nights became easier.","bn":"৩০ সপ্তাহের অন্তঃসত্ত্বা শিরিন প্রতি রাতে বুক জ্বালায় জেগে উঠতেন। তিনি রাতের খাবার আগে খাওয়া শুরু করলেন, বড় থালার বদলে অল্প ভাত-ডাল খেলেন, আর স্বামী দুটো ইট দিয়ে খাটের মাথার দিক উঁচু করে দিলেন। ডাক্তারও একটা অ্যান্টাসিড দিলেন, আয়রন ট্যাবলেট থেকে আলাদা সময়ে খাওয়ার জন্য। রাতগুলো সহজ হয়ে এলো।"},"seek_help":{"en":["Heartburn does not improve with these changes","Trouble swallowing, or pain when you swallow","You are losing weight or cannot eat"],"bn":["এসব পরিবর্তনেও বুক জ্বালা কমছে না","গিলতে কষ্ট বা গেলার সময় ব্যথা","ওজন কমছে বা খেতে পারছেন না"]},"warning_signs":{"en":["Pain under the ribs or in the upper belly that does not go away, especially with headache, blurred vision or swelling — this can be pre-eclampsia","Vomiting blood or material that looks like coffee grounds","Chest pain with breathlessness or sweating, or pain spreading to the arm or jaw"],"bn":["পাঁজরের নিচে বা পেটের ওপরের দিকে না সারা ব্যথা, বিশেষ করে মাথাব্যথা, ঝাপসা দেখা বা শরীর ফোলার সাথে — এটা প্রি-এক্লাম্পসিয়া হতে পারে","বমির সাথে রক্ত, বা কফির গুঁড়ার মতো কালচে বমি","বুকে ব্যথার সাথে শ্বাসকষ্ট বা ঘাম, বা ব্যথা হাত বা চোয়ালে ছড়িয়ে পড়া"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['heartburn', 'acidity', 'indigestion', 'reflux']::text[], false, 'in_review'::lp_review_status, 2030),
  ('pp-back-pain', 'scenario', 'scientific', 'mother', 'routine', 'guideline', '🧍‍♀️', '{"en":"Back pain in pregnancy","bn":"গর্ভাবস্থায় কোমর ও পিঠ ব্যথা"}'::jsonb, '{"en":"Backache is very common as the bump grows. Good posture, gentle exercise and rest help — but some back pain is a sign to get checked.","bn":"পেট বড় হওয়ার সাথে কোমর ব্যথা খুব সাধারণ। ঠিকভাবে বসা-দাঁড়ানো, হালকা ব্যায়াম আর বিশ্রামে উপকার হয় — তবে কিছু ব্যথায় দেরি না করে দেখাতে হয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Pain in the lower back, or around the hips and pelvis, affects many pregnant women, most often in the later months.","bn":"কোমরের নিচের দিকে, বা নিতম্ব ও শ্রোণির চারপাশে ব্যথা অনেক গর্ভবতী মায়েরই হয়, বেশিরভাগ শেষের মাসগুলোতে।"},"why":{"en":"Hormones loosen the joints and ligaments to prepare the body for birth, and the growing belly changes your posture and puts more strain on your back.","bn":"প্রসবের প্রস্তুতিতে হরমোন জোড়া ও লিগামেন্টগুলো ঢিলে করে দেয়, আর বড় হতে থাকা পেট শরীরের ভঙ্গি বদলে কোমরে বাড়তি চাপ দেয়।"},"normal":{"en":"A dull ache in the lower back after standing, walking or housework, which eases with rest, is common.","bn":"দাঁড়িয়ে থাকা, হাঁটা বা ঘরের কাজের পর কোমরে চিনচিনে ব্যথা, যা বিশ্রামে কমে — এটা সাধারণ।"},"do_now":{"en":["Rest lying on your side with a pillow between your knees","Put a warm (not hot) cloth on your lower back","Ask someone to gently rub your lower back","Sit on a chair with back support instead of on the floor"],"bn":["হাঁটুর মাঝে বালিশ দিয়ে কাত হয়ে শুয়ে বিশ্রাম নিন","কোমরে কুসুম গরম (বেশি গরম নয়) কাপড়ের সেঁক দিন","কাউকে আলতো করে কোমর মালিশ করে দিতে বলুন","মেঝেতে না বসে পিঠে হেলান দেওয়া যায় এমন চেয়ারে বসুন"]},"steps":{"en":["Stay active: regular walking and gentle stretches help prevent back pain","Stand tall, without locking your knees or arching your back","Bend your knees and keep your back straight to pick things up — better still, let others lift","Wear flat, comfortable shoes or sandals","When sitting on the floor for meals or work, use a low stool or lean against a wall","To get out of bed, roll onto your side first, then push up with your arms","Sleep on your side with pillows between your knees and under the bump"],"bn":["সক্রিয় থাকুন: নিয়মিত হাঁটা আর হালকা স্ট্রেচিং কোমর ব্যথা প্রতিরোধে সাহায্য করে","সোজা হয়ে দাঁড়ান, হাঁটু টানটান করে আটকে রাখবেন না, কোমর বাঁকাবেন না","কিছু তুলতে হলে হাঁটু ভাঁজ করে পিঠ সোজা রাখুন — আরও ভালো, অন্যকে তুলতে দিন","সমান, আরামদায়ক জুতা বা স্যান্ডেল পরুন","খাওয়া বা কাজের জন্য মেঝেতে বসলে নিচু পিঁড়ি ব্যবহার করুন বা দেয়ালে হেলান দিন","বিছানা থেকে উঠতে আগে কাত হোন, তারপর হাতে ভর দিয়ে উঠুন","হাঁটুর মাঝে আর পেটের নিচে বালিশ দিয়ে কাত হয়ে ঘুমান"]},"avoid":{"en":["Lifting heavy loads such as water pots, buckets, or children for long","Painkillers like ibuprofen or diclofenac, or pain-relief gels, without a doctor","Standing or sitting in one position for a long time","Firm massage on the belly"],"bn":["পানির কলসি, বালতি বা অনেকক্ষণ শিশুকে কোলে নেওয়ার মতো ভারী বোঝা তোলা","ডাক্তার ছাড়া আইবুপ্রোফেন বা ডাইক্লোফেনাকের মতো ব্যথার ওষুধ বা ব্যথানাশক জেল","অনেকক্ষণ একভাবে দাঁড়িয়ে বা বসে থাকা","পেটে জোরে মালিশ"]},"example":{"en":"Moushumi works in a garment factory and had backache by every evening. Her supervisor let her sit for some tasks, she walked for 15 minutes after dinner, and at night her husband put a pillow between her knees and rubbed her back. The ache did not disappear completely, but it became manageable.","bn":"মৌসুমী পোশাক কারখানায় কাজ করেন, প্রতি সন্ধ্যায় কোমর ব্যথা হতো। সুপারভাইজার কিছু কাজ বসে করার সুযোগ দিলেন, তিনি রাতের খাবারের পর ১৫ মিনিট হাঁটতেন, আর রাতে স্বামী হাঁটুর মাঝে বালিশ দিয়ে কোমর মালিশ করে দিতেন। ব্যথা পুরো চলে যায়নি, কিন্তু সহনীয় হয়ে এলো।"},"seek_help":{"en":["The pain is severe or makes walking very hard","The pain does not improve with rest after a few days","Pain in the pelvis or hip joints makes it hard to turn in bed or climb stairs"],"bn":["ব্যথা তীব্র, বা হাঁটতে খুব কষ্ট হয়","কয়েক দিন বিশ্রামেও ব্যথা কমছে না","শ্রোণি বা নিতম্বের জোড়ায় এমন ব্যথা যে বিছানায় পাশ ফিরতে বা সিঁড়ি ভাঙতে কষ্ট হয়"]},"warning_signs":{"en":["Back pain that comes and goes regularly with tightening of the belly, especially before 37 weeks — this may be labour","Pain in the side or back with fever, shivering or burning urine — possible kidney infection","Back pain with bleeding or fluid leaking from the vagina","Numbness or weakness in the legs, or losing control of urine or stool","Sudden, severe pain"],"bn":["নিয়মিত বিরতিতে আসা-যাওয়া করা কোমর ব্যথা, সাথে পেট শক্ত হয়ে আসা, বিশেষ করে ৩৭ সপ্তাহের আগে — এটা প্রসববেদনা হতে পারে","পাশে বা পিঠে ব্যথার সাথে জ্বর, কাঁপুনি বা প্রস্রাবে জ্বালা — কিডনিতে সংক্রমণ হতে পারে","কোমর ব্যথার সাথে যোনিপথে রক্তপাত বা পানি বের হওয়া","পায়ে অবশ ভাব বা দুর্বলতা, বা প্রস্রাব-পায়খানা আটকে রাখতে না পারা","হঠাৎ তীব্র ব্যথা"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['back pain', 'pelvic pain', 'posture', 'backache']::text[], false, 'in_review'::lp_review_status, 2031),
  ('pp-leg-cramps-swollen-feet', 'scenario', 'scientific', 'mother', 'routine', 'guideline', '🦶', '{"en":"Leg cramps and swollen feet","bn":"পায়ে টান ধরা ও পা ফোলা"}'::jsonb, '{"en":"Night cramps and mild swelling of the feet are common in later pregnancy. Sudden swelling of the face and hands, or one painful swollen leg, needs care quickly.","bn":"গর্ভাবস্থার শেষের দিকে রাতে পায়ে টান ধরা আর পা হালকা ফোলা সাধারণ। কিন্তু হঠাৎ মুখ-হাত ফোলা, বা এক পা ফুলে ব্যথা হলে দ্রুত চিকিৎসা নিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Cramps are sudden, painful tightening of the calf or foot muscles, often at night. Swelling (oedema) of the feet and ankles usually builds up during the day and is better in the morning.","bn":"পায়ে টান ধরা মানে পায়ের ডিম বা পাতার পেশি হঠাৎ ব্যথা দিয়ে শক্ত হয়ে যাওয়া, প্রায়ই রাতে। পায়ের পাতা ও গোড়ালি ফোলা (ইডিমা) সাধারণত দিনভর বাড়ে আর সকালে কম থাকে।"},"why":{"en":"In pregnancy the body holds more fluid, and the growing womb slows the flow of blood back from the legs. The exact cause of cramps is not fully known; tiredness and long hours of standing may play a part.","bn":"গর্ভাবস্থায় শরীরে পানি বেশি জমে, আর বড় হতে থাকা জরায়ু পা থেকে রক্ত ফেরার গতি কমিয়ে দেয়। টান ধরার সঠিক কারণ পুরোপুরি জানা নেই; ক্লান্তি আর অনেকক্ষণ দাঁড়িয়ে থাকা ভূমিকা রাখতে পারে।"},"normal":{"en":"Swelling in both feet and ankles that is worse in the evening or in hot weather and better after resting with your feet up is common. So are occasional night cramps that pass in a few minutes.","bn":"দুই পায়ের পাতা ও গোড়ালি ফোলা, যা সন্ধ্যায় বা গরমে বাড়ে আর পা উঁচু করে বিশ্রামে কমে — এটা সাধারণ। মাঝে মাঝে রাতে কয়েক মিনিটের টান ধরাও সাধারণ।"},"do_now":{"en":["For a cramp: straighten your leg and gently pull your toes towards you, or stand and press your heel into the floor","Rub the muscle firmly, then walk around a little","For swelling: lie on your side, or sit with your feet raised on a pillow or stool"],"bn":["টান ধরলে: পা সোজা করে পায়ের আঙুলগুলো আলতো করে নিজের দিকে টানুন, বা দাঁড়িয়ে গোড়ালি মেঝেতে চেপে ধরুন","পেশিটা ভালো করে ডলে দিন, তারপর একটু হাঁটুন","ফোলার জন্য: কাত হয়ে শুয়ে থাকুন, বা বালিশ বা পিঁড়িতে পা তুলে বসুন"]},"steps":{"en":["Stretch your calves gently before bed","Walk every day, and move your feet often when sitting — circle them and point them up and down","Avoid standing in one place for long; take breaks to sit","Do not sit cross-legged for long periods","Drink enough water through the day","Wear comfortable shoes, and take off tight bangles, rings or anklets if your hands or feet swell","Ask your health worker whether calcium or magnesium could help, and take them only as prescribed"],"bn":["শোয়ার আগে আলতো করে পায়ের ডিমের পেশি টানটান করুন","প্রতিদিন হাঁটুন, বসে থাকলেও মাঝে মাঝে পায়ের পাতা ঘোরান আর ওপর-নিচ করুন","অনেকক্ষণ এক জায়গায় দাঁড়িয়ে থাকবেন না, মাঝে মাঝে বসুন","অনেকক্ষণ আসন করে পা ভাঁজ করে বসবেন না","সারাদিন যথেষ্ট পানি পান করুন","আরামদায়ক জুতা পরুন; হাত-পা ফুললে টাইট চুড়ি, আংটি বা নূপুর খুলে রাখুন","ক্যালসিয়াম বা ম্যাগনেসিয়ামে উপকার হবে কিনা স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন, আর শুধু যেভাবে দেওয়া হয় সেভাবে খান"]},"avoid":{"en":["Drinking less water to reduce swelling — it does not help","Water pills or other medicines without a doctor","Tight socks or bands around the top of the calf","Massaging a calf that is red, hot and painful"],"bn":["ফোলা কমাতে পানি কম খাওয়া — এতে উপকার হয় না","ডাক্তার ছাড়া পানি কমানোর বড়ি বা অন্য ওষুধ","পায়ের ডিমের ওপরে টাইট মোজা বা বাঁধন","লাল, গরম আর ব্যথাযুক্ত পায়ের ডিমে মালিশ"]},"example":{"en":"In her eighth month, Nazma woke twice in one night with a cramp in her calf. Her husband learned to help her stretch her foot and rub the muscle. She started walking after dinner and resting with her feet up in the afternoon. At her check-up her blood pressure was normal, and the doctor said the swelling was the usual kind.","bn":"অষ্টম মাসে নাজমা এক রাতে দুবার পায়ে টান ধরে জেগে উঠলেন। স্বামী শিখে নিলেন কীভাবে পা টানটান করে পেশি ডলে দিতে হয়। নাজমা রাতের খাবারের পর হাঁটা আর দুপুরে পা তুলে বিশ্রাম নেওয়া শুরু করলেন। চেকআপে রক্তচাপ স্বাভাবিক পাওয়া গেল, ডাক্তার বললেন ফোলাটা সাধারণ ধরনের।"},"seek_help":{"en":["Swelling that does not go down after a night''s rest","Cramps that are frequent and wake you every night","Swelling together with quick weight gain over a few days"],"bn":["রাতভর বিশ্রামের পরও ফোলা কমছে না","প্রতি রাতে বারবার টান ধরে ঘুম ভেঙে যাচ্ছে","কয়েক দিনে দ্রুত ওজন বাড়ার সাথে ফোলা"]},"warning_signs":{"en":["Sudden swelling of the face, hands or around the eyes","Swelling with a severe headache, blurred vision or pain under the ribs — possible pre-eclampsia","One leg swollen, red, warm or painful, especially in the calf — possible blood clot","Breathlessness or chest pain — go to hospital at once"],"bn":["হঠাৎ মুখ, হাত বা চোখের চারপাশ ফুলে যাওয়া","ফোলার সাথে তীব্র মাথাব্যথা, ঝাপসা দেখা বা পাঁজরের নিচে ব্যথা — প্রি-এক্লাম্পসিয়া হতে পারে","এক পা ফোলা, লাল, গরম বা ব্যথা, বিশেষ করে পায়ের ডিমে — রক্ত জমাট বাঁধতে পারে","শ্বাসকষ্ট বা বুকে ব্যথা — সাথে সাথে হাসপাতালে যান"]}}'::jsonb, 3, -189, 0, '{}'::text[], 'any', ARRAY['leg cramps', 'swollen feet', 'oedema', 'swelling', 'blood clot']::text[], false, 'in_review'::lp_review_status, 2032),
  ('pp-constipation', 'scenario', 'scientific', 'mother', 'routine', 'guideline', '🥬', '{"en":"Constipation in pregnancy","bn":"গর্ভাবস্থায় কোষ্ঠকাঠিন্য"}'::jsonb, '{"en":"Hard stools are common in pregnancy, especially with iron tablets. More water, more fibre and daily movement usually help.","bn":"গর্ভাবস্থায়, বিশেষ করে আয়রন ট্যাবলেট খেলে, পায়খানা শক্ত হওয়া সাধারণ। বেশি পানি, আঁশযুক্ত খাবার আর প্রতিদিন হাঁটাচলায় সাধারণত উপকার হয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Constipation means opening your bowels less often than usual, or passing stools that are hard and painful. It can also lead to piles (haemorrhoids).","bn":"কোষ্ঠকাঠিন্য মানে স্বাভাবিকের চেয়ে কম পায়খানা হওয়া, বা পায়খানা শক্ত ও কষ্টদায়ক হওয়া। এ থেকে পাইলসও (অর্শ) হতে পারে।"},"why":{"en":"Pregnancy hormones slow down the bowel, the growing womb presses on it, and iron tablets can make stools harder.","bn":"গর্ভাবস্থার হরমোন অন্ত্রের গতি কমিয়ে দেয়, বড় হতে থাকা জরায়ু অন্ত্রে চাপ দেয়, আর আয়রন ট্যাবলেট পায়খানা শক্ত করতে পারে।"},"normal":{"en":"Going less often than before, and some straining, are common in pregnancy. Black stools while taking iron are normal.","bn":"গর্ভাবস্থায় আগের চেয়ে কম পায়খানা হওয়া আর একটু চাপ দিতে হওয়া সাধারণ। আয়রন খেলে কালো পায়খানা স্বাভাবিক।"},"do_now":{"en":["Drink a glass of warm water first thing in the morning","Add fibre to today''s meals: shak, vegetables, fruit and dal","Take a short walk","Go to the toilet as soon as you feel the urge; do not hold it in"],"bn":["সকালে উঠেই এক গ্লাস কুসুম গরম পানি পান করুন","আজকের খাবারে আঁশ যোগ করুন: শাক, সবজি, ফল ও ডাল","একটু হেঁটে আসুন","বেগ এলে সাথে সাথে টয়লেটে যান, চেপে রাখবেন না"]},"steps":{"en":["Drink plenty of safe water through the day","Eat fibre at every meal: dark green shak, beans, dal, atta roti, red rice or chira, and fruits such as guava, ripe papaya, banana and bel (wood apple)","Isabgul (ispaghula husk) soaked in water can help — ask your health worker","Walk or move every day","On a high toilet, put a low stool under your feet so you sit in a squatting position","Take iron at a regular time; if it makes constipation worse, tell your health worker instead of stopping it","If these steps do not help, ask your doctor for a laxative that is safe in pregnancy"],"bn":["সারাদিন প্রচুর নিরাপদ পানি পান করুন","প্রতিবেলার খাবারে আঁশ রাখুন: গাঢ় সবুজ শাক, শিমের বিচি, ডাল, আটার রুটি, লাল চাল বা চিড়া, আর পেয়ারা, পাকা পেঁপে, কলা ও বেলের মতো ফল","পানিতে ভেজানো ইসবগুলের ভুসি উপকার করতে পারে — স্বাস্থ্যকর্মীকে জিজ্ঞেস করুন","প্রতিদিন হাঁটুন বা নড়াচড়া করুন","উঁচু কমোডে বসলে পায়ের নিচে একটা নিচু পিঁড়ি দিন, যাতে বসার ভঙ্গি উবু হয়ে বসার মতো হয়","আয়রন নিয়ম করে একই সময়ে খান; কোষ্ঠকাঠিন্য বাড়লে বন্ধ না করে স্বাস্থ্যকর্মীকে জানান","এতেও কাজ না হলে গর্ভাবস্থায় নিরাপদ জোলাপের কথা ডাক্তারকে জিজ্ঞেস করুন"]},"avoid":{"en":["Stopping iron tablets on your own","Strong laxatives, enemas or herbal purges without a doctor","Straining hard for a long time","Eating or drinking less"],"bn":["নিজে নিজে আয়রন ট্যাবলেট বন্ধ করা","ডাক্তার ছাড়া কড়া জোলাপ, ডুশ বা ভেষজ পেট পরিষ্কারের ওষুধ","অনেকক্ষণ জোরে চাপ দেওয়া","খাওয়া বা পানি কমিয়ে দেওয়া"]},"example":{"en":"Taslima, taking iron tablets, had not opened her bowels properly for three days. Her mother made sure there was shak and dal at every meal, Taslima kept a water bottle beside her all day, and she took isabgul in the evening as her health worker advised. Within a few days, things moved more easily.","bn":"আয়রন ট্যাবলেট খাওয়া তাসলিমার তিন দিন ঠিকমতো পায়খানা হচ্ছিল না। মা খেয়াল রাখলেন প্রতিবেলা যেন শাক আর ডাল থাকে, তাসলিমা সারাদিন পাশে পানির বোতল রাখলেন, আর স্বাস্থ্যকর্মীর পরামর্শে সন্ধ্যায় ইসবগুল খেলেন। কয়েক দিনের মধ্যেই সহজ হয়ে এলো।"},"seek_help":{"en":["No bowel movement for more than 3–4 days despite these steps","Painful piles, or piles that bleed","Constipation that alternates with diarrhoea"],"bn":["এসব করার পরও ৩–৪ দিনের বেশি পায়খানা হয়নি","পাইলসে ব্যথা, বা পাইলস থেকে রক্ত পড়া","কখনো কোষ্ঠকাঠিন্য, কখনো পাতলা পায়খানা"]},"warning_signs":{"en":["Severe belly pain or cramping","Blood in or on the stool — more than a small streak","A swollen belly with vomiting and no passing of wind","Bleeding from the vagina, or regular tightening of the belly"],"bn":["পেটে তীব্র ব্যথা বা মোচড়","পায়খানার সাথে বা ওপরে রক্ত — সামান্য দাগের চেয়ে বেশি","পেট ফুলে যাওয়া, সাথে বমি আর বায়ু বের না হওয়া","যোনিপথে রক্তপাত, বা পেট নিয়মিত শক্ত হয়ে আসা"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['constipation', 'piles', 'fibre', 'iron tablets', 'isabgul']::text[], false, 'in_review'::lp_review_status, 2033),
  ('pp-bleeding-spotting', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🩸', '{"en":"Spotting or bleeding in pregnancy","bn":"গর্ভাবস্থায় রক্তের দাগ বা রক্তপাত"}'::jsonb, '{"en":"Any bleeding from the vagina in pregnancy needs a check by a health worker — the same day for spotting, immediately for heavier bleeding or pain.","bn":"গর্ভাবস্থায় যোনিপথে যেকোনো রক্তপাত স্বাস্থ্যকর্মীকে দেখাতে হবে — সামান্য দাগ হলে সেদিনই, বেশি রক্ত বা ব্যথা হলে সাথে সাথে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Bleeding can be a few brown or pink spots on your underwear, red bleeding like a period, or heavier. It can happen at any stage of pregnancy.","bn":"রক্তপাত হতে পারে অন্তর্বাসে কয়েক ফোঁটা বাদামি বা গোলাপি দাগ, মাসিকের মতো লাল রক্ত, বা তার চেয়েও বেশি। গর্ভাবস্থার যেকোনো সময় হতে পারে।"},"why":{"en":"In early pregnancy, light spotting sometimes happens without any problem — for example, when the pregnancy settles into the womb or after an internal examination. But bleeding can also be a sign of miscarriage, a pregnancy outside the womb (ectopic pregnancy), or, later on, a problem with the placenta. Only an examination, and often an ultrasound, can tell the difference.","bn":"গর্ভাবস্থার শুরুতে কখনো কোনো সমস্যা ছাড়াই হালকা দাগ দেখা যায় — যেমন ভ্রূণ জরায়ুতে বসার সময়, বা ভেতরের পরীক্ষার পর। কিন্তু রক্তপাত গর্ভপাত, জরায়ুর বাইরে গর্ভধারণ (একটোপিক প্রেগন্যান্সি), বা পরের দিকে গর্ভফুলের সমস্যার লক্ষণও হতে পারে। শুধু পরীক্ষা করে, আর প্রায়ই আলট্রাসাউন্ড করে, পার্থক্য বোঝা যায়।"},"normal":{"en":"A few spots of blood in early pregnancy can happen in a healthy pregnancy — but there is no way to be sure at home. Every bleed should be checked.","bn":"সুস্থ গর্ভাবস্থাতেও শুরুর দিকে কয়েক ফোঁটা রক্ত দেখা যেতে পারে — কিন্তু ঘরে বসে নিশ্চিত হওয়ার উপায় নেই। প্রতিবারের রক্তপাতই দেখাতে হবে।"},"do_now":{"en":["Contact or go to a health facility today, even if it is only spotting","If the bleeding is heavy, or comes with pain, dizziness or fainting, go to hospital now or call 999","Lie down and rest until you can leave, and wear a pad so you can show how much you are losing","Take your antenatal card and blood group report"],"bn":["সামান্য দাগ হলেও আজই স্বাস্থ্যকেন্দ্রে যোগাযোগ করুন বা যান","রক্ত বেশি গেলে, বা সাথে ব্যথা, মাথা ঘোরা বা অজ্ঞান ভাব থাকলে এখনই হাসপাতালে যান বা ৯৯৯-এ ফোন করুন","রওনা না দেওয়া পর্যন্ত শুয়ে বিশ্রাম নিন, আর প্যাড পরে থাকুন যাতে কতটা রক্ত যাচ্ছে দেখানো যায়","গর্ভকালীন কার্ড আর রক্তের গ্রুপের রিপোর্ট সাথে নিন"]},"steps":{"en":["Note when it started, the colour, and how many pads you have used","Tell the health worker about any pain, fever, dizziness, or a recent fall or injury","If you are Rh-negative, ask whether you need anti-D","If the bleeding is heavy, call your blood donors","Follow the advice on rest and further tests, and go back if the bleeding returns"],"bn":["কখন শুরু হলো, রক্তের রং কেমন, আর কয়টা প্যাড লেগেছে — লিখে রাখুন","কোনো ব্যথা, জ্বর, মাথা ঘোরা, বা সম্প্রতি পড়ে যাওয়া বা আঘাতের কথা স্বাস্থ্যকর্মীকে জানান","আপনি আরএইচ নেগেটিভ হলে অ্যান্টি-ডি লাগবে কিনা জিজ্ঞেস করুন","রক্ত বেশি গেলে রক্তদাতাদের খবর দিন","বিশ্রাম ও পরীক্ষার পরামর্শ মেনে চলুন, আবার রক্ত গেলে আবার যান"]},"avoid":{"en":["Waiting to see if it stops on its own","Putting anything into the vagina — no cloth, tampon or herbal remedy","Sex, until a doctor says it is safe","Medicines or injections from a pharmacy or village doctor to stop the bleeding","Lifting heavy things or doing hard work"],"bn":["নিজে থেকে থেমে যায় কিনা দেখার জন্য অপেক্ষা করা","যোনিপথে কিছু ঢোকানো — কাপড়, ট্যাম্পন বা ভেষজ কিছু নয়","ডাক্তার নিরাপদ না বলা পর্যন্ত সহবাস","রক্ত থামাতে ফার্মেসি বা গ্রাম্য ডাক্তারের ওষুধ বা ইনজেকশন","ভারী জিনিস তোলা বা কঠিন কাজ"]},"example":{"en":"At 10 weeks, Farzana noticed brown spots on her underwear. She was scared and wanted to wait, but her husband said, ''Let''s go today, just to be sure.'' The doctor did an ultrasound; the baby''s heartbeat was fine, and she was asked to rest and come back if the bleeding increased. Going early meant they could stop worrying.","bn":"১০ সপ্তাহে ফারজানা অন্তর্বাসে বাদামি দাগ দেখলেন। ভয় পেয়ে অপেক্ষা করতে চাইছিলেন, কিন্তু স্বামী বললেন, ''চলো আজই যাই, নিশ্চিত হয়ে আসি।'' ডাক্তার আলট্রাসাউন্ড করলেন; শিশুর হৃৎস্পন্দন ঠিক ছিল, তাঁকে বিশ্রাম নিতে আর রক্ত বাড়লে আবার আসতে বলা হলো। আগেভাগে যাওয়ায় তাঁদের দুশ্চিন্তা কেটে গেল।"},"seek_help":{"en":["Any spotting — get checked the same day","Bleeding again after you have been checked","Bleeding after sex or after a fall"],"bn":["যেকোনো দাগ — সেদিনই দেখান","দেখানোর পর আবার রক্তপাত","সহবাসের পর বা পড়ে যাওয়ার পর রক্তপাত"]},"warning_signs":{"en":["Heavy bleeding — soaking a pad within an hour, or passing clots","Severe belly pain, or pain on one side of the lower belly","Pain in the tip of the shoulder, dizziness or fainting — possible ectopic pregnancy","Any bleeding in the later months, with or without pain","Fever or a bad-smelling discharge","The baby moving less"],"bn":["অতিরিক্ত রক্তপাত — এক ঘণ্টার মধ্যে প্যাড ভিজে যাওয়া, বা রক্তের চাকা যাওয়া","পেটে তীব্র ব্যথা, বা তলপেটের এক পাশে ব্যথা","কাঁধের ডগায় ব্যথা, মাথা ঘোরা বা অজ্ঞান হয়ে যাওয়া — জরায়ুর বাইরে গর্ভধারণ হতে পারে","শেষের মাসগুলোতে যেকোনো রক্তপাত, ব্যথা থাকুক বা না থাকুক","জ্বর বা দুর্গন্ধযুক্ত স্রাব","শিশুর নড়াচড়া কমে যাওয়া"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['bleeding', 'spotting', 'miscarriage', 'ectopic pregnancy', 'placenta']::text[], false, 'in_review'::lp_review_status, 2034),
  ('pp-baby-moving-less', 'scenario', 'scientific', 'shared', 'important', 'guideline', '👶', '{"en":"Baby moving less than usual","bn":"গর্ভের শিশু স্বাভাবিকের চেয়ে কম নড়ছে"}'::jsonb, '{"en":"If your baby is moving less than usual, or the pattern changes, go to a health facility the same day. Do not wait until tomorrow.","bn":"গর্ভের শিশু স্বাভাবিকের চেয়ে কম নড়লে, বা নড়াচড়ার ধরন বদলে গেলে, সেদিনই স্বাস্থ্যকেন্দ্রে যান। পরের দিনের জন্য অপেক্ষা করবেন না।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Most women start to feel movements between about 16 and 24 weeks. As the pregnancy goes on, you learn your own baby''s pattern — the times of day when they are active and when they sleep. A drop in movements, or a change in that pattern, matters.","bn":"বেশিরভাগ মা মোটামুটি ১৬ থেকে ২৪ সপ্তাহের মধ্যে নড়াচড়া টের পেতে শুরু করেন। সময়ের সাথে নিজের শিশুর ধরন চেনা হয়ে যায় — দিনের কখন সে বেশি নড়ে, কখন ঘুমায়। নড়াচড়া কমে যাওয়া বা সেই ধরন বদলে যাওয়া গুরুত্বপূর্ণ।"},"why":{"en":"A change in movements can be an early sign that the baby is not getting enough oxygen or nourishment through the placenta. Checking quickly gives the health team the chance to act in time.","bn":"নড়াচড়ার পরিবর্তন হতে পারে এমন প্রাথমিক লক্ষণ যে শিশু গর্ভফুলের মাধ্যমে যথেষ্ট অক্সিজেন বা পুষ্টি পাচ্ছে না। দ্রুত পরীক্ষা করালে স্বাস্থ্যকর্মীরা সময়মতো ব্যবস্থা নিতে পারেন।"},"normal":{"en":"Babies have sleep periods, usually shorter than about an hour and a half. Babies do not move less towards the end of pregnancy. The movements may feel different — more pushing and rolling than kicking — but they should continue right up to and during labour.","bn":"শিশুর ঘুমের সময় থাকে, সাধারণত দেড় ঘণ্টার কম। গর্ভাবস্থার শেষ দিকে শিশু কম নড়ে — এটা ঠিক নয়। নড়াচড়ার অনুভূতি বদলাতে পারে — লাথির চেয়ে ঠেলা আর গড়ানো বেশি — কিন্তু প্রসব পর্যন্ত, এমনকি প্রসবের সময়ও নড়াচড়া চলতে থাকার কথা।"},"do_now":{"en":["If you think your baby is moving less, contact your health facility now","You can lie on your left side for a short while and focus on the movements — but if you are unsure, or movements are still fewer, go now","Take your antenatal card, and go with someone","If you feel no movement at all, go to hospital immediately"],"bn":["শিশু কম নড়ছে মনে হলে এখনই স্বাস্থ্যকেন্দ্রে যোগাযোগ করুন","অল্প কিছুক্ষণ বাঁ কাতে শুয়ে নড়াচড়ায় মন দিতে পারেন — তবে নিশ্চিত না হলে, বা নড়াচড়া তখনো কম থাকলে, এখনই যান","গর্ভকালীন কার্ড সাথে নিন, একা না গিয়ে কাউকে সাথে নিন","একেবারেই নড়াচড়া টের না পেলে সাথে সাথে হাসপাতালে যান"]},"steps":{"en":["Get to know your baby''s usual pattern from about 24 weeks; the movement counter in the app can help","At the facility, the health worker will listen to the baby''s heartbeat and may do a monitoring trace (CTG) or an ultrasound","If the checks are normal, you can go home — but go back every time the movements reduce again","Never feel embarrassed about going back; health workers would much rather check"],"bn":["মোটামুটি ২৪ সপ্তাহ থেকে শিশুর স্বাভাবিক ধরন চিনে নিন; অ্যাপের নড়াচড়া গোনার কাউন্টার কাজে দেবে","স্বাস্থ্যকেন্দ্রে শিশুর হৃৎস্পন্দন শোনা হবে, দরকারে মনিটর (সিটিজি) বা আলট্রাসাউন্ড করা হতে পারে","সব ঠিক থাকলে বাড়ি ফিরতে পারেন — কিন্তু যতবার নড়াচড়া কমবে, ততবার আবার যান","বারবার যেতে লজ্জা পাবেন না; স্বাস্থ্যকর্মীরা পরীক্ষা করে নিশ্চিত হতেই বেশি পছন্দ করেন"]},"avoid":{"en":["Waiting until the next day or the next check-up","Relying on cold water, sweets or prodding the belly to make the baby move","Relying on a home heartbeat device or a phone app — hearing a heartbeat does not show the baby is well","Assuming it is normal because it is late in pregnancy"],"bn":["পরের দিন বা পরের চেকআপ পর্যন্ত অপেক্ষা করা","ঠান্ডা পানি, মিষ্টি খেয়ে বা পেটে খোঁচা দিয়ে নড়ানোর ওপর ভরসা করা","ঘরের হৃৎস্পন্দন মাপার যন্ত্র বা ফোনের অ্যাপের ওপর ভরসা করা — হৃৎস্পন্দন শোনা গেলেই শিশু ভালো আছে, তা বলা যায় না","শেষের দিক বলে কম নড়াচড়াকে স্বাভাবিক ধরে নেওয়া"]},"example":{"en":"At 34 weeks, Sabina noticed her baby had been quiet all afternoon. Her mother-in-law said babies go quiet near the end, but Sabina remembered what she had read. Her husband took her to the hospital that evening. The monitor showed the baby was well, and the nurse said, ''You did the right thing. Come again any time.''","bn":"৩৪ সপ্তাহে সাবিনা খেয়াল করলেন, সারা বিকেল শিশু চুপচাপ। শাশুড়ি বললেন, শেষের দিকে শিশু এমন চুপ থাকে; কিন্তু সাবিনার মনে পড়ল যা পড়েছিলেন। সেদিন সন্ধ্যাতেই স্বামী তাঁকে হাসপাতালে নিয়ে গেলেন। মনিটরে দেখা গেল শিশু ভালো আছে, আর নার্স বললেন, ''ঠিক কাজ করেছেন। যখনই দরকার, আবার আসবেন।''"},"seek_help":{"en":["Movements are fewer than usual, or the pattern has changed — the same day","Movements reduce again after a normal check"],"bn":["নড়াচড়া স্বাভাবিকের চেয়ে কম, বা ধরন বদলে গেছে — সেদিনই","পরীক্ষায় সব ঠিক থাকার পর আবার নড়াচড়া কমে গেছে"]},"warning_signs":{"en":["No movements at all","Fewer movements with bleeding, leaking fluid, belly pain or fever","Fewer movements with a severe headache, blurred vision or sudden swelling"],"bn":["একেবারেই নড়াচড়া নেই","নড়াচড়া কম, সাথে রক্তপাত, পানি বের হওয়া, পেটে ব্যথা বা জ্বর","নড়াচড়া কম, সাথে তীব্র মাথাব্যথা, ঝাপসা দেখা বা হঠাৎ শরীর ফোলা"]}}'::jsonb, 3, -112, 0, '{}'::text[], 'any', ARRAY['baby movements', 'kicks', 'reduced movements', 'fetal movement']::text[], false, 'in_review'::lp_review_status, 2035),
  ('pp-cannot-sleep', 'scenario', 'scientific', 'mother', 'routine', 'consensus', '🌙', '{"en":"Cannot sleep in pregnancy","bn":"গর্ভাবস্থায় ঘুম আসছে না"}'::jsonb, '{"en":"Trouble sleeping is common, especially in later pregnancy. Comfortable positions, a calm routine and daytime activity can help.","bn":"গর্ভাবস্থায়, বিশেষ করে শেষের দিকে, ঘুমের সমস্যা খুব সাধারণ। আরামদায়ক ভঙ্গি, শান্ত একটা রুটিন আর দিনে হাঁটাচলা সাহায্য করে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Many women find it hard to fall asleep, wake often in the night or wake very early, especially in the first and last three months of pregnancy.","bn":"অনেক মায়ের ঘুম আসতে দেরি হয়, রাতে বারবার ঘুম ভাঙে, বা খুব ভোরে জেগে যান — বিশেষ করে গর্ভাবস্থার প্রথম ও শেষ তিন মাসে।"},"why":{"en":"Needing to pass urine often, heartburn, back pain, cramps, the baby moving, a big belly, vivid dreams and worries can all disturb sleep.","bn":"ঘন ঘন প্রস্রাবের বেগ, বুক জ্বালা, কোমর ব্যথা, পায়ে টান, শিশুর নড়াচড়া, বড় পেট, স্পষ্ট স্বপ্ন আর দুশ্চিন্তা — সবই ঘুম ভাঙাতে পারে।"},"normal":{"en":"Waking a few times a night to pass urine or change position, and feeling more tired during the day, are common in pregnancy.","bn":"রাতে কয়েকবার প্রস্রাবের জন্য বা পাশ ফিরতে জেগে ওঠা, আর দিনে বেশি ক্লান্ত লাগা — গর্ভাবস্থায় এগুলো সাধারণ।"},"do_now":{"en":["Lie on your side with a pillow between your knees and another under your bump or behind your back","Breathe slowly — in for a count of 4, out for a count of 6 — for a few minutes","If you cannot sleep after a while, get up, sit quietly in dim light, and go back to bed when sleepy"],"bn":["হাঁটুর মাঝে একটা বালিশ আর পেটের নিচে বা পিঠের পেছনে আরেকটা বালিশ দিয়ে কাত হয়ে শোন","কয়েক মিনিট ধীরে শ্বাস নিন — ৪ গুনে নিন, ৬ গুনে ছাড়ুন","অনেকক্ষণ ঘুম না এলে উঠে কম আলোয় চুপচাপ বসুন, ঘুম পেলে আবার শুতে যান"]},"steps":{"en":["Go to bed and get up at about the same time each day","Keep the room dark, quiet and airy, with a mosquito net","Put away phone and TV screens an hour before bed","Avoid tea, coffee and cola in the afternoon and evening","Eat dinner 2–3 hours before bed, with a small snack later if you are hungry","Drink most of your water earlier in the day, and less in the last hour before bed","Walk during the day; a short rest after lunch is fine, but keep it under an hour if nights are hard","Talk through your worries with your husband or someone you trust in the evening, not at midnight","From about 28 weeks, go to sleep on your side, not on your back"],"bn":["প্রতিদিন মোটামুটি একই সময়ে শুতে যান আর উঠুন","ঘর অন্ধকার, শান্ত ও খোলামেলা রাখুন, মশারি টানিয়ে নিন","শোয়ার এক ঘণ্টা আগে ফোন আর টিভি বন্ধ করুন","বিকেল ও সন্ধ্যায় চা, কফি ও কোলা এড়িয়ে চলুন","শোয়ার ২–৩ ঘণ্টা আগে রাতের খাবার খান; পরে খিদে পেলে হালকা কিছু","দিনের প্রথম ভাগে বেশি পানি পান করুন, শোয়ার আগের এক ঘণ্টায় কম","দিনে হাঁটুন; দুপুরে খাওয়ার পর অল্প বিশ্রাম ঠিক আছে, তবে রাতে ঘুমের সমস্যা হলে এক ঘণ্টার কম রাখুন","দুশ্চিন্তার কথা মাঝরাতে নয়, সন্ধ্যায় স্বামী বা বিশ্বস্ত কারো সাথে আলোচনা করুন","মোটামুটি ২৮ সপ্তাহ থেকে চিত হয়ে নয়, কাত হয়ে ঘুমাতে যান"]},"avoid":{"en":["Sleeping pills, allergy tablets or herbal sleep remedies without a doctor","Long naps late in the afternoon","Heavy, spicy meals at night"],"bn":["ডাক্তার ছাড়া ঘুমের ওষুধ, অ্যালার্জির ট্যাবলেট বা ভেষজ ঘুমের ওষুধ","বিকেলের শেষে লম্বা ঘুম","রাতে ভারী ও ঝাল খাবার"]},"example":{"en":"Lipi, 32 weeks pregnant, lay awake worrying about the birth. Her husband suggested they go over the birth plan together after dinner instead of at midnight. With an extra pillow under her bump, no phone after ten o''clock and a walk after lunch, she began falling asleep more easily.","bn":"৩২ সপ্তাহের অন্তঃসত্ত্বা লিপি প্রসবের দুশ্চিন্তায় জেগে থাকতেন। স্বামী বললেন, মাঝরাতে নয়, রাতের খাবারের পর দুজনে মিলে প্রসব পরিকল্পনাটা দেখে নেবেন। পেটের নিচে একটা বাড়তি বালিশ, রাত দশটার পর ফোন বন্ধ আর দুপুরে খাওয়ার পর একটু হাঁটা — এতে লিপির ঘুম আগের চেয়ে সহজে আসতে লাগল।"},"seek_help":{"en":["Poor sleep together with feeling low, hopeless or very anxious most days","Loud snoring with pauses in breathing or gasping, or feeling very sleepy in the day","An uncomfortable urge to move your legs at night (restless legs) — it can be linked to low iron"],"bn":["ঘুমের সমস্যার সাথে বেশিরভাগ দিন মন খারাপ, আশাহীন বা খুব উদ্বিগ্ন থাকা","জোরে নাক ডাকা, সাথে শ্বাস থেমে যাওয়া বা হাঁসফাঁস করা, কিংবা দিনে খুব ঘুম পাওয়া","রাতে পা নাড়ানোর অস্বস্তিকর তাড়না (রেস্টলেস লেগস) — আয়রনের ঘাটতির সাথে সম্পর্ক থাকতে পারে"]},"warning_signs":{"en":["Itching of the palms and soles, worse at night and without a rash — a liver condition of pregnancy that needs checking soon","Breathlessness when lying down, or chest pain","Severe headache, blurred vision or upper belly pain","Thoughts of harming yourself"],"bn":["হাতের তালু ও পায়ের তলায় চুলকানি, রাতে বেশি, কোনো র‍্যাশ ছাড়া — গর্ভাবস্থার একটি লিভারের সমস্যা, দ্রুত দেখানো দরকার","শুলে শ্বাসকষ্ট, বা বুকে ব্যথা","তীব্র মাথাব্যথা, ঝাপসা দেখা বা পেটের ওপরের দিকে ব্যথা","নিজের ক্ষতি করার চিন্তা"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['insomnia', 'sleep', 'tiredness', 'night waking', 'sleep position']::text[], false, 'in_review'::lp_review_status, 2036),
  ('pp-feeling-low-anxious', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🫂', '{"en":"Feeling low or anxious in pregnancy","bn":"গর্ভাবস্থায় মন খারাপ বা দুশ্চিন্তা"}'::jsonb, '{"en":"Feeling down or worried now and then is normal. If it lasts most days for two weeks or more, it is a health problem that can be treated.","bn":"মাঝে মাঝে মন খারাপ বা দুশ্চিন্তা হওয়া স্বাভাবিক। কিন্তু দুই সপ্তাহ বা তার বেশি সময় বেশিরভাগ দিন এমন থাকলে, এটা একটা স্বাস্থ্য সমস্যা — আর এর চিকিৎসা আছে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Some days you may feel tearful, irritable or worried, and that is common. Depression or anxiety is when these feelings last most of the day, on most days, for two weeks or more, and make it hard to cope.","bn":"কোনো কোনো দিন কান্না পাওয়া, খিটখিটে লাগা বা দুশ্চিন্তা হওয়া সাধারণ। বিষণ্ণতা বা উদ্বেগ তখন, যখন এই অনুভূতিগুলো দুই সপ্তাহ বা বেশি সময় ধরে বেশিরভাগ দিন, দিনের বেশিরভাগ সময় থাকে, আর সামলানো কঠিন হয়ে পড়ে।"},"why":{"en":"Hormones, tiredness, physical discomfort, money worries, a difficult past pregnancy, family pressure or conflict, and having little support can all play a part. It is not a weakness and it is not your fault.","bn":"হরমোন, ক্লান্তি, শারীরিক কষ্ট, টাকার দুশ্চিন্তা, আগের কঠিন গর্ভাবস্থা, পরিবারের চাপ বা কলহ, আর পাশে কাউকে না পাওয়া — সবকিছুরই ভূমিকা থাকতে পারে। এটা দুর্বলতা নয়, আপনার দোষও নয়।"},"normal":{"en":"Mood swings, worry about the baby''s health or the birth, and feeling overwhelmed at times are common in pregnancy — especially when the feelings pass and you can still enjoy some things.","bn":"হঠাৎ মন বদলানো, শিশুর স্বাস্থ্য বা প্রসব নিয়ে দুশ্চিন্তা, মাঝে মাঝে সব ভারী লাগা — গর্ভাবস্থায় এগুলো সাধারণ, বিশেষ করে যদি অনুভূতিগুলো কেটে যায় আর কিছু জিনিসে এখনো আনন্দ পান।"},"do_now":{"en":["Tell one person you trust how you really feel today","Take a short walk outside, or sit in fresh air","Breathe slowly — in for a count of 4, out for a count of 6 — for a few minutes","Eat something and drink some water","If you have thoughts of harming yourself, tell someone now and go to a hospital or call 999"],"bn":["আজই বিশ্বস্ত একজনকে বলুন, আসলে কেমন লাগছে","বাইরে একটু হেঁটে আসুন, বা খোলা বাতাসে বসুন","কয়েক মিনিট ধীরে শ্বাস নিন — ৪ গুনে নিন, ৬ গুনে ছাড়ুন","কিছু খান, একটু পানি পান করুন","নিজের ক্ষতি করার চিন্তা এলে এখনই কাউকে বলুন, হাসপাতালে যান বা ৯৯৯-এ ফোন করুন"]},"steps":{"en":["Tell your health worker how you have been feeling, at your next visit or sooner","Keep a simple routine: regular meals, sleep and a daily walk","Ask your husband and family for specific help: chores, time to rest, company at check-ups","Spend time with people who make you feel calm","Cut down on frightening news, stories and social media","Counselling helps many women; ask where it is available near you","If a doctor advises medicine, ask about safety in pregnancy — some options can be used"],"bn":["পরের চেকআপে, বা তার আগেই, স্বাস্থ্যকর্মীকে জানান কেমন লাগছে","সহজ একটা রুটিন রাখুন: সময়মতো খাওয়া, ঘুম আর প্রতিদিন একটু হাঁটা","স্বামী ও পরিবারের কাছে নির্দিষ্ট সাহায্য চান: ঘরের কাজ, বিশ্রামের সময়, চেকআপে সঙ্গ","যাঁদের সাথে থাকলে মন শান্ত হয়, তাঁদের সাথে সময় কাটান","ভয়ের খবর, গল্প আর সোশ্যাল মিডিয়া কমিয়ে দিন","কাউন্সেলিং অনেক মায়ের উপকারে আসে; কাছাকাছি কোথায় পাওয়া যায় জিজ্ঞেস করুন","ডাক্তার ওষুধ দিলে গর্ভাবস্থায় নিরাপদ কিনা জিজ্ঞেস করুন — কিছু ওষুধ ব্যবহার করা যায়"]},"avoid":{"en":["Hiding how you feel to look strong","Accepting ''just be happy'' as an answer — your feelings are real","Stopping prescribed medicines suddenly","Sleeping or calming pills from a pharmacy without a doctor"],"bn":["শক্ত দেখাতে নিজের অনুভূতি লুকিয়ে রাখা","''খুশি থাকো তো'' — এই কথাকেই সমাধান ভাবা; আপনার অনুভূতি সত্যি","লেখা ওষুধ হঠাৎ বন্ধ করা","ডাক্তার ছাড়া ফার্মেসি থেকে ঘুমের বা মন শান্ত করার ওষুধ"]},"example":{"en":"Since moving into her in-laws'' home, Ayesha, five months pregnant, cried most days and could not enjoy anything. Her husband noticed and asked gently. She told the doctor at her check-up, who referred her to a counsellor. Her husband began joining her for evening walks and asked his mother to let Ayesha rest after lunch. Over a few weeks, she felt more like herself again.","bn":"শ্বশুরবাড়িতে আসার পর থেকে পাঁচ মাসের অন্তঃসত্ত্বা আয়েশা প্রায় প্রতিদিন কাঁদতেন, কিছুতেই আনন্দ পেতেন না। স্বামী খেয়াল করে নরমভাবে জিজ্ঞেস করলেন। চেকআপে আয়েশা ডাক্তারকে বললেন, ডাক্তার তাঁকে একজন কাউন্সেলরের কাছে পাঠালেন। স্বামী সন্ধ্যায় তাঁর সাথে হাঁটতে যাওয়া শুরু করলেন, আর মাকে বললেন দুপুরে খাওয়ার পর আয়েশাকে বিশ্রাম নিতে দিতে। কয়েক সপ্তাহে আয়েশা আবার নিজের মতো বোধ করতে লাগলেন।"},"seek_help":{"en":["Low mood, hopelessness or loss of interest most days for two weeks or more","Constant worry, panic attacks, or fear that stops you doing everyday things","Not eating or sleeping because of how you feel","Feeling unsafe at home"],"bn":["দুই সপ্তাহ বা তার বেশি সময় বেশিরভাগ দিন মন খারাপ, আশাহীনতা বা কিছুতে আগ্রহ না থাকা","সারাক্ষণ দুশ্চিন্তা, হঠাৎ আতঙ্কের আক্রমণ, বা এমন ভয় যে দৈনন্দিন কাজ করতে পারছেন না","মনের অবস্থার কারণে খেতে বা ঘুমাতে না পারা","ঘরে নিজেকে নিরাপদ মনে না হওয়া"]},"warning_signs":{"en":["Thoughts of self-harm, of suicide, or that the family would be better off without you","Hearing or seeing things that others do not","Feeling unable to look after yourself"],"bn":["নিজের ক্ষতি করার, আত্মহত্যার, বা ''আমি না থাকলে সবাই ভালো থাকত'' — এমন চিন্তা","অন্যরা শোনে না বা দেখে না এমন কিছু শোনা বা দেখা","নিজের যত্ন নিতে না পারা"]}}'::jsonb, 3, -280, 0, '{}'::text[], 'any', ARRAY['depression', 'anxiety', 'low mood', 'worry', 'mental health', 'support']::text[], false, 'in_review'::lp_review_status, 2037),
  ('pp-early-contractions', 'scenario', 'scientific', 'shared', 'important', 'guideline', '⚠️', '{"en":"Contractions before 37 weeks","bn":"৩৭ সপ্তাহের আগে প্রসববেদনা"}'::jsonb, '{"en":"Regular tightening or period-like pain before 37 weeks may be early (preterm) labour. Go to hospital now — early treatment can help the baby.","bn":"৩৭ সপ্তাহের আগে নিয়মিত পেট শক্ত হওয়া বা মাসিকের মতো ব্যথা অকালপ্রসবের লক্ষণ হতে পারে। এখনই হাসপাতালে যান — আগেভাগে চিকিৎসা শিশুকে সাহায্য করে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Labour that starts before 37 weeks is called preterm labour. Signs include regular tightening of the belly, period-like cramps, a dull low backache, pressure in the pelvis, a change in vaginal discharge, a show, or fluid leaking.","bn":"৩৭ সপ্তাহের আগে প্রসব শুরু হলে তাকে অকালপ্রসব বলে। লক্ষণ: নিয়মিত পেট শক্ত হয়ে আসা, মাসিকের মতো ব্যথা, কোমরের নিচে চাপা ব্যথা, শ্রোণিতে চাপ, যোনিপথের স্রাবে পরিবর্তন, রক্তমেশানো শ্লেষ্মা, বা পানি বের হওয়া।"},"why":{"en":"Sometimes there is a cause, such as an infection, twins, too much fluid around the baby, high blood pressure or bleeding from the placenta; often no cause is found. Babies born early may need special care, and the earlier they are born, the more help they need.","bn":"কখনো কারণ থাকে — সংক্রমণ, যমজ, শিশুর চারপাশে বেশি পানি, উচ্চ রক্তচাপ বা গর্ভফুল থেকে রক্তক্ষরণ; প্রায়ই কোনো কারণ পাওয়া যায় না। আগে জন্মানো শিশুর বিশেষ যত্ন লাগতে পারে, আর যত আগে জন্ম, তত বেশি সাহায্য লাগে।"},"normal":{"en":"From mid-pregnancy, irregular, mostly painless tightening that comes and goes and eases with rest (Braxton Hicks) is the womb practising, and it is normal.","bn":"গর্ভাবস্থার মাঝামাঝি থেকে অনিয়মিত, প্রায় ব্যথাহীন পেট শক্ত হওয়া, যা আসে-যায় আর বিশ্রামে কমে (ব্র্যাক্সটন হিকস) — এটা জরায়ুর অনুশীলন, স্বাভাবিক।"},"do_now":{"en":["Go now to a hospital that can care for a small baby — do not wait","Take your antenatal card and reports","Call the transport and blood donors in your birth plan","If a big hospital is far away, go to the nearest facility; they will refer you if needed"],"bn":["ছোট শিশুর চিকিৎসা হয় এমন হাসপাতালে এখনই যান — অপেক্ষা করবেন না","গর্ভকালীন কার্ড ও রিপোর্ট সাথে নিন","প্রসব পরিকল্পনার যানবাহন আর রক্তদাতাদের খবর দিন","বড় হাসপাতাল দূরে হলে কাছের স্বাস্থ্যকেন্দ্রে যান; দরকারে তাঁরা রেফার করবেন"]},"steps":{"en":["At the hospital, the team will check you and the baby, and whether labour has really started","If birth is likely soon, they may give injections to help the baby''s lungs, and other medicines to protect the baby","If an infection is found, treating it may help","If it is not labour, you may go home with advice — come back at once if the signs return","Go over the signs again together, so you can act quickly next time"],"bn":["হাসপাতালে আপনাকে ও শিশুকে পরীক্ষা করা হবে, আর দেখা হবে সত্যিই প্রসব শুরু হয়েছে কিনা","শিগগির জন্মের সম্ভাবনা থাকলে শিশুর ফুসফুসের জন্য ইনজেকশন আর শিশুকে সুরক্ষা দিতে অন্য ওষুধ দেওয়া হতে পারে","সংক্রমণ পাওয়া গেলে তার চিকিৎসায় উপকার হতে পারে","প্রসববেদনা না হলে পরামর্শ দিয়ে বাড়ি পাঠানো হতে পারে — লক্ষণ ফিরে এলে সাথে সাথে আবার আসুন","দুজনে মিলে লক্ষণগুলো আবার ঝালিয়ে নিন, যাতে পরের বার দ্রুত ব্যবস্থা নিতে পারেন"]},"avoid":{"en":["Waiting overnight to see if the pains settle","Painkillers or injections from a pharmacy or village doctor","Pressing or massaging the belly","Long journeys in the last months without a plan for where to get care"],"bn":["ব্যথা কমে কিনা দেখতে রাতভর অপেক্ষা করা","ফার্মেসি বা গ্রাম্য ডাক্তারের ব্যথার ওষুধ বা ইনজেকশন","পেটে চাপ দেওয়া বা মালিশ করা","শেষের মাসগুলোতে কোথায় চিকিৎসা নেবেন তা ঠিক না করে দূরের যাত্রা"]},"example":{"en":"At 33 weeks, Mitu felt tightening every ten minutes and a backache that would not settle. Her husband called the CNG driver from their birth plan, and they went to the district hospital. The doctor gave injections to help the baby''s lungs. Her baby arrived a week later — small, but breathing well — and stayed a few days in the newborn unit.","bn":"৩৩ সপ্তাহে মিতুর প্রতি দশ মিনিট পরপর পেট শক্ত হচ্ছিল, আর কোমর ব্যথা কমছিল না। স্বামী প্রসব পরিকল্পনায় রাখা সিএনজি চালককে ফোন করলেন, তাঁরা জেলা সদর হাসপাতালে গেলেন। ডাক্তার শিশুর ফুসফুসের জন্য ইনজেকশন দিলেন। এক সপ্তাহ পর শিশুটি জন্মাল — ছোট, কিন্তু ভালোভাবে শ্বাস নিচ্ছিল — আর কয়েক দিন নবজাতক ইউনিটে থাকল।"},"seek_help":{"en":["Regular tightening, period-like pain or a low backache before 37 weeks","Pressure in the pelvis, or a feeling that the baby is pushing down","A change in vaginal discharge — watery, mucus-like or bloody"],"bn":["৩৭ সপ্তাহের আগে নিয়মিত পেট শক্ত হওয়া, মাসিকের মতো ব্যথা বা কোমরের নিচে ব্যথা","শ্রোণিতে চাপ, বা মনে হওয়া যে শিশু নিচের দিকে চাপ দিচ্ছে","যোনিপথের স্রাবে পরিবর্তন — পানির মতো, শ্লেষ্মার মতো বা রক্তমেশানো"]},"warning_signs":{"en":["Fluid leaking or gushing from the vagina","Bleeding","Fever, or a bad-smelling discharge","The baby moving less","Severe, constant belly pain"],"bn":["যোনিপথে পানি চুইয়ে পড়া বা হঠাৎ বের হওয়া","রক্তপাত","জ্বর, বা দুর্গন্ধযুক্ত স্রাব","শিশুর নড়াচড়া কমে যাওয়া","পেটে তীব্র, একটানা ব্যথা"]}}'::jsonb, 3, -140, -21, '{}'::text[], 'any', ARRAY['preterm labour', 'early contractions', 'premature birth', 'braxton hicks']::text[], false, 'in_review'::lp_review_status, 2038)
