INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('pp_couple_blood_tests', '{"en":"Do your blood tests together: thalassaemia and blood group","bn":"দুজনে মিলে রক্ত পরীক্ষা: থ্যালাসেমিয়া ও রক্তের গ্রুপ"}'::jsonb, '{"en":"Both partners do a CBC, a thalassaemia carrier test (haemoglobin electrophoresis) and blood group with Rh.","bn":"স্বামী-স্ত্রী দুজনেরই সিবিসি, থ্যালাসেমিয়া বাহক পরীক্ষা (হিমোগ্লোবিন ইলেকট্রোফোরেসিস) আর আরএইচসহ রক্তের গ্রুপ পরীক্ষা।"}'::jsonb, '{"en":"If both partners carry thalassaemia, each child has a 1 in 4 chance of the serious form. Knowing early, and knowing your blood groups, lets you plan safely.","bn":"দুজনই থ্যালাসেমিয়ার বাহক হলে প্রতিটি সন্তানের মারাত্মক ধরন হওয়ার সম্ভাবনা ৪ ভাগের ১ ভাগ। আগে জানলে, আর রক্তের গ্রুপ জানা থাকলে, নিরাপদে পরিকল্পনা করা যায়।"}'::jsonb, '{"en":"Peace of mind and informed choices before pregnancy.","bn":"মনের শান্তি, আর গর্ভধারণের আগে জেনে-বুঝে সিদ্ধান্ত।"}'::jsonb, '[{"en":"Ask your doctor for a CBC, Hb electrophoresis and blood group with Rh for both of you.","bn":"দুজনের জন্য সিবিসি, হিমোগ্লোবিন ইলেকট্রোফোরেসিস ও আরএইচসহ রক্তের গ্রুপ পরীক্ষা লিখে দিতে ডাক্তারকে বলুন।"},{"en":"Go together to give the samples.","bn":"নমুনা দিতে দুজনে একসাথে যান।"},{"en":"Show both reports to the doctor, and keep copies in your health folder.","bn":"দুজনের রিপোর্টই ডাক্তারকে দেখান, কপি স্বাস্থ্য ফাইলে রাখুন।"}]'::jsonb, '{"en":"Do not start iron tablets because of a low result until a doctor has read the reports; a carrier may not need iron.","bn":"রিপোর্টে কম দেখে ডাক্তার দেখার আগে আয়রন ট্যাবলেট শুরু করবেন না; বাহকের আয়রন না-ও লাগতে পারে।"}'::jsonb, 'recommended', 'once', 'shared', 'planning', NULL, NULL, 60, 20, '🩸', 'preconception_care', 'pp-thalassaemia-carrier-screening', 'nhs_conditions', 'any', 'in_review'::lp_review_status, 2039),
  ('pp_dental_check', '{"en":"Have a dental check-up before pregnancy","bn":"গর্ভধারণের আগে দাঁতের চেকআপ করান"}'::jsonb, '{}'::jsonb, '{"en":"Tooth decay and gum problems are easier to treat before pregnancy, and pregnancy hormones can make gums bleed more.","bn":"দাঁতের ক্ষয় আর মাড়ির সমস্যা গর্ভধারণের আগে সারানো সহজ; আর গর্ভাবস্থার হরমোনে মাড়ি থেকে বেশি রক্ত পড়তে পারে।"}'::jsonb, '{"en":"Healthy teeth and gums for the months ahead.","bn":"সামনের মাসগুলোর জন্য সুস্থ দাঁত ও মাড়ি।"}'::jsonb, '[{"en":"Book a visit to a dentist.","bn":"দাঁতের ডাক্তারের কাছে সময় নিন।"},{"en":"Tell the dentist you are planning a pregnancy.","bn":"জানান যে আপনি সন্তান নেওয়ার পরিকল্পনা করছেন।"},{"en":"Brush twice a day with fluoride toothpaste.","bn":"দিনে দুবার ফ্লোরাইডযুক্ত টুথপেস্ট দিয়ে দাঁত ব্রাশ করুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'once', 'mother', 'planning', NULL, NULL, 45, 10, '🦷', 'preconception_care', 'pp-preconception-checkup', 'who_oral_health', 'any', 'in_review'::lp_review_status, 2040),
  ('pp_tobacco_free_week', '{"en":"A week free of tobacco and betel nut","bn":"তামাক ও সুপারি ছাড়া এক সপ্তাহ"}'::jsonb, '{"en":"For anyone at home who smokes or chews jarda, gul or supari: stay free of it this week, and keep the home smoke-free.","bn":"বাড়িতে যিনি ধূমপান করেন বা জর্দা, গুল, সুপারি খান: এই সপ্তাহ এগুলো ছাড়া কাটান, আর ঘর ধোঁয়ামুক্ত রাখুন।"}'::jsonb, '{"en":"Tobacco in any form, and second-hand smoke, harm fertility and the growing baby. Stopping before pregnancy is best.","bn":"যেকোনো তামাক আর অন্যের ধোঁয়া উর্বরতা ও গর্ভের শিশুর ক্ষতি করে। গর্ভধারণের আগে ছাড়াই সবচেয়ে ভালো।"}'::jsonb, '{"en":"Better fertility, a safer pregnancy and a healthier home.","bn":"উর্বরতা বাড়ে, গর্ভাবস্থা নিরাপদ হয়, ঘর থাকে সুস্থ।"}'::jsonb, '[{"en":"Remove tobacco, gul and supari from the house.","bn":"বাসা থেকে তামাক, গুল ও সুপারি সরিয়ে ফেলুন।"},{"en":"Agree that no one smokes indoors.","bn":"ঠিক করুন, ঘরের ভেতর কেউ ধূমপান করবে না।"},{"en":"When a craving comes, drink water or take a short walk.","bn":"ইচ্ছা জাগলে পানি খান বা একটু হেঁটে আসুন।"},{"en":"Call 16263 or see a doctor if you need help quitting.","bn":"ছাড়তে সাহায্য লাগলে ১৬২৬৩-এ ফোন করুন বা ডাক্তার দেখান।"}]'::jsonb, '{}'::jsonb, 'recommended', 'weekly', 'shared', 'planning', NULL, NULL, 5, 15, '🚭', 'lifestyle', 'pp-quit-tobacco-betel', 'nhs_pregnancy_baby', 'any', 'in_review'::lp_review_status, 2041),
  ('pp_birth_savings_plan', '{"en":"Put money aside for pregnancy and birth","bn":"গর্ভাবস্থা ও প্রসবের জন্য টাকা জমান"}'::jsonb, '{}'::jsonb, '{"en":"Saving a little each month before pregnancy means check-ups, tests and the birth are covered without stress or delay.","bn":"গর্ভধারণের আগে থেকে প্রতি মাসে অল্প অল্প জমালে চেকআপ, পরীক্ষা আর প্রসবের খরচ দুশ্চিন্তা বা দেরি ছাড়াই মেটানো যায়।"}'::jsonb, '{"en":"Calm choices and no delay in care.","bn":"ঠান্ডা মাথায় সিদ্ধান্ত, চিকিৎসায় দেরি নয়।"}'::jsonb, '[{"en":"Agree on a monthly amount together.","bn":"দুজনে মিলে মাসিক একটা পরিমাণ ঠিক করুন।"},{"en":"Keep it in a separate account or mobile savings.","bn":"আলাদা অ্যাকাউন্ট বা মোবাইল সঞ্চয়ে রাখুন।"},{"en":"Use it only for health.","bn":"শুধু চিকিৎসার জন্য খরচ করুন।"}]'::jsonb, '{}'::jsonb, 'family', 'monthly', 'shared', 'planning', NULL, NULL, 10, 10, '💰', 'family_finance', 'pp-pregnancy-birth-budget', NULL, 'any', 'in_review'::lp_review_status, 2042),
  ('pp_daily_walk', '{"en":"Take a walk today","bn":"আজ একটু হাঁটুন"}'::jsonb, '{"en":"A gentle 20–30 minute walk, at a pace where you can still talk.","bn":"২০–৩০ মিনিট আরাম করে হাঁটা — এমন গতিতে, যাতে কথা বলতে পারেন।"}'::jsonb, '{"en":"Regular activity in pregnancy helps with back pain, constipation, sleep, mood and blood sugar.","bn":"গর্ভাবস্থায় নিয়মিত হাঁটাচলা কোমর ব্যথা, কোষ্ঠকাঠিন্য, ঘুম, মন আর রক্তে শর্করা — সবকিছুতে সাহায্য করে।"}'::jsonb, '{"en":"More energy, and a body that is ready for birth.","bn":"শরীরে বেশি শক্তি, আর প্রসবের জন্য তৈরি শরীর।"}'::jsonb, '[{"en":"Walk in the cooler part of the day.","bn":"দিনের ঠান্ডা সময়ে হাঁটুন।"},{"en":"Take water, and walk with someone if you can.","bn":"পানি সাথে নিন, সম্ভব হলে কাউকে সঙ্গে নিন।"}]'::jsonb, '{"en":"Stop and get help if you have bleeding, leaking fluid, dizziness, chest pain or painful tightening. If you have a complication, ask your doctor first.","bn":"রক্তপাত, পানি বের হওয়া, মাথা ঘোরা, বুকে ব্যথা বা ব্যথাসহ পেট শক্ত হলে থামুন ও সাহায্য নিন। কোনো জটিলতা থাকলে আগে ডাক্তারকে জিজ্ঞেস করুন।"}'::jsonb, 'recommended', 'daily', 'mother', 'pregnancy', -280, 0, 30, 5, '🚶‍♀️', 'lifestyle', 'pp-safe-activity-rest', 'who_activity_5_17', 'any', 'in_review'::lp_review_status, 2043),
  ('pp_td_vaccine', '{"en":"Get your Td vaccine doses","bn":"টিডি টিকার ডোজগুলো নিন"}'::jsonb, '{}'::jsonb, '{"en":"Td protects you and your newborn from tetanus; the baby is protected by the antibodies you pass on.","bn":"টিডি আপনাকে ও নবজাতককে ধনুষ্টংকার থেকে রক্ষা করে; আপনার শরীরের অ্যান্টিবডি শিশুকে সুরক্ষা দেয়।"}'::jsonb, '{"en":"Your baby is protected from newborn tetanus from the first day.","bn":"প্রথম দিন থেকেই শিশু নবজাতকের ধনুষ্টংকার থেকে সুরক্ষিত।"}'::jsonb, '[{"en":"Take your vaccination card to your next check-up or to an EPI centre.","bn":"পরের চেকআপে বা ইপিআই কেন্দ্রে টিকা কার্ড নিয়ে যান।"},{"en":"Ask how many doses you need in this pregnancy.","bn":"এই গর্ভাবস্থায় কয়টি ডোজ লাগবে জিজ্ঞেস করুন।"},{"en":"Note the date of the next dose, and finish at least two weeks before your due date.","bn":"পরের ডোজের তারিখ লিখে রাখুন, আর প্রসবের সম্ভাব্য তারিখের অন্তত দুই সপ্তাহ আগে শেষ করুন।"}]'::jsonb, '{"en":"A sore arm or mild fever for a day is common. Seek care for a high fever or an arm that is very swollen, hot and painful.","bn":"এক দিনের জন্য বাহুতে ব্যথা বা হালকা জ্বর সাধারণ। বেশি জ্বর, বা বাহু খুব ফুলে গরম ও ব্যথা হলে চিকিৎসা নিন।"}'::jsonb, 'must_do', 'once', 'mother', 'pregnancy', -280, -14, 60, 20, '💉', 'vaccination', 'pp-td-vaccine', 'dghs_epi', 'any', 'in_review'::lp_review_status, 2044),
  ('pp_glucose_test', '{"en":"Do the glucose test (24–28 weeks)","bn":"গ্লুকোজ পরীক্ষা করান (২৪–২৮ সপ্তাহ)"}'::jsonb, '{}'::jsonb, '{"en":"Gestational diabetes usually has no symptoms. The test finds it so it can be controlled, protecting you and the baby.","bn":"গর্ভকালীন ডায়াবেটিসে সাধারণত কোনো উপসর্গ থাকে না। পরীক্ষায় ধরা পড়লে নিয়ন্ত্রণ করা যায়, আপনি আর শিশু দুজনেই সুরক্ষিত থাকেন।"}'::jsonb, '{"en":"Early treatment and a safer birth.","bn":"আগেভাগে চিকিৎসা, আর নিরাপদ প্রসব।"}'::jsonb, '[{"en":"Ask your doctor for the test and the instructions.","bn":"ডাক্তারের কাছ থেকে পরীক্ষা আর নিয়মকানুন জেনে নিন।"},{"en":"Come fasting from the night before, as instructed.","bn":"নির্দেশমতো আগের রাত থেকে খালি পেটে আসুন।"},{"en":"Bring something to eat after the last blood sample.","bn":"শেষ রক্ত নেওয়ার পর খাওয়ার জন্য কিছু সাথে আনুন।"},{"en":"Show the result to your doctor.","bn":"ফলাফল ডাক্তারকে দেখান।"}]'::jsonb, '{"en":"Some women are tested earlier in pregnancy; follow your doctor''s advice.","bn":"কারো কারো আরও আগে পরীক্ষা করা হয়; ডাক্তারের পরামর্শ মেনে চলুন।"}'::jsonb, 'recommended', 'once', 'mother', 'pregnancy', -112, -84, 150, 15, '🧪', 'antenatal_care', 'pp-gestational-diabetes-pre-eclampsia', 'who_anc_2016', 'any', 'in_review'::lp_review_status, 2045),
  ('pp_choose_birth_facility', '{"en":"Choose where you will give birth","bn":"কোথায় প্রসব করাবেন ঠিক করুন"}'::jsonb, '{}'::jsonb, '{"en":"Choosing in the middle months gives you time to compare, visit and plan transport, instead of deciding during labour.","bn":"মাঝের মাসগুলোতে ঠিক করলে তুলনা করা, ঘুরে দেখা আর যানবাহনের পরিকল্পনার সময় পাওয়া যায় — প্রসববেদনার মধ্যে সিদ্ধান্ত নিতে হয় না।"}'::jsonb, '{"en":"You know exactly where to go.","bn":"কোথায় যেতে হবে, ঠিক জানা থাকে।"}'::jsonb, '[{"en":"List two facilities with a skilled birth attendant, including one that can do a caesarean.","bn":"দক্ষ প্রসব সহায়তাকারী আছে এমন দুটি জায়গার তালিকা করুন, যার একটিতে সিজার করা যায়।"},{"en":"Ask about cost, 24-hour staff, blood and newborn care.","bn":"খরচ, ২৪ ঘণ্টার কর্মী, রক্ত আর নবজাতকের চিকিৎসার কথা জিজ্ঞেস করুন।"},{"en":"Visit the one you choose, together.","bn":"বেছে নেওয়া জায়গাটা দুজনে একবার ঘুরে আসুন।"},{"en":"Save its phone number.","bn":"সেখানকার ফোন নম্বর সেভ করুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'once', 'shared', 'pregnancy', -189, -84, 60, 20, '🏥', 'birth_preparation', 'pp-choosing-birth-place', 'who_anc_2016', 'any', 'in_review'::lp_review_status, 2046),
  ('pp_birth_fund', '{"en":"Add to the birth and emergency fund","bn":"প্রসব ও জরুরি তহবিলে টাকা যোগ করুন"}'::jsonb, '{}'::jsonb, '{"en":"Money ready for the birth and for any emergency means no delay when care is needed.","bn":"প্রসব আর যেকোনো জরুরি অবস্থার টাকা হাতে থাকলে চিকিৎসার দরকারে দেরি হয় না।"}'::jsonb, '{"en":"No last-minute rush for money.","bn":"শেষ মুহূর্তে টাকার জন্য ছোটাছুটি নেই।"}'::jsonb, '[{"en":"Add this month''s amount.","bn":"এই মাসের টাকা যোগ করুন।"},{"en":"Check the total against your budget list.","bn":"খরচের তালিকার সাথে মোট টাকা মিলিয়ে দেখুন।"},{"en":"Make sure someone can withdraw it at any hour.","bn":"যেকোনো সময় কেউ যেন টাকা তুলতে পারেন, নিশ্চিত করুন।"}]'::jsonb, '{}'::jsonb, 'family', 'monthly', 'shared', 'pregnancy', -280, 0, 10, 10, '🏦', 'family_finance', 'pp-pregnancy-birth-budget', NULL, 'any', 'in_review'::lp_review_status, 2047),
  ('pp_father_attends_checkup', '{"en":"Go with her to a check-up","bn":"স্ত্রীর সাথে চেকআপে যান"}'::jsonb, '{}'::jsonb, '{"en":"When fathers attend check-ups, they understand the pregnancy, know the danger signs and can act fast in an emergency.","bn":"বাবারা চেকআপে গেলে গর্ভাবস্থা ভালো বোঝেন, বিপদচিহ্ন জানেন, আর জরুরি অবস্থায় দ্রুত ব্যবস্থা নিতে পারেন।"}'::jsonb, '{"en":"She feels supported, and you feel part of it.","bn":"তিনি ভরসা পান, আর আপনিও এই যাত্রার অংশ হন।"}'::jsonb, '[{"en":"Arrange leave or time off in advance.","bn":"আগে থেকে ছুটির ব্যবস্থা করুন।"},{"en":"Write down your own questions.","bn":"নিজের প্রশ্নগুলো লিখে নিন।"},{"en":"Ask the doctor what to watch for before the next visit.","bn":"পরের চেকআপের আগে কী খেয়াল রাখতে হবে, ডাক্তারকে জিজ্ঞেস করুন।"}]'::jsonb, '{}'::jsonb, 'family', 'monthly', 'father', 'pregnancy', -280, 0, 120, 15, '👨', 'fatherhood', 'pp-father-role-pregnancy', NULL, 'any', 'in_review'::lp_review_status, 2048),
  ('pp_side_rest', '{"en":"Rest on your side for a while today","bn":"আজ কিছুক্ষণ কাত হয়ে বিশ্রাম নিন"}'::jsonb, '{"en":"Lie down on your side — many women find the left side comfortable — for a short rest, with your feet up if they are swollen.","bn":"কিছুক্ষণ কাত হয়ে শুয়ে বিশ্রাম নিন — অনেকে বাঁ কাতে আরাম পান — পা ফুললে পা একটু উঁচু করে রাখুন।"}'::jsonb, '{"en":"In the last months, lying on your side rather than your back keeps blood flowing well to the baby and eases swelling and backache. Going to sleep on your side is advised from about 28 weeks.","bn":"শেষের মাসগুলোতে চিত না হয়ে কাত হয়ে শুলে শিশুর কাছে রক্ত ভালোভাবে পৌঁছায়, পা ফোলা আর কোমর ব্যথাও কমে। মোটামুটি ২৮ সপ্তাহ থেকে কাত হয়ে ঘুমাতে যাওয়ার পরামর্শ দেওয়া হয়।"}'::jsonb, '{"en":"Less swelling and tiredness, and good blood flow to your baby.","bn":"ফোলা ও ক্লান্তি কম, আর শিশুর কাছে ভালো রক্তপ্রবাহ।"}'::jsonb, '[{"en":"Put a pillow between your knees and another under your bump.","bn":"হাঁটুর মাঝে একটা আর পেটের নিচে আরেকটা বালিশ দিন।"},{"en":"Ask family to take over a chore while you rest.","bn":"বিশ্রামের সময় পরিবারের কাউকে একটা কাজ সামলে নিতে বলুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'mother', 'pregnancy', -84, 0, 30, 5, '🛏️', 'sleep', 'pp-safe-activity-rest', 'nhs_pregnancy_baby', 'any', 'in_review'::lp_review_status, 2049)
